-- ======================================================================
-- 20260914195000_placed.sql
-- ======================================================================

-- Things set down on the ground, and the fires in them.
--
-- ## One table, not nine
--
-- A campfire, a smelter, a kiln, an anvil, a crate and a loom are the same
-- shape: somewhere on a tile, a footprint in subtiles, a quality, and for the
-- ones that burn, fuel and ash. Nine tables would mean nine of every function
-- that asks "is there one of those near me", which is the question this whole
-- file exists to answer.
--
-- ## Fire on the wall clock
--
-- Nothing ticks here, fires included. `fuel` is what was in it at the moment
-- `since` was stamped; a lit thing has burned the seconds since off that, and
-- made ash at a fixed rate the whole while. Both are worked out on reading,
-- and written back whenever anything touches it — the same settle-on-touch the
-- actions use, for the same reason: there is nowhere in Supabase to put a loop,
-- and a fire that only burns while somebody is watching is not a fire.

create table if not exists placed (
  id bigint primary key generated always as identity,
  world_id uuid not null references world on delete cascade,
  /** campfire, smelter, kiln, furniture, anvil, crate, post */
  kind text not null,
  /** Which sort of furniture, when that is the kind. */
  sub text,
  x int not null,
  y int not null,
  /** Top-left subtile of its footprint, 0..3. */
  sx int not null default 0,
  sy int not null default 0,
  /** Where its middle is, in tiles: what "near enough to use" is measured to. */
  cx double precision not null,
  cy double precision not null,
  ql real not null default 20,
  fuel real not null default 0,
  ash real not null default 0,
  lit boolean not null default false,
  /** When `fuel` and `ash` were last true. */
  since timestamptz not null default now(),
  state jsonb not null default '{}',
  made_by uuid,
  made_at timestamptz not null default now()
);

create index if not exists placed_on_island on placed (world_id, kind);
create index if not exists placed_near on placed (world_id, x, y);

alter table placed enable row level security;
drop policy if exists placed_read on placed;
create policy placed_read on placed for select to authenticated using (true);
grant select on placed to authenticated;
revoke insert, update, delete on placed from anon, authenticated;

/** Four subtiles to a tile, each way. */
create or replace function subtiles() returns int language sql immutable as $$ select 4 $$;

/** What a thing of this sort takes up, in subtiles. */
create or replace function placed_size(p_kind text, p_sub text) returns int[] language sql stable as $$
  select case p_kind
    when 'campfire' then array[2, 2]
    when 'smelter' then array[3, 2]
    when 'kiln' then array[2, 2]
    when 'anvil' then array[2, 2]
    when 'furniture' then coalesce((select array[w, h] from furniture_def where id = p_sub), array[1, 1])
    else array[1, 1] end
$$;

/** Seconds of burning left in it, now rather than when it was last looked at. */
create or replace function placed_fuel(p placed) returns double precision language sql stable as $$
  select case when p.lit
    then greatest(0, p.fuel - extract(epoch from (now() - p.since)))
    else p.fuel end
$$;

/**
 * Ashes built up, now. A fire makes one lot every two minutes it burns, and
 * stops making them when the fuel runs out rather than when somebody notices.
 */
create or replace function placed_ash(p placed) returns double precision language sql stable as $$
  select case when p.lit
    then p.ash + least(p.fuel, extract(epoch from (now() - p.since))) / 120
    else p.ash end
$$;

create or replace function placed_lit(p placed) returns boolean language sql stable as $$
  select p.lit and placed_fuel(p) > 0
$$;

/**
 * Bring a fire up to date and say whether it went out while nobody was there.
 * Called before anything reads or changes one, so that what is written down is
 * always what is true at the moment it is written.
 */
create or replace function placed_settle(p_id bigint) returns void language plpgsql as $$
declare p placed; f double precision; a double precision;
begin
  select * into p from placed where id = p_id for update;
  if not found or not p.lit then return; end if;
  f := placed_fuel(p);
  a := placed_ash(p);
  update placed set fuel = f, ash = a, lit = (f > 0), since = now() where id = p_id;
end $$;

/** Everything of a kind within reach of somebody, nearest first. */
create or replace function placed_near(p_world uuid, p_uid uuid, p_kind text, p_sub text default null,
                                       p_range double precision default 2.4)
  returns setof placed language sql stable as $$
  select pl.* from placed pl, player py
  where pl.world_id = p_world and py.world_id = p_world and py.uid = p_uid
    and pl.kind = p_kind and (p_sub is null or pl.sub = p_sub)
    and sqrt(power(pl.cx - py.x, 2) + power(pl.cy - py.y, 2)) <= p_range
  order by sqrt(power(pl.cx - py.x, 2) + power(pl.cy - py.y, 2))
$$;

/**
 * Whether you are standing at the thing a recipe needs.
 *
 * A cooking fire is a lit campfire or a lit oven — an oven holds its heat more
 * evenly, which is why the two are not quite the same thing elsewhere, but for
 * the purpose of "can this be cooked here" they are. Everything else is a
 * piece of furniture of the right sort within arm's reach.
 */
create or replace function at_station(p_world uuid, p_uid uuid, p_station text)
  returns boolean language sql stable as $$
  select case p_station
    when 'campfire' then
      exists (select 1 from placed_near(p_world, p_uid, 'campfire', null, 2.6) p where placed_lit(p))
      or exists (select 1 from placed_near(p_world, p_uid, 'furniture', null, 2.6) p
                 join furniture_def d on d.id = p.sub where d.hearth and placed_lit(p))
    when 'smelter' then
      exists (select 1 from placed_near(p_world, p_uid, 'smelter', null, 2.6) p where placed_lit(p))
    else
      exists (select 1 from placed_near(p_world, p_uid, 'furniture', p_station, 2.4))
    end
$$;

/** Seconds of burning each thing is worth. Fires take wood and coal, nothing else. */
create or replace function fuel_value(p_item text) returns double precision language sql immutable as $$
  select case p_item
    when 'shaft' then 90 when 'thatch' then 60 when 'plank' then 120
    when 'timber' then 240 when 'log' then 600 when 'coal' then 900 end
$$;

/** Most a fire holds: an hour of burning. */
create or replace function fire_capacity() returns double precision language sql immutable as $$ select 3600 $$;

create or replace function burns_for(p_fuel double precision) returns text language sql immutable as $$
  select case
    when round(p_fuel / 60) >= 60 then to_char(p_fuel / 3600, 'FM990.0') || ' hours'
    when round(p_fuel / 60) >= 1 then round(p_fuel / 60) || ' minutes'
    else round(p_fuel) || ' seconds' end
$$;

select private.lock_doors();

-- ======================================================================
-- 20260914195100_fires.sql
-- ======================================================================

-- Laying a fire, lighting it, feeding it, and raking it out.
--
-- Ported from src/game/campfire.ts and src/game/smelter.ts. The smelter is
-- carried and set down; the campfire is built where it stands out of two
-- shafts, which is why one has a `place_` action and the other a `build_`.

/**
 * Reach to a thing on the ground is measured to its middle, not to the tile it
 * was dropped on: a smelter is three subtiles wide and you can stand at either
 * end of it. `in_reach` cannot do this — it is immutable and knows nothing of
 * the island — so anything aimed at a placed thing is measured here instead.
 */
create or replace function placed_in_reach(p_world uuid, p_uid uuid, p_id bigint, p_range double precision default 2.4)
  returns boolean language sql stable as $$
  select exists (
    select 1 from placed pl, player py
    where pl.id = p_id and pl.world_id = p_world and py.world_id = p_world and py.uid = p_uid
      and sqrt(power(pl.cx - py.x, 2) + power(pl.cy - py.y, 2)) <= p_range)
$$;

/** The thing an action is aimed at, when it is aimed at something on the ground. */
create or replace function target_placed(p_world uuid, p_target jsonb) returns placed language sql stable as $$
  select * from placed where world_id = p_world and id = nullif(p_target->>'id', '')::bigint
$$;

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

/** What the fire actions refuse, and why. */
create or replace function fire_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare p placed; it item; n int; sub text;
begin
  if p_action = 'build_campfire' then
    if p_target->>'sx' is null or p_target->>'sy' is null then return 'Choose a spot.'; end if;
    if pack_count(p_world, p_uid, 'shaft') < 2 then return 'A campfire takes 2 shafts.'; end if;
    return null;
  end if;

  if p_action in ('place_smelter', 'place_furniture') then
    select * into it from item
      where id = nullif(p_target->>'uid', '')::bigint and world_id = p_world
        and holder = 'player' and holder_uid = p_uid;
    if not found then return 'You are not carrying that.'; end if;
    if p_action = 'place_smelter' and it.def <> 'smelter' then return 'That is not a smelter.'; end if;
    if p_action = 'place_furniture' then
      sub := replace(it.def, 'furniture_', '');
      if not exists (select 1 from furniture_def where id = sub) then return 'That is not something you can set down.'; end if;
    end if;
    return null;
  end if;

  p := target_placed(p_world, p_target);
  if p.id is null then return 'It is gone.'; end if;
  if not placed_in_reach(p_world, p_uid, p.id) then
    return 'Stand next to the ' || coalesce(p.sub, p.kind) || '.';
  end if;

  if p_action in ('light_campfire', 'light_smelter') then
    if placed_lit(p) then return 'It is already burning.'; end if;
    if placed_fuel(p) <= 0 then return 'There is nothing left to burn. Feed it some wood.'; end if;
  elsif p_action in ('put_out_campfire', 'damp_smelter') then
    if not placed_lit(p) then return 'It is not burning.'; end if;
  elsif p_action in ('fuel_campfire', 'fuel_smelter') then
    select * into it from item
      where world_id = p_world and holder = 'player' and holder_uid = p_uid
        and (id = nullif(p_target->>'uid', '')::bigint or fuel_value(def) is not null)
      order by (id = nullif(p_target->>'uid', '')::bigint) desc limit 1;
    if not found or fuel_value(it.def) is null then
      return 'Fires take wood and coal: shafts, thatch, planks, timbers, logs or coal.';
    end if;
    if placed_fuel(p) >= fire_capacity() then return 'It is already piled as high as it will take.'; end if;
  elsif p_action in ('take_ashes_fire', 'take_ashes_smelter') then
    if floor(placed_ash(p)) < 1 then return 'There are no ashes worth taking yet.'; end if;
  elsif p_action in ('take_apart_campfire', 'pick_up_smelter', 'pick_up_furniture') then
    if placed_lit(p) then return 'Put it out first.'; end if;
  end if;
  return null;
end $$;

/** And what they do. */
create or replace function perform_fire(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare p placed; it item; sz int[]; ax int; ay int; per double precision; room double precision;
        fits int; whole int; sub text; made bigint; back text;
begin
  if p_action = 'build_campfire' then
    ax := least(subtiles() - 2, greatest(0, (p_target->>'sx')::int));
    ay := least(subtiles() - 2, greatest(0, (p_target->>'sy')::int));
    if not consume(p_world, p_uid, 'shaft', 2) then return; end if;
    values (p_world, 'campfire', (p_target->>'x')::int, (p_target->>'y')::int, ax, ay,
            (p_target->>'x')::int + (ax + 1.0) / subtiles(), (p_target->>'y')::int + (ay + 1.0) / subtiles(),
            120, p_uid);
    perform tell(p_world, p_uid, 'You lay a campfire from 2 shafts. Light it, or feed it more wood first.', 'event');
    perform land_announce(p_world, (p_target->>'x')::int, (p_target->>'y')::int);
    return;
  end if;

  if p_action in ('place_smelter', 'place_furniture') then
    select * into it from item where id = nullif(p_target->>'uid', '')::bigint;
    sub := case when p_action = 'place_furniture' then replace(it.def, 'furniture_', '') end;
    sz := placed_size(case when p_action = 'place_smelter' then 'smelter' else 'furniture' end, sub);
    ax := least(subtiles() - sz[1], greatest(0, coalesce((p_target->>'sx')::int, 0)));
    ay := least(subtiles() - sz[2], greatest(0, coalesce((p_target->>'sy')::int, 0)));
    values (p_world, case when p_action = 'place_smelter' then 'smelter' else 'furniture' end, sub,
            (p_target->>'x')::int, (p_target->>'y')::int, ax, ay,
            (p_target->>'x')::int + (ax + sz[1] / 2.0) / subtiles(),
            (p_target->>'y')::int + (ay + sz[2] / 2.0) / subtiles(),
            it.ql, p_uid)
    returning id into made;
    delete from item where id = it.id;
    perform tell(p_world, p_uid, 'You set the ' ||
      lower(coalesce((select name from furniture_def where id = sub), 'smelter')) || ' down.', 'event');
    perform land_announce(p_world, (p_target->>'x')::int, (p_target->>'y')::int);
    return;
  end if;

  perform placed_settle(nullif(p_target->>'id', '')::bigint);
  p := target_placed(p_world, p_target);
  if p.id is null then return; end if;

  if p_action in ('light_campfire', 'light_smelter') then
    update placed set lit = true, since = now() where id = p.id;
    perform tell(p_world, p_uid, 'The kindling catches and the ' || p.kind || ' burns. It has '
      || burns_for(p.fuel) || ' of fuel.', 'event');
  elsif p_action in ('put_out_campfire', 'damp_smelter') then
    update placed set lit = false, since = now() where id = p.id;
    perform tell(p_world, p_uid, 'You smother the fire. The wood is saved for later.', 'event');
  elsif p_action in ('fuel_campfire', 'fuel_smelter') then
    select * into it from item
      where world_id = p_world and holder = 'player' and holder_uid = p_uid
        and (id = nullif(p_target->>'uid', '')::bigint or fuel_value(def) is not null)
      order by (id = nullif(p_target->>'uid', '')::bigint) desc limit 1;
    per := fuel_value(it.def);
    room := greatest(0, fire_capacity() - p.fuel);
    fits := greatest(1, least(it.count, ceil(room / per)::int));
    if not consume(p_world, p_uid, it.def, fits, it.id) then return; end if;
    update placed set fuel = least(fire_capacity(), p.fuel + per * fits), since = now() where id = p.id;
    perform tell(p_world, p_uid, 'You feed ' || case when fits > 1 then fits || ' × ' else 'a ' end
      || lower((select name from item_def where id = it.def)) || ' to the fire. '
      || burns_for(least(fire_capacity(), p.fuel + per * fits)) || ' of fuel.', 'event');
  elsif p_action in ('take_ashes_fire', 'take_ashes_smelter') then
    whole := floor(p.ash)::int;
    update placed set ash = p.ash - whole, since = now() where id = p.id;
    perform give(p_world, p_uid, 'ash', whole, 20);
    perform tell(p_world, p_uid, 'You rake ' || whole || case when whole = 1 then ' lot' else ' lots' end
      || ' of ashes out of the ' || p.kind || '. (QL 20)', 'event');
  elsif p_action = 'take_apart_campfire' then
    -- Coal burns but is never got back, so a pile of logs cannot be turned
    -- into coal by rebuilding the fire.
    delete from placed where id = p.id;
    perform give(p_world, p_uid, 'shaft', 2, 20);
    perform tell(p_world, p_uid, 'You take the campfire apart and save what will burn again.', 'event');
    perform land_announce(p_world, p.x, p.y);
  elsif p_action in ('pick_up_smelter', 'pick_up_furniture') then
    back := case when p.kind = 'smelter' then 'smelter' else 'furniture_' || p.sub end;
    delete from placed where id = p.id;
    perform give(p_world, p_uid, back, 1, p.ql);
    perform tell(p_world, p_uid, 'You take up the ' || lower(coalesce(p.sub, p.kind)) || '.', 'event');
    perform land_announce(p_world, p.x, p.y);
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914195200_dispatch2.sql
-- ======================================================================

-- The dispatcher, now that there are things on the ground to aim at.

create or replace function act_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare d action_def; p player; cx int; cy int; tx int; ty int; t tile_def; aimed text;
begin
  select * into d from action_def where id = p_action;
  if not found then return 'There is no such thing as ' || p_action || '.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  -- Deliberately not "are you busy": this is asked of the next go in a queue
  -- as well as the first. Being busy is `rpc_act`'s business.
  if not act_ported(p_action) then
    return 'You cannot ' || lower(d.label) || ' on this island yet.';
  end if;

  aimed := p_target->>'kind';
  /*
   * Reach to a thing on the ground is measured to its middle rather than to
   * the tile it sits on, and `fire_refusal` does that itself — a smelter is
   * three subtiles wide and you may stand at either end of it.
   */
  if aimed in ('campfire', 'smelter', 'kiln', 'furniture', 'anvil') or p_action like 'place_%' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
  if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
    return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
  end if;
  if p_action = 'build_campfire' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;

  if exists (select 1 from recipe where id = p_action) then
    return craft_refusal(p_world, p_uid, p_action, nullif(p_target->>'uid', '')::bigint);
  end if;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    if t.dig_yield is null then return 'You cannot dig that.'; end if;
    if land_height(p_world, cx, cy) <= 0 then return 'You cannot dig below the water level.'; end if;
    if land_dirt(p_world, cx, cy) <= 0 then
      return 'That corner is bare rock. Only a pickaxe will take it lower.';
    end if;
  end if;
  return null;
end $$;

create or replace function act_perform(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tq double precision; s double precision; cx int; cy int; tx int; ty int;
        t tile_def; left_dirt int; made_ql double precision; yield text; gained double precision; tool_id bigint;
begin
  if p_action like 'build\_%' or p_action like 'place\_%' or p_action like 'pick\_up\_%'
     or p_action like 'light\_%' or p_action like 'fuel\_%' or p_action like 'put\_out\_%'
     or p_action like 'damp\_%' or p_action like 'take\_ashes\_%' or p_action like 'take\_apart\_%' then
    perform perform_fire(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if exists (select 1 from recipe where id = p_action) then
    perform perform_craft(p_world, p_uid, p_action, p_target);
    return;
  end if;

  select * into d from action_def where id = p_action;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    select i.id into tool_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = d.tool
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'You fail to dig anything useful.', 'event');
      return;
    end if;
    perform land_set_height(p_world, cx, cy, land_height(p_world, cx, cy) - 1);
    left_dirt := land_dirt(p_world, cx, cy) - 1;
    perform land_set_dirt(p_world, cx, cy, left_dirt);
    if t.turns_to_dirt then perform land_set_tile(p_world, tx, ty, 1); end if;
    perform land_announce(p_world, tx, ty);
    if left_dirt <= 0 then
      perform tell(p_world, p_uid, 'Your shovel grates on bare rock.', 'event');
    end if;
    yield := coalesce(t.dig_yield, 'dirt');
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yield, 1, made_ql);
    gained := skill_raise(p_world, p_uid, d.skill, 1);
    perform tell(p_world, p_uid,
      'You dig up some ' || lower((select name from item_def where id = yield)) ||
      '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    if gained > 0 then
      perform tell(p_world, p_uid, 'Digging increased by ' || to_char(gained, 'FM0.0000') ||
        ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
    end if;
  end if;
end $$;

select private.lock_doors();

