-- ======================================================================
-- 20260914200400_gather.sql
-- ======================================================================

-- Taking what the island grows: felling, foraging, botanizing, and filling a
-- shovel off a bed of something.

/**
 * Where has been picked over lately.
 *
 * A row per spot per kind, and "picked clean" is simply whether it was written
 * recently — three minutes, on the wall clock, like everything else. No timer
 * clears these; an old row is just an old row, and the sweep tidies them away
 * when it has nothing better to do.
 */
create table if not exists foraged (
  world_id uuid not null references world on delete cascade,
  x int not null,
  y int not null,
  kind text not null,
  at timestamptz not null default now(),
  primary key (world_id, x, y, kind)
);
alter table foraged enable row level security;
drop policy if exists foraged_read on foraged;
create policy foraged_read on foraged for select to authenticated using (true);
grant select on foraged to authenticated;
revoke insert, update, delete on foraged from anon, authenticated;

create or replace function forage_cooldown() returns double precision language sql immutable as $$ select 180 $$;

create or replace function is_foraged(p_world uuid, p_x int, p_y int, p_kind text)
  returns boolean language sql stable as $$
  select exists (select 1 from foraged
    where world_id = p_world and x = p_x and y = p_y and kind = p_kind
      and now() - at < make_interval(secs => forage_cooldown()))
$$;

create or replace function mark_foraged(p_world uuid, p_x int, p_y int, p_kind text)
  returns void language sql as $$
  on conflict (world_id, x, y, kind) do update set at = now()
$$;

/** What stands on a tile: species in the low four bits, age in the next two. */
create or replace function tree_species(p_data int) returns int language sql immutable as $$
  select least((select max(id) from tree_def), p_data & 15)
$$;
create or replace function tree_age(p_data int) returns int language sql immutable as $$
  select least(2, (p_data >> 4) & 3)
$$;
create or replace function bush_species(p_data int) returns int language sql immutable as $$
  select least((select max(id) from bush_def), p_data & 15)
$$;

/**
 * One draw from a weighted table.
 *
 * Takes the roll as an argument rather than rolling inside, so that a caller
 * making several passes over the same ground gets several different answers
 * and not one answer several times.
 */
create or replace function roll_table(p_table text, p_roll double precision) returns text
  language sql stable as $$
  select item from (
    select item, sum(weight) over (order by weight desc, item) as upto,
           sum(weight) over () as total
    from loot_table where id = p_table
  ) q where upto >= p_roll * total order by upto limit 1
$$;

/**
 * How many times a tile is searched in one go. Skill does not only make a find
 * likelier, it makes a second and a third look worth taking: one more pass for
 * every twenty points.
 */
create or replace function rolls_at(p_skill double precision) returns int language sql immutable as $$
  select 1 + floor(greatest(0, p_skill) / 20)::int
$$;

/** "a, b and c", for saying what a handful of passes turned up. */
create or replace function list_of(p_parts text[]) returns text language sql immutable as $$
  select case when array_length(p_parts, 1) <= 1 then coalesce(p_parts[1], '')
    else array_to_string(p_parts[1:array_length(p_parts,1)-1], ', ') || ' and ' || p_parts[array_length(p_parts,1)]
    end
$$;

select private.lock_doors();

-- ======================================================================
-- 20260914200500_gather_acts.sql
-- ======================================================================

-- Felling, foraging, botanizing, and filling a shovel off a bed.

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

/**
 * A tile's number, by its name.
 *
 * The numbers are storage — a tile is written down as one, so the list may
 * only be appended to — but they are a poor thing to hand-write. `Tree` was
 * typed as 3 here, which is Sand, and cutting down a tree became cutting down
 * a beach. Looked up, it cannot be got wrong.
 */
create or replace function tile_id(p_name text) returns int language sql stable as $$
  select id from tile_def where name = p_name
$$;

create or replace function gather_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare tx int; ty int; here int; t tile_def;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  here := land_tile(p_world, tx, ty);
  select * into t from tile_def where id = here;

  if p_action = 'cut_down' then
    -- It may have come down since this was asked for; do not swing at air.
    if here not in (tile_id('Tree'), tile_id('Bush')) then return 'There is nothing standing here to cut down.'; end if;
  elsif p_action = 'forage' then
    if not t.forage then return 'Nothing grows here worth looking through.'; end if;
    if is_foraged(p_world, tx, ty, 'forage') then return 'This spot has been picked clean for now.'; end if;
  elsif p_action = 'botanize' then
    if not t.botanize then return 'Nothing grows here worth looking through.'; end if;
    if is_foraged(p_world, tx, ty, 'botanize') then return 'This spot has been picked clean for now.'; end if;
  elsif p_action = 'collect' then
    if not t.collect then return 'There is no bed of anything here.'; end if;
  end if;
  return null;
end $$;

create or replace function perform_gather(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tx int; ty int; here int; data int; t tile_def; tool_id bigint;
        s double precision; tq double precision; made_ql double precision;
        species int; logs int; tree tree_def; gained double precision;
        passes int; i int; found text[] := '{}'; got text; yields text;
begin
  select * into d from action_def where id = p_action;
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  here := land_tile(p_world, tx, ty);
  data := land_data(p_world, tx, ty);
  select * into t from tile_def where id = here;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;
  if d.tool is not null then
    select it.id into tool_id from item it
      where it.world_id = p_world and it.holder = 'player' and it.holder_uid = p_uid and it.def = d.tool
      order by tool_worth(it.ql, it.dmg, it.extra, it.rare, it.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
  end if;

  if p_action = 'cut_down' then
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'Your hatchet glances off and you fail to make headway.', 'event');
      return;
    end if;
    if here = tile_id('Bush') then
      perform land_set_tile(p_world, tx, ty, tile_id('Grass'));
      perform land_set_data(p_world, tx, ty, 0);
      perform land_announce(p_world, tx, ty);
      perform tell(p_world, p_uid, 'You hack the bush down.', 'event');
    else
      species := tree_species(data);
      select * into tree from tree_def where id = species;
      -- An old tree is worth one log more than a grown one.
      logs := tree.logs + case when tree_age(data) = 2 then 1 else 0 end;
      perform land_set_tile(p_world, tx, ty, tile_id('Grass'));
      perform land_set_data(p_world, tx, ty, 0);
      perform land_announce(p_world, tx, ty);
      made_ql := product_ql(s, tq);
      perform give(p_world, p_uid, 'log', logs, made_ql, tree.name);
      perform tell(p_world, p_uid, 'The ' || lower(tree.name) || ' tree falls. You get ' || logs
        || case when logs = 1 then ' log' else ' logs' end || '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    end if;
    gained := skill_raise(p_world, p_uid, 'woodcutting', 1);

  elsif p_action in ('forage', 'botanize') then
    perform mark_foraged(p_world, tx, ty, p_action);
    -- A practised eye goes over the same ground more than once.
    passes := rolls_at(s);
    for i in 1..passes loop
      if random() < 0.2 or not skill_check(s, 5, 0) then continue; end if;
      got := roll_table(p_action, random());
      made_ql := product_ql(s, 0);
      perform give(p_world, p_uid, got, 1, made_ql);
      found := found || (lower((select coalesce(name, got) from item_def where id = got))
        || ' (QL ' || to_char(made_ql, 'FM990.0') || ')');
    end loop;
    if array_length(found, 1) is null then
      perform tell(p_world, p_uid, case when passes > 1
        then 'You go over the ground ' || passes || ' times and find nothing'
             || case when p_action = 'forage' then ' edible.' else ' of interest.' end
        else case when p_action = 'forage' then 'You find nothing edible.' else 'You find nothing of interest.' end
        end, 'event');
    else
      perform tell(p_world, p_uid, 'You find some ' || list_of(found) || '.', 'event');
    end if;
    gained := skill_raise(p_world, p_uid, d.skill, 1);

  elsif p_action = 'collect' then
    yields := t.dig_yield;
    if yields is null then return; end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'Your shovel comes up with nothing but a smear of '
        || lower(t.name) || '.', 'event');
      return;
    end if;
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yields, 1, made_ql);
    perform tell(p_world, p_uid, 'You fill a shovel with '
      || lower((select coalesce(name, yields) from item_def where id = yields))
      || ' off the top of the bed. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    gained := skill_raise(p_world, p_uid, 'digging', 1);
  end if;

  if gained > 0 and d.skill is not null then
    perform tell(p_world, p_uid,
      initcap(replace(d.skill, '_', ' ')) || ' increased by ' || to_char(gained, 'FM0.0000')
      || ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914200600_dispatch4.sql
-- ======================================================================

-- The dispatcher: the ground, and what grows on it.

create or replace function act_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare d action_def; p player; cx int; cy int; tx int; ty int; t tile_def; aimed text;
begin
  select * into d from action_def where id = p_action;
  if not found then return 'There is no such thing as ' || p_action || '.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  -- Deliberately not "are you busy": asked of queued jobs too. That is rpc_act's.
  if not act_ported(p_action) then
    return 'You cannot ' || lower(d.label) || ' on this island yet.';
  end if;

  aimed := p_target->>'kind';
  if aimed in ('campfire', 'smelter', 'kiln', 'furniture', 'anvil') or p_action like 'place\_%' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
  if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
    return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
  end if;
  if p_action = 'build_campfire' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    return terrain_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    return gather_refusal(p_world, p_uid, p_action, p_target);
  end if;

  if exists (select 1 from recipe where id = p_action) then
    return craft_refusal(p_world, p_uid, p_action, nullif(p_target->>'uid', '')::bigint);
  end if;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    if t.dig_yield is null then return 'You cannot dig that.'; end if;
    if land_height(p_world, cx, cy) <= 0 then return 'You cannot dig below the water level.'; end if;
    if land_dirt(p_world, cx, cy) <= 0 then
      return 'That corner is bare rock. Only a pickaxe will take it lower.';
    end if;
  end if;
  return null;
end $$;

create or replace function act_perform(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tq double precision; s double precision; cx int; cy int; tx int; ty int;
        t tile_def; left_dirt int; made_ql double precision; yield text; gained double precision; tool_id bigint;
begin
  if p_action like 'build\_%' or p_action like 'place\_%' or p_action like 'pick\_up\_%'
     or p_action like 'light\_%' or p_action like 'fuel\_%' or p_action like 'put\_out\_%'
     or p_action like 'damp\_%' or p_action like 'take\_ashes\_%' or p_action like 'take\_apart\_%' then
    perform perform_fire(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    perform perform_terrain(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    perform perform_gather(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if exists (select 1 from recipe where id = p_action) then
    perform perform_craft(p_world, p_uid, p_action, p_target);
    return;
  end if;

  select * into d from action_def where id = p_action;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    select i.id into tool_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = d.tool
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'You fail to dig anything useful.', 'event');
      return;
    end if;
    perform land_set_height(p_world, cx, cy, land_height(p_world, cx, cy) - 1);
    left_dirt := land_dirt(p_world, cx, cy) - 1;
    perform land_set_dirt(p_world, cx, cy, left_dirt);
    if t.turns_to_dirt then perform land_set_tile(p_world, tx, ty, 1); end if;
    -- Dug to the rock, the tile becomes rock and shows the seam under it.
    perform reconcile_around(p_world, cx, cy);
    perform land_announce(p_world, tx, ty);
    if left_dirt <= 0 then
      perform tell(p_world, p_uid, 'Your shovel grates on bare rock.', 'event');
    end if;
    yield := coalesce(t.dig_yield, 'dirt');
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yield, 1, made_ql);
    gained := skill_raise(p_world, p_uid, d.skill, 1);
    perform tell(p_world, p_uid,
      'You dig up some ' || lower((select name from item_def where id = yield)) ||
      '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    if gained > 0 then
      perform tell(p_world, p_uid, 'Digging increased by ' || to_char(gained, 'FM0.0000') ||
        ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
    end if;
  end if;
end $$;

select private.lock_doors();

