-- ======================================================================
-- 20260914202000_fish.sql
-- ======================================================================

-- Fishing: a rod off the bank, and a net walked round the shallows.
--
-- Everything is caught from where you stand, so finding water with depth to it
-- close to something you can stand on is half the trade. What runs in the
-- shallows is not what runs off a drop-off, and what runs deep will not come up
-- for a beginner.

/** How deep the water is on a tile, in height units; zero on dry land. */
create or replace function water_depth(p_world uuid, p_x int, p_y int) returns double precision
  language sql stable as $$
  select case when least(a, b, c, d) < 0 then greatest(0, -((a + b + c + d) / 4.0)) else 0 end
  from (select land_height(p_world, p_x, p_y) a, land_height(p_world, p_x + 1, p_y) b,
               land_height(p_world, p_x + 1, p_y + 1) c, land_height(p_world, p_x, p_y + 1) d) q
$$;

/** Water worth putting a line into: deep enough to hold anything at all. */
create or replace function fishable(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$ select water_depth(p_world, p_x, p_y) >= 1 $$;

/** The best water within reach of where somebody is standing. */
create or replace function best_water_near(p_world uuid, p_uid uuid, p_range int default 3)
  returns table (x int, y int, depth double precision) language sql stable as $$
  select gx, gy, water_depth(p_world, gx, gy)
  from player py,
       generate_series(floor(py.x)::int - p_range, floor(py.x)::int + p_range) gx,
       generate_series(floor(py.y)::int - p_range, floor(py.y)::int + p_range) gy
  where py.world_id = p_world and py.uid = p_uid
    and gx >= 0 and gy >= 0 and water_depth(p_world, gx, gy) >= 1
  order by water_depth(p_world, gx, gy) desc limit 1
$$;

/** How far a line will go, and how far a net is dragged. */
create or replace function cast_range() returns double precision language sql immutable as $$ select 3.6 $$;
create or replace function net_range() returns double precision language sql immutable as $$ select 2.6 $$;

/**
 * Where the line actually goes. Whatever was clicked is a hint: if it is water
 * you can reach from where you stand, it is fished; otherwise the deepest water
 * within a cast of your feet is.
 */
create or replace function cast_at(p_world uuid, p_uid uuid, p_x int, p_y int, p_range double precision)
  returns table (x int, y int, depth double precision) language plpgsql stable as $$
declare py player;
begin
  select * into py from player where world_id = p_world and uid = p_uid;
  if fishable(p_world, p_x, p_y)
     and sqrt(power(p_x + 0.5 - py.x, 2) + power(p_y + 0.5 - py.y, 2)) <= p_range then
    return query select p_x, p_y, water_depth(p_world, p_x, p_y);
  else
    return query select * from best_water_near(p_world, p_uid, 3);
  end if;
end $$;

/** What could be caught here by somebody who knows this much. */
create or replace function fish_here(p_depth double precision, p_skill double precision)
  returns setof fish_def language sql stable as $$
  select * from fish_def where p_depth >= depth and p_skill >= level
$$;

/**
 * One fish out of the pool, weighted, with whatever is on the hook counted in.
 *
 * A bait is worth eight of a fish's own weight for its first favourite, four
 * for its second, and everything it does not favour is worth a third of what it
 * would have been. The roll comes in as an argument so that a net taking five
 * passes gets five answers rather than one answer five times.
 */
create or replace function pick_fish(p_depth double precision, p_skill double precision,
                                     p_bait text, p_roll double precision)
  returns text language sql stable as $$
  select id from (
    select f.id, sum(w) over (order by w desc, f.id) upto, sum(w) over () total
    from fish_here(p_depth, p_skill) f
    cross join lateral (select case
      when p_bait is null then f.weight
      else coalesce(
        (select f.weight * (8.0 / (bf.rank + 1)) from bait_favours bf
         where bf.bait = p_bait and bf.fish = f.id),
        f.weight * 0.35)
      end as w) q
  ) r where upto >= p_roll * total order by upto limit 1
$$;

/**
 * What comes up, or nothing for a bite that came off. Deeper water and a
 * better hand both help; the rarer fish are simply rarer wherever you stand.
 */
create or replace function catch_fish(p_depth double precision, p_skill double precision,
                                      p_rod_ql double precision, p_bait text)
  returns text language sql volatile as $$
  select case
    when not exists (select 1 from fish_here(p_depth, p_skill)) then null
    when random() > least(0.95, 0.3 + p_skill / 190 + p_rod_ql / 320
                          + case when p_bait is null then 0 else 0.12 end) then null
    else pick_fish(p_depth, p_skill, p_bait, random())
    end
$$;

/**
 * The bait in the pack worth using here: the one favouring the rarest thing
 * that actually swims at this depth. A fish on the hook is a fish you are not
 * eating, so the last one of anything is left alone — you have to be able to
 * spare it.
 */
create or replace function bait_for(p_world uuid, p_uid uuid, p_depth double precision, p_skill double precision)
  returns text language sql stable as $$
  select b.id from bait_def b
  cross join lateral (
    select max(100 - f.weight) as score
    from bait_favours bf join fish_here(p_depth, p_skill) f on f.id = bf.fish
    where bf.bait = b.id) s
  where s.score > 0
    and pack_count(p_world, p_uid, b.id)
        >= case when exists (select 1 from fish_def where id = b.id) then 2 else 1 end
  order by s.score desc, b.id limit 1
$$;

select private.lock_doors();

-- ======================================================================
-- 20260914202100_fish_acts.sql
-- ======================================================================

-- Casting a line, and walking a net round.

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field',
      'fish', 'drag_net',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

create or replace function fish_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare tx int; ty int; spot record; skill double precision;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  skill := skill_of(p_world, p_uid, 'fishing');

  if p_action = 'fish' then
    select * into spot from cast_at(p_world, p_uid, tx, ty, cast_range());
    if spot.depth is null then
      return 'There is no water within reach deep enough to hold anything. Walk to the bank.';
    end if;
    if not exists (select 1 from fish_here(spot.depth, skill)) then
      return 'Nothing you could land runs in water this shallow.';
    end if;
  elsif p_action = 'drag_net' then
    select * into spot from cast_at(p_world, p_uid, tx, ty, net_range());
    if spot.depth is null then
      return 'There is no water close enough to drag a net through. Wade in.';
    end if;
    if spot.depth < 1 then return 'The water is too thin to drag a net through.'; end if;
  end if;
  return null;
end $$;

create or replace function perform_fish(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare tx int; ty int; spot record; skill double precision; rod_ql double precision;
        bait text; got text; made_ql double precision; tool_id bigint; gained double precision;
        haul int; i int; parts text[] := '{}'; one text; counted jsonb := '{}'::jsonb; k text;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  skill := skill_of(p_world, p_uid, 'fishing');

  if p_action = 'fish' then
    select * into spot from cast_at(p_world, p_uid, tx, ty, cast_range());
    if spot.depth is null then return; end if;
    rod_ql := tool_ql(p_world, p_uid, 'fishing_rod');
    select it.id into tool_id from item it
      where it.world_id = p_world and it.holder = 'player' and it.holder_uid = p_uid and it.def = 'fishing_rod'
      order by tool_worth(it.ql, it.dmg, it.extra, it.rare, it.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id, 0.5); end if;
    gained := skill_raise(p_world, p_uid, 'fishing', 0.4);

    -- Something goes on the hook if anything worth using is in the pack.
    bait := bait_for(p_world, p_uid, spot.depth, skill);
    if bait is not null and not consume(p_world, p_uid, bait, 1) then return; end if;

    got := catch_fish(spot.depth, skill, rod_ql, bait);
    if got is null then
      perform tell(p_world, p_uid, case when bait is null then 'Something takes it and comes off again.'
        else 'Something takes the ' || lower((select coalesce(name, bait) from item_def where id = bait))
             || ' and comes off again.' end, 'event');
    else
      made_ql := product_ql(skill, rod_ql);
      perform give(p_world, p_uid, got, 1, made_ql);
      perform tell(p_world, p_uid, 'You land '
        || case when lower((select name from fish_def where id = got)) ~ '^[aeiou]' then 'an ' else 'a ' end
        || lower((select name from fish_def where id = got))
        || case when bait is null then '' else ' on the '
             || lower((select coalesce(name, bait) from item_def where id = bait)) end
        || '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    end if;

  elsif p_action = 'drag_net' then
    select * into spot from cast_at(p_world, p_uid, tx, ty, net_range());
    if spot.depth is null then return; end if;
    rod_ql := tool_ql(p_world, p_uid, 'fishing_net');
    select it.id into tool_id from item it
      where it.world_id = p_world and it.holder = 'player' and it.holder_uid = p_uid and it.def = 'fishing_net'
      order by tool_worth(it.ql, it.dmg, it.extra, it.rare, it.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id, 1.4); end if;
    gained := skill_raise(p_world, p_uid, 'fishing', 0.55);

    if not exists (select 1 from fish_here(spot.depth, skill)) then
      perform tell(p_world, p_uid, 'The net comes up with nothing in it but weed.', 'event');
      return;
    end if;
    -- A net takes numbers, not size: the big fish go round it or through it.
    haul := 1 + floor(random() * (1 + 4 * (0.3 + least(100, rod_ql) / 160)))::int;
    for i in 1..haul loop
      one := pick_fish(spot.depth, skill, null, random());
      -- Anything that lives deeper than a net reaches mostly avoids it.
      if one is not null and ((select depth from fish_def where id = one) <= 8 or random() < 0.12) then
        counted := jsonb_set(counted, array[one], to_jsonb(coalesce((counted->>one)::int, 0) + 1));
      end if;
    end loop;
    if counted = '{}'::jsonb then
      perform tell(p_world, p_uid, 'The net comes up empty.', 'event');
      return;
    end if;
    made_ql := product_ql(skill, rod_ql);
    for k in select jsonb_object_keys(counted) loop
      perform give(p_world, p_uid, k, (counted->>k)::int, made_ql);
      parts := parts || ((counted->>k) || ' × ' || lower((select coalesce(name, k) from item_def where id = k)));
    end loop;
    perform tell(p_world, p_uid, 'You walk the net round and haul it in: '
      || array_to_string(parts, ', ') || '.', 'event');
  end if;

  if gained > 0 then
    perform tell(p_world, p_uid, 'Fishing increased by ' || to_char(gained, 'FM0.0000')
      || ' to ' || to_char(skill_of(p_world, p_uid, 'fishing'), 'FM990.0000') || '.', 'skill');
  end if;
end $$;

