-- ======================================================================
-- 20260914203200_build.sql
-- ======================================================================

-- A settlement, and the houses that stand on it.
--
-- ## Why a building is four tables
--
-- A building is a footprint of tiles, a wall on each of a set of *borders*,
-- and a floor slot per tile per storey. The browser keeps the three in maps
-- keyed by a string — `"2:h:14,9"` — which is a primary key written the long
-- way round. Here they are columns, and the key does the work it was always
-- doing: one wall per border per storey, one floor per tile per storey, one
-- building per tile.
--
-- Walls and floors are planned before they are built, and are then fed
-- materials one unit at a time. What is still owed is a bill on the row, and a
-- thing is finished when its bill is empty — which is the same rule for a
-- wall, a roof, a staircase and a ladder, so it is written once.

/* ------------------------------------------------------------------ *
 * Things any part of the island may want to ask about the land.
 * ------------------------------------------------------------------ */

create or replace function in_bounds(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select p_x >= 0 and p_y >= 0 and p_x < (select size from world where id = p_world)
     and p_y < (select size from world where id = p_world)
$$;

/** Whether anything alive can stand on the tile at all. */
create or replace function passable(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select in_bounds(p_world, p_x, p_y)
     and not coalesce((select blocks from tile_def where id = land_tile(p_world, p_x, p_y)), true)
$$;

/**
 * Whether a tile is wet at all.
 *
 * Not `water_depth() > 0`: a tile with one corner just under and three well
 * over averages out dry, and you still cannot build there.
 */
create or replace function has_water(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select least(land_height(p_world, p_x, p_y), land_height(p_world, p_x + 1, p_y),
               land_height(p_world, p_x + 1, p_y + 1), land_height(p_world, p_x, p_y + 1)) < 0
$$;

/* ------------------------------------------------------------------ *
 * The settlement.
 * ------------------------------------------------------------------ */

/**
 * One deed to an island.
 *
 * In the browser the deed is the player's; here the island is shared, and a
 * shared island with a deed each would be a border dispute rather than a game.
 * So the first stake planted claims the island's one settlement and everybody
 * who lands there builds on it. Who planted it is kept, because the deed
 * actions that are still to come — disband, upgrade — are theirs to take.
 */
create table if not exists deed (
  world_id uuid primary key references world on delete cascade,
  name text not null check (length(name) between 1 and 32),
  x int not null,
  y int not null,
  radius int not null default 5,
  level int not null default 1 check (level between 1 and 5),
  founded_by uuid,
  founded_at timestamptz not null default now()
);
alter table deed enable row level security;
drop policy if exists deed_read on deed;
create policy deed_read on deed for select to authenticated using (true);
grant select on deed to authenticated;
revoke insert, update, delete on deed from anon, authenticated;

create or replace function deed_radius(p_level int) returns int language sql immutable as $$
  select 5 + (greatest(1, least(5, p_level)) - 1) * 2
$$;

create or replace function on_deed(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select exists (select 1 from deed d where d.world_id = p_world
    and abs(p_x - d.x) <= d.radius and abs(p_y - d.y) <= d.radius)
$$;

create or replace function is_token(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select exists (select 1 from deed d where d.world_id = p_world and d.x = p_x and d.y = p_y)
$$;

/* ------------------------------------------------------------------ *
 * The buildings themselves.
 * ------------------------------------------------------------------ */

create table if not exists building (
  world_id uuid not null references world on delete cascade,
  id int not null,
  name text not null check (length(name) between 1 and 32),
  /** Storeys planned; the ground floor counts as one. */
  levels int not null default 1 check (levels between 1 and 10),
  /** The storey wall and floor work applies to; null means the top one. */
  work_level int,
  planned_by uuid,
  primary key (world_id, id)
);

/**
 * The footprint. One building to a tile, which the key says outright — the
 * browser's `tileIndex` is this, and the check it does by hand before adding
 * a tile is one Postgres does for it.
 */
create table if not exists building_tile (
  world_id uuid not null,
  building int not null,
  x int not null,
  y int not null,
  primary key (world_id, x, y),
  foreign key (world_id, building) references building (world_id, id) on delete cascade
);
create index if not exists building_tile_by_building on building_tile (world_id, building);

/**
 * A wall, on a border rather than on a tile.
 *
 * `h` is the north border of (x, y) and `v` its west, so every border has
 * exactly one name and two tiles that share it. A fence belongs to no
 * building, which is what building 0 means — it is a real border with a real
 * wall on it, just with nothing around it.
 */
create table if not exists wall (
  world_id uuid not null references world on delete cascade,
  level int not null,
  dir text not null check (dir in ('h', 'v')),
  x int not null,
  y int not null,
  building int not null default 0,
  type text not null,
  material text not null,
  needed jsonb not null,
  total jsonb not null,
  planned_by uuid,
  primary key (world_id, level, dir, x, y)
);
create index if not exists wall_by_building on wall (world_id, building, level);

/** A tile's floor slot on a storey: a floor, a staircase, a ladder or a roof. */
create table if not exists floor_tile (
  world_id uuid not null references world on delete cascade,
  level int not null,
  x int not null,
  y int not null,
  building int not null,
  material text not null,
  kind text not null default 'floor' check (kind in ('floor', 'stairs', 'ladder', 'roof')),
  /** For stairs and ladders: the side you step on from below. */
  facing text,
  needed jsonb not null,
  total jsonb not null,
  planned_by uuid,
  primary key (world_id, level, x, y)
);
create index if not exists floor_by_building on floor_tile (world_id, building, level);

do $$
declare t text;
begin
  foreach t in array array['building', 'building_tile', 'wall', 'floor_tile'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_read', t);
    execute format('create policy %I on %I for select to authenticated using (true)', t || '_read', t);
    execute format('grant select on %I to authenticated', t);
    execute format('revoke insert, update, delete on %I from anon, authenticated', t);
  end loop;
end $$;

/* ------------------------------------------------------------------ *
 * Bills of materials.
 * ------------------------------------------------------------------ */

/** Nothing left owing. */
create or replace function bill_done(p_bill jsonb) returns boolean language sql immutable as $$
  select not exists (select 1 from jsonb_each_text(p_bill) e where e.value::numeric > 0)
$$;

/**
 * A material's own bill, scaled and rounded up, never to nothing.
 *
 * A window is three quarters of a solid wall and a fence less than a third of
 * one, but a third of one log is still a log: you cannot build with less than
 * a whole thing, so every line is at least one.
 */
create or replace function scaled_bill(p_material text, p_factor double precision) returns jsonb
  language sql stable as $$
  select coalesce(jsonb_object_agg(b.item, greatest(1, ceil(b.n * p_factor)::int)), '{}'::jsonb)
  from build_material_bill b where b.material = p_material
$$;

create or replace function wall_bill(p_material text, p_type text) returns jsonb
  language sql stable as $$
  select scaled_bill(p_material, coalesce((select factor from wall_type_def where id = p_type), 1))
$$;

/** Floors and roofs take half a wall, stairs three quarters; a ladder is two planks. */
create or replace function floor_bill(p_material text, p_kind text default 'floor') returns jsonb
  language sql stable as $$
  select case when p_kind = 'ladder' then '{"plank": 2}'::jsonb
    else scaled_bill(p_material, case when p_kind = 'stairs' then 0.75 else 0.5 end) end
$$;

/** What a floor slot is called, which is not always what it is keyed by. */
create or replace function floor_kind_name(p_kind text) returns text language sql immutable as $$
  select case p_kind when 'stairs' then 'staircase' else p_kind end
$$;

/** "2 logs", "1 mortar" — the plural rule of the thing rather than of English. */
create or replace function material_name(p_item text, p_n int) returns text
  language sql stable as $$
  select case
    when p_n = 1 or name ~ 's$' or name in ('mortar', 'thatch', 'adobe') then name
    else name || 's' end
  from (select lower((select coalesce(d.name, p_item) from item_def d where d.id = p_item)) as name) q
$$;

/**
 * What is still owed, in words, in the order the material lists it.
 *
 * The order matters twice over: it reads the way the bill was written, and it
 * is the order the units go in, so what the line says you need next is what
 * the next swing of the mallet will use.
 */
create or replace function bill_text(p_material text, p_bill jsonb) returns text
  language sql stable as $$
  select string_agg(part, ', ' order by ord) from (
    select coalesce(b.ord, 99) as ord, (e.value::int) || ' ' || material_name(e.key, e.value::int) as part
    from jsonb_each_text(p_bill) e
    left join build_material_bill b on b.material = p_material and b.item = e.key
    where e.value::int > 0) q
$$;

/** The next thing on a bill that the builder is actually carrying. */
create or replace function next_material(p_world uuid, p_uid uuid, p_material text, p_bill jsonb)
  returns text language sql stable as $$
  select e.key from jsonb_each_text(p_bill) e
  left join build_material_bill b on b.material = p_material and b.item = e.key
  where e.value::int > 0 and pack_count(p_world, p_uid, e.key) > 0
  order by coalesce(b.ord, 99), e.key limit 1
$$;

/* ------------------------------------------------------------------ *
 * Borders, footprints and storeys.
 * ------------------------------------------------------------------ */

/** A tile's side, in the one name a border has. */
create or replace function border_of(p_x int, p_y int, p_side text)
  returns table (x int, y int, dir text) language sql immutable as $$
  select case when p_side = 'e' then p_x + 1 else p_x end,
         case when p_side = 's' then p_y + 1 else p_y end,
         case when p_side in ('n', 's') then 'h' else 'v' end
$$;

create or replace function side_name(p_side text) returns text language sql immutable as $$
  select case p_side when 'n' then 'north' when 'e' then 'east'
                     when 's' then 'south' when 'w' then 'west' else p_side end
$$;

/** The tile on the far side of a border. */
create or replace function across(p_x int, p_y int, p_side text)
  returns table (x int, y int) language sql immutable as $$
  select p_x + case p_side when 'w' then -1 when 'e' then 1 else 0 end,
         p_y + case p_side when 'n' then -1 when 's' then 1 else 0 end
$$;

create or replace function building_at(p_world uuid, p_x int, p_y int) returns int
  language sql stable as $$
  select building from building_tile where world_id = p_world and x = p_x and y = p_y
$$;

/** An edge-adjacent building, for extending a plan onto the next tile. */
create or replace function neighbour_building(p_world uuid, p_x int, p_y int) returns int
  language sql stable as $$
  select building_at(p_world, p_x + dx, p_y + dy)
  from (values (1, 0), (-1, 0), (0, 1), (0, -1)) as d(dx, dy)
  where building_at(p_world, p_x + dx, p_y + dy) is not null
  limit 1
$$;

/** The storey being worked on, clamped to what exists. */
create or replace function work_level(p_world uuid, p_building int) returns int
  language sql stable as $$
  select least(coalesce(work_level, levels - 1), levels - 1) from building
  where world_id = p_world and id = p_building
$$;

/** Anything standing on a tile's borders or in its floor slot, at any storey. */
create or replace function tile_has_structures(p_world uuid, p_x int, p_y int) returns boolean
  language sql stable as $$
  select exists (select 1 from wall w where w.world_id = p_world
      and ((w.dir = 'h' and w.x = p_x and w.y in (p_y, p_y + 1))
        or (w.dir = 'v' and w.y = p_y and w.x in (p_x, p_x + 1))))
    or exists (select 1 from floor_tile f where f.world_id = p_world and f.x = p_x and f.y = p_y)
$$;

/** The borders of a footprint whose far side is somebody else's problem. */
create or replace function exterior_borders(p_world uuid, p_building int)
  returns table (x int, y int, dir text) language sql stable as $$
  select b.x, b.y, b.dir
  from building_tile t
  cross join lateral (values ('n'), ('s'), ('w'), ('e')) as s(side)
  cross join lateral across(t.x, t.y, s.side) a
  cross join lateral border_of(t.x, t.y, s.side) b
  where t.world_id = p_world and t.building = p_building
    and building_at(p_world, a.x, a.y) is distinct from p_building
$$;

/** Waist-high work: nothing rests on it, so no storey can be raised over it. */
create or replace function is_low_wall(p_type text) returns boolean language sql stable as $$
  select coalesce((select low from wall_type_def where id = p_type), false)
$$;

/**
 * Whether a storey carries anything waist-high — its own, or a fence that was
 * already standing on one of its borders when the footprint was laid out
 * around it. Either way there is nothing up there to build on.
 */
create or replace function has_low_wall(p_world uuid, p_building int, p_level int) returns boolean
  language sql stable as $$
  select exists (select 1 from wall w where w.world_id = p_world and w.building = p_building
      and w.level = p_level and is_low_wall(w.type))
    or (p_level = 0 and exists (
      select 1 from exterior_borders(p_world, p_building) b
      join wall w on w.world_id = p_world and w.level = 0
        and w.dir = b.dir and w.x = b.x and w.y = b.y
      where is_low_wall(w.type)))
$$;

create or replace function has_roof(p_world uuid, p_building int) returns boolean
  language sql stable as $$
  select exists (select 1 from floor_tile f where f.world_id = p_world
    and f.building = p_building and f.kind = 'roof')
$$;

/** Every exterior border walled and finished, and nothing half-built inside. */
create or replace function level_complete(p_world uuid, p_building int, p_level int) returns boolean
  language sql stable as $$
  select not exists (
      select 1 from exterior_borders(p_world, p_building) b
      left join wall w on w.world_id = p_world and w.level = p_level
        and w.dir = b.dir and w.x = b.x and w.y = b.y
      where w.type is null or not bill_done(w.needed))
    and not exists (
      select 1 from wall w where w.world_id = p_world and w.building = p_building
        and w.level = p_level and not bill_done(w.needed))
$$;

/**
 * Why a tile cannot take a building plan, or null when it can.
 *
 * Flat, packed, dry, clear, and yours. The order is the browser's, because
 * the first thing wrong is what a player is told and being told the same
 * thing in both places is the point of porting it rather than rewriting it.
 */
create or replace function plan_reason(p_world uuid, p_x int, p_y int) returns text
  language sql stable as $$
  select case
    when not on_deed(p_world, p_x, p_y) then 'You may only build on your own deed.'
    when is_token(p_world, p_x, p_y) then 'The settlement token stands here.'
    when building_at(p_world, p_x, p_y) is not null then 'That tile is already part of a building.'
    when land_tile(p_world, p_x, p_y) <> tile_id('Packed dirt')
      then 'Buildings need flat packed dirt. Pack the tile first.'
    when tile_slope(p_world, p_x, p_y) <> 0 then 'The tile must be perfectly flat. Flatten it first.'
    when has_water(p_world, p_x, p_y) then 'You cannot build in water.'
    when exists (select 1 from item i where i.world_id = p_world and i.holder = 'ground'
                   and i.gx = p_x and i.gy = p_y) then 'Clear away the items lying there first.'
    end
$$;

select private.lock_doors();

-- ======================================================================
-- 20260914203300_build_acts.sql
-- ======================================================================

-- Planting a stake, planning a house, and feeding it planks.

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field',
      'fish', 'drag_net',
      'found_settlement',
      'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
      'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
      'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

/** "You need a mallet for that.", or nothing when it is in hand. */
create or replace function need_tool(p_world uuid, p_uid uuid, p_tool text) returns text
  language sql stable as $$
  select case when pack_count(p_world, p_uid, p_tool) > 0 then null
    else 'You need a ' || lower((select coalesce(name, p_tool) from item_def where id = p_tool))
         || ' for that.' end
$$;

/** The storey wall work happens on: a building's working one, or the ground. */
create or replace function wall_level(p_world uuid, p_x int, p_y int) returns int
  language sql stable as $$
  select coalesce(work_level(p_world, building_at(p_world, p_x, p_y)), 0)
$$;

/** The wall or fence on the side of a tile that is being worked on. */
create or replace function wall_at(p_world uuid, p_x int, p_y int, p_side text) returns wall
  language sql stable as $$
  select w.* from border_of(p_x, p_y, p_side) b
  join wall w on w.world_id = p_world and w.level = wall_level(p_world, p_x, p_y)
    and w.dir = b.dir and w.x = b.x and w.y = b.y
$$;

/**
 * The storey a floor slot belongs to.
 *
 * A roof is not part of the top storey, it sits one above it; everything else
 * goes on the storey being worked on.
 */
create or replace function floor_level(p_world uuid, p_building int, p_kind text) returns int
  language sql stable as $$
  select case when p_kind = 'roof' then (select levels from building where world_id = p_world and id = p_building)
              else work_level(p_world, p_building) end
$$;

/* ------------------------------------------------------------------ *
 * Founding.
 * ------------------------------------------------------------------ */

create or replace function deed_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare p player; tx int; ty int; radius int := 5;
begin
  select * into p from player where world_id = p_world and uid = p_uid;
  tx := floor(p.x)::int; ty := floor(p.y)::int;
  if exists (select 1 from deed where world_id = p_world) then
    return 'You already hold a settlement. Disband it first.';
  end if;
  if pack_count(p_world, p_uid, 'deed_stake') <= 0 then return 'You have no deed stake.'; end if;
  if tx - radius < 0 or ty - radius < 0
     or not in_bounds(p_world, tx + radius, ty + radius) then
    return 'Too close to the edge of the world.';
  end if;
  if has_water(p_world, tx, ty) then return 'The token must stand on dry land.'; end if;
  if not passable(p_world, tx, ty) then return 'The token needs a clear tile.'; end if;
  return null;
end $$;

create or replace function perform_deed(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare p player; tx int; ty int; nm text;
begin
  select * into p from player where world_id = p_world and uid = p_uid;
  tx := floor(p.x)::int; ty := floor(p.y)::int;
  -- The browser asks for a name in a dialog; here it rides in with the target,
  -- because there is nobody at this end to ask.
  nm := nullif(btrim(coalesce(p_target->>'name', '')), '');
  if nm is null then nm := 'Homestead'; end if;
  if not consume(p_world, p_uid, 'deed_stake', 1) then return; end if;
  values (p_world, left(nm, 32), tx, ty, deed_radius(1), 1, p_uid)
  on conflict do nothing;
  perform tell(p_world, p_uid, 'You found the settlement of ' || left(nm, 32)
    || '. The land ' || (deed_radius(1) * 2 + 1) || ' tiles across around the token is yours to build on.', 'system');
end $$;

/* ------------------------------------------------------------------ *
 * Building work.
 * ------------------------------------------------------------------ */

create or replace function build_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare tx int; ty int; side text; wt wall_type_def; mat build_material_def; b building;
        w wall; f floor_tile; lvl int; kind text; tool text; other record;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  side := p_target->>'side';
  select * into wt from wall_type_def where id = p_target->>'wallType';
  select * into mat from build_material_def where id = p_target->>'material';
  select * into b from building where world_id = p_world and id = building_at(p_world, tx, ty);

  if p_action = 'plan_building' then
    return coalesce(need_tool(p_world, p_uid, 'mallet'), plan_reason(p_world, tx, ty));

  elsif p_action = 'add_to_building' then
    tool := need_tool(p_world, p_uid, 'mallet');
    if tool is not null then return tool; end if;
    select * into b from building where world_id = p_world and id = neighbour_building(p_world, tx, ty);
    if not found then return 'There is no building next to this tile.'; end if;
    if b.levels > 1 then return 'The footprint cannot change once upper floors are planned.'; end if;
    return plan_reason(p_world, tx, ty);

  elsif p_action = 'remove_from_plan' then
    if b.id is null then return 'No building here.'; end if;
    if b.levels > 1 then return 'Remove the upper floors first.'; end if;
    if tile_has_structures(p_world, tx, ty) then return 'Remove the walls and floor on this tile first.'; end if;
    return null;

  elsif p_action = 'rename_building' then
    if b.id is null then return 'No building here.'; end if;
    if nullif(btrim(coalesce(p_target->>'name', '')), '') is null then return 'Choose a name.'; end if;
    return null;

  elsif p_action = 'plan_wall' then
    if side is null or wt.id is null or mat.id is null then return 'Choose a side, a wall type and a material.'; end if;
    tool := need_tool(p_world, p_uid, 'mallet');
    if tool is not null then return tool; end if;
    if b.id is null then return 'No building here.'; end if;
    lvl := work_level(p_world, b.id);
    if lvl > 0 then
      select * into f from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty;
      if not found or not bill_done(f.needed) then return 'Build the floor of this storey first.'; end if;
    end if;
    if (wall_at(p_world, tx, ty, side)).world_id is not null then return 'There is already a wall on that side.'; end if;
    return null;

  elsif p_action = 'plan_fence' then
    if side is null or wt.id is null or mat.id is null then return 'Choose a side, a kind and a material.'; end if;
    if not wt.standalone then return 'Only fences and half walls stand on their own.'; end if;
    tool := need_tool(p_world, p_uid, mat.tool);
    if tool is not null then return tool; end if;
    if b.id is not null then return 'That is part of a building: plan a wall instead.'; end if;
    select * into other from across(tx, ty, side);
    -- The border is shared, so the tile on the other side of it has a say.
    if building_at(p_world, other.x, other.y) is not null then return 'A building stands on the other side of that border.'; end if;
    if not in_bounds(p_world, other.x, other.y) then return 'That border is the edge of the world.'; end if;
    if has_water(p_world, tx, ty) or has_water(p_world, other.x, other.y) then return 'Fences do not stand in water.'; end if;
    if not passable(p_world, tx, ty) or not passable(p_world, other.x, other.y) then return 'There is no room for posts there.'; end if;
    if exists (select 1 from border_of(tx, ty, side) bd
               join wall w2 on w2.world_id = p_world and w2.level = 0
                 and w2.dir = bd.dir and w2.x = bd.x and w2.y = bd.y) then
      return 'There is already something on that border.';
    end if;
    return null;

  elsif p_action in ('build_wall', 'remove_wall') then
    if side is null then return 'Choose a side.'; end if;
    w := wall_at(p_world, tx, ty, side);
    if p_action = 'remove_wall' then
      return case when w.world_id is null then 'There is no wall there.' end;
    end if;
    if w.world_id is null then return 'There is no wall planned there.'; end if;
    if bill_done(w.needed) then return 'That wall is finished.'; end if;
    select * into mat from build_material_def where id = w.material;
    if mat.id is not null then
      tool := need_tool(p_world, p_uid, mat.tool);
      if tool is not null then return tool; end if;
    end if;
    if next_material(p_world, p_uid, w.material, w.needed) is null then
      return 'You need ' || bill_text(w.material, w.needed) || '.';
    end if;
    return null;

  elsif p_action = 'add_floor' then
    tool := need_tool(p_world, p_uid, 'mallet');
    if tool is not null then return tool; end if;
    if b.id is null then return 'No building here.'; end if;
    if b.levels >= 10 then return 'Buildings cannot be taller than 10 storeys.'; end if;
    if has_roof(p_world, b.id) then return 'Take the roof off first.'; end if;
    if has_low_wall(p_world, b.id, b.levels - 1) then
      return 'Nothing rests on a fence or a half wall. The storey below needs walls all round.';
    end if;
    if not level_complete(p_world, b.id, b.levels - 1) then
      return 'All walls of the storey below must be built first.';
    end if;
    return null;

  elsif p_action = 'plan_floor' then
    if mat.id is null then return 'Choose a material.'; end if;
    tool := need_tool(p_world, p_uid, 'mallet');
    if tool is not null then return tool; end if;
    if b.id is null then return 'No building here.'; end if;
    kind := coalesce(p_target->>'floorKind', 'floor');
    lvl := floor_level(p_world, b.id, kind);
    if kind = 'roof' then
      if not level_complete(p_world, b.id, b.levels - 1) then
        return 'All walls of the top storey must be built before roofing.';
      end if;
    elsif kind in ('stairs', 'ladder') then
      if lvl < 1 then return 'Stairs and ladders belong to an upper storey; plan another storey first.'; end if;
      if side is null then return 'Choose the side to climb from.'; end if;
      if lvl > 1 and not exists (select 1 from floor_tile where world_id = p_world
          and level = lvl - 1 and x = tx and y = ty) then
        return 'Plan the floor of the storey below first.';
      end if;
    end if;
    if exists (select 1 from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty) then
      return case when kind = 'roof' then 'There is already roof planned here.'
                  else 'There is already a floor planned here.' end;
    end if;
    return null;

  elsif p_action in ('build_floor', 'remove_floor') then
    if b.id is null then return case when p_action = 'build_floor'
      then 'There is nothing planned here.' else 'No building here.' end; end if;
    kind := coalesce(p_target->>'floorKind', 'floor');
    lvl := floor_level(p_world, b.id, kind);
    select * into f from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty;
    if p_action = 'remove_floor' then
      if not found then return 'There is nothing here to remove.'; end if;
      if f.kind <> 'roof' and exists (
          select 1 from (values ('n'), ('e'), ('s'), ('w')) as s(side)
          cross join lateral border_of(tx, ty, s.side) bd
          join wall w2 on w2.world_id = p_world and w2.level = lvl
            and w2.dir = bd.dir and w2.x = bd.x and w2.y = bd.y) then
        return 'Take down the walls standing on it first.';
      end if;
      return null;
    end if;
    if not found then return 'There is nothing planned here.'; end if;
    if bill_done(f.needed) then return 'That is already finished.'; end if;
    select * into mat from build_material_def where id = f.material;
    tool := need_tool(p_world, p_uid, case when f.kind = 'ladder' then 'mallet' else mat.tool end);
    if tool is not null then return tool; end if;
    if next_material(p_world, p_uid, f.material, f.needed) is null then
      return 'You need ' || bill_text(f.material, f.needed) || '.';
    end if;
    return null;

  elsif p_action = 'remove_storey' then
    if b.id is null or b.levels <= 1 then return 'There is no upper storey.'; end if;
    lvl := b.levels - 1;
    if has_roof(p_world, b.id) then return 'Take the roof off first.'; end if;
    if exists (select 1 from wall where world_id = p_world and building = b.id and level = lvl) then
      return 'Take down the walls of the top storey first.';
    end if;
    if exists (select 1 from floor_tile where world_id = p_world and building = b.id and level = lvl) then
      return 'Tear up the floors of the top storey first.';
    end if;
    return null;
  end if;
  return null;
end $$;

/**
 * The doing of it.
 *
 * Planning writes a row with a bill on it; building takes one unit off that
 * bill. The unit taken is the first line of the material's own bill that the
 * builder is carrying, which is why the bill keeps its order: what the refusal
 * says you still need is what the next swing actually uses.
 */
create or replace function perform_building(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare tx int; ty int; side text; b building; w wall; f floor_tile; mat build_material_def;
        wt wall_type_def; lvl int; kind text; used text; nm text; gained double precision;
        sk text; bill jsonb; other record; what text; new_id int;
begin
  tx := (p_target->>'x')::int; ty := (p_target->>'y')::int;
  side := p_target->>'side';
  select * into b from building where world_id = p_world and id = building_at(p_world, tx, ty);

  if p_action = 'plan_building' then
    nm := left(coalesce(nullif(btrim(coalesce(p_target->>'name', '')), ''), 'House'), 32);
    select coalesce(max(id), 0) + 1 into new_id from building where world_id = p_world;
    perform tell(p_world, p_uid, 'You plan ' || nm || ' here. Extend it onto neighbouring flat packed '
      || 'tiles, then plan walls on its borders.', 'event');

  elsif p_action = 'add_to_building' then
    select * into b from building where world_id = p_world and id = neighbour_building(p_world, tx, ty);
    if not found then return; end if;
      on conflict do nothing;
    perform tell(p_world, p_uid, 'You add the tile to ' || b.name || '.', 'event');

  elsif p_action = 'remove_from_plan' then
    if b.id is null then return; end if;
    delete from building_tile where world_id = p_world and x = tx and y = ty;
    if exists (select 1 from building_tile where world_id = p_world and building = b.id) then
      perform tell(p_world, p_uid, 'You remove the tile from ' || b.name || '.', 'event');
    else
      -- The last tile of a plan is the plan.
      delete from building where world_id = p_world and id = b.id;
      perform tell(p_world, p_uid, 'You remove the last of ' || b.name || '''s plan.', 'event');
    end if;

  elsif p_action = 'rename_building' then
    if b.id is null then return; end if;
    nm := left(btrim(p_target->>'name'), 32);
    update building set name = nm where world_id = p_world and id = b.id;
    perform tell(p_world, p_uid, 'The building is now called ' || nm || '.', 'event');

  elsif p_action in ('plan_wall', 'plan_fence') then
    select * into wt from wall_type_def where id = p_target->>'wallType';
    select * into mat from build_material_def where id = p_target->>'material';
    lvl := case when p_action = 'plan_fence' then 0 else work_level(p_world, b.id) end;
    bill := wall_bill(mat.id, wt.id);
    select p_world, lvl, bd.dir, bd.x, bd.y,
           case when p_action = 'plan_fence' then 0 else b.id end,
           wt.id, mat.id, bill, bill, p_uid
    from border_of(tx, ty, side) bd;
    if p_action = 'plan_fence' then
      perform tell(p_world, p_uid, 'You mark out a ' || lower(mat.name) || ' ' || lower(wt.name)
        || ' on the ' || side_name(side) || ' border. It needs ' || bill_text(mat.id, bill) || '.', 'event');
    else
      perform tell(p_world, p_uid, 'You plan a ' || lower(wt.name) || ' ' || lower(mat.name)
        || ' wall on the ' || side_name(side) || ' side. It needs ' || bill_text(mat.id, bill) || '.', 'event');
    end if;

  elsif p_action = 'build_wall' then
    w := wall_at(p_world, tx, ty, side);
    if w.world_id is null or bill_done(w.needed) then return; end if;
    select * into mat from build_material_def where id = w.material;
    used := next_material(p_world, p_uid, w.material, w.needed);
    if used is null or not consume(p_world, p_uid, used, 1) then return; end if;
    bill := jsonb_set(w.needed, array[used], to_jsonb((w.needed->>used)::int - 1));
    update wall set needed = bill where world_id = w.world_id and level = w.level
      and dir = w.dir and x = w.x and y = w.y;
    gained := skill_raise(p_world, p_uid, mat.skill, 0.4);
    select * into wt from wall_type_def where id = w.type;
    if bill_done(bill) then
      what := case when wt.low then lower(wt.name) else 'wall' end;
      perform tell(p_world, p_uid, 'You finish the ' || lower(mat.name) || ' ' || what || '.', 'event');
    else
      perform tell(p_world, p_uid, 'You fit ' || material_name(used, 1) || ' into the wall. Still needed: '
        || bill_text(w.material, bill) || '.', 'event');
    end if;
    if gained > 0 then
      perform tell(p_world, p_uid, initcap(replace(mat.skill, '_', ' ')) || ' increased by '
        || to_char(gained, 'FM0.0000') || ' to '
        || to_char(skill_of(p_world, p_uid, mat.skill), 'FM990.0000') || '.', 'skill');
    end if;

  elsif p_action = 'remove_wall' then
    w := wall_at(p_world, tx, ty, side);
    if w.world_id is null then return; end if;
    select * into wt from wall_type_def where id = w.type;
    delete from wall where world_id = w.world_id and level = w.level and dir = w.dir and x = w.x and y = w.y;
    perform tell(p_world, p_uid, 'You take down the '
      || case when wt.low then lower(wt.name) else 'wall' end
      || ' on the ' || side_name(side) || ' side.', 'event');

  elsif p_action = 'add_floor' then
    if b.id is null then return; end if;
    update building set levels = levels + 1, work_level = levels
      where world_id = p_world and id = b.id returning * into b;
    perform tell(p_world, p_uid, 'You plan storey ' || b.levels || ' of ' || b.name
      || '. Plan and build its floor tiles, then raise walls on them.', 'event');

  elsif p_action = 'plan_floor' then
    if b.id is null then return; end if;
    kind := coalesce(p_target->>'floorKind', 'floor');
    lvl := floor_level(p_world, b.id, kind);
    select * into mat from build_material_def where id = p_target->>'material';
    bill := floor_bill(mat.id, kind);
    values (p_world, lvl, tx, ty, b.id, mat.id, kind,
            case when kind in ('stairs', 'ladder') then side end, bill, bill, p_uid);
    perform tell(p_world, p_uid, 'You plan a '
      || case when kind = 'ladder' then 'ladder' else lower(mat.name) || ' ' || floor_kind_name(kind) end
      || '. It needs ' || bill_text(mat.id, bill) || '.', 'event');

  elsif p_action = 'build_floor' then
    if b.id is null then return; end if;
    kind := coalesce(p_target->>'floorKind', 'floor');
    lvl := floor_level(p_world, b.id, kind);
    select * into f from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty;
    if not found or bill_done(f.needed) then return; end if;
    select * into mat from build_material_def where id = f.material;
    used := next_material(p_world, p_uid, f.material, f.needed);
    if used is null or not consume(p_world, p_uid, used, 1) then return; end if;
    bill := jsonb_set(f.needed, array[used], to_jsonb((f.needed->>used)::int - 1));
    update floor_tile set needed = bill where world_id = p_world and level = lvl and x = tx and y = ty;
    -- Floors are paving; stairs, ladders and roofs are carpentry or masonry by material.
    sk := case f.kind when 'floor' then 'paving' when 'ladder' then 'carpentry'
                      else coalesce(mat.skill, 'carpentry') end;
    gained := skill_raise(p_world, p_uid, sk, 0.4);
    what := case when f.kind = 'ladder' then 'ladder' else lower(mat.name) || ' ' || floor_kind_name(f.kind) end;
    if bill_done(bill) then
      perform tell(p_world, p_uid, 'You finish the ' || what || '.', 'event');
    else
      perform tell(p_world, p_uid, 'You work ' || material_name(used, 1) || ' into the '
        || floor_kind_name(f.kind) || '. Still needed: ' || bill_text(f.material, bill) || '.', 'event');
    end if;
    if gained > 0 then
      perform tell(p_world, p_uid, initcap(replace(sk, '_', ' ')) || ' increased by '
        || to_char(gained, 'FM0.0000') || ' to '
        || to_char(skill_of(p_world, p_uid, sk), 'FM990.0000') || '.', 'skill');
    end if;

  elsif p_action = 'remove_floor' then
    if b.id is null then return; end if;
    kind := coalesce(p_target->>'floorKind', 'floor');
    lvl := floor_level(p_world, b.id, kind);
    select * into f from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty;
    if not found then return; end if;
    delete from floor_tile where world_id = p_world and level = lvl and x = tx and y = ty;
    -- Anybody standing on what was just torn up goes down a storey, not through it.
    if lvl > 0 then
      update player set level = lvl - 1
        where world_id = p_world and floor(x)::int = tx and floor(y)::int = ty and level >= lvl;
    end if;
    perform tell(p_world, p_uid, 'You remove the ' || floor_kind_name(f.kind) || '.', 'event');

  elsif p_action = 'remove_storey' then
    if b.id is null or b.levels <= 1 then return; end if;
    update building set levels = levels - 1, work_level = levels - 2
      where world_id = p_world and id = b.id returning * into b;
    perform tell(p_world, p_uid, b.name || ' is back to '
      || case when b.levels = 1 then 'a single storey' else b.levels || ' storeys' end || '.', 'event');
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914203400_dispatch7.sql
-- ======================================================================

-- The dispatcher, with a settlement and the houses on it.

/**
 * Which jobs belong to the building code.
 *
 * Written as a list rather than a prefix on purpose: `build_wall` and
 * `build_floor` share their first word with `build_campfire`, and the
 * dispatcher used to send anything beginning with `build_` to the fires. A
 * prefix that was unambiguous when it was written stopped being so the moment
 * a second family wanted the same verb, and nothing would have said so — the
 * wall would simply have been handed to the code that lights things.
 */
create or replace function build_action(p_action text) returns boolean language sql immutable as $$
  select p_action in (
    'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
    'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
    'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey')
$$;

create or replace function act_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql as $$
declare d action_def; p player; cx int; cy int; tx int; ty int; t tile_def; aimed text;
begin
  select * into d from action_def where id = p_action;
  if not found then return 'There is no such thing as ' || p_action || '.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  -- Deliberately not "are you busy": asked of queued jobs too. That is rpc_act's.
  if not act_ported(p_action) then
    return 'You cannot ' || lower(d.label) || ' on this island yet.';
  end if;

  aimed := p_target->>'kind';
  if aimed in ('campfire', 'smelter', 'kiln', 'furniture', 'anvil') or p_action like 'place\_%' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- The stake is in your hand and the ground is under your feet: nothing to reach for.
  if p_action = 'found_settlement' then
    return deed_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
  if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
    return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
  end if;
  if p_action = 'build_campfire' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if build_action(p_action) then
    return build_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    return terrain_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    return gather_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    return farm_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('fish', 'drag_net') then
    return fish_refusal(p_world, p_uid, p_action, p_target);
  end if;

  if exists (select 1 from recipe where id = p_action) then
    return craft_refusal(p_world, p_uid, p_action, nullif(p_target->>'uid', '')::bigint);
  end if;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    if t.dig_yield is null then return 'You cannot dig that.'; end if;
    if land_height(p_world, cx, cy) <= 0 then return 'You cannot dig below the water level.'; end if;
    if land_dirt(p_world, cx, cy) <= 0 then
      return 'That corner is bare rock. Only a pickaxe will take it lower.';
    end if;
  end if;
  return null;
end $$;

create or replace function act_perform(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tq double precision; s double precision; cx int; cy int; tx int; ty int;
        t tile_def; left_dirt int; made_ql double precision; yield text; gained double precision; tool_id bigint;
begin
  -- Before the `build_%` prefix below, which would otherwise take the walls.
  if build_action(p_action) then
    perform perform_building(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action = 'found_settlement' then
    perform perform_deed(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action like 'build\_%' or p_action like 'place\_%' or p_action like 'pick\_up\_%'
     or p_action like 'light\_%' or p_action like 'fuel\_%' or p_action like 'put\_out\_%'
     or p_action like 'damp\_%' or p_action like 'take\_ashes\_%' or p_action like 'take\_apart\_%' then
    perform perform_fire(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    perform perform_terrain(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    perform perform_gather(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    perform perform_farm(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('fish', 'drag_net') then
    perform perform_fish(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if exists (select 1 from recipe where id = p_action) then
    perform perform_craft(p_world, p_uid, p_action, p_target);
    return;
  end if;

  select * into d from action_def where id = p_action;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    select i.id into tool_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = d.tool
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'You fail to dig anything useful.', 'event');
      return;
    end if;
    perform land_set_height(p_world, cx, cy, land_height(p_world, cx, cy) - 1);
    left_dirt := land_dirt(p_world, cx, cy) - 1;
    perform land_set_dirt(p_world, cx, cy, left_dirt);
    if t.turns_to_dirt then perform land_set_tile(p_world, tx, ty, 1); end if;
    -- Dug to the rock, the tile becomes rock and shows the seam under it.
    perform reconcile_around(p_world, cx, cy);
    perform land_announce(p_world, tx, ty);
    if left_dirt <= 0 then
      perform tell(p_world, p_uid, 'Your shovel grates on bare rock.', 'event');
    end if;
    yield := coalesce(t.dig_yield, 'dirt');
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yield, 1, made_ql);
    gained := skill_raise(p_world, p_uid, d.skill, 1);
    perform tell(p_world, p_uid,
      'You dig up some ' || lower((select name from item_def where id = yield)) ||
      '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    if gained > 0 then
      perform tell(p_world, p_uid, 'Digging increased by ' || to_char(gained, 'FM0.0000') ||
        ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
    end if;
  end if;
end $$;

/**
 * Instant work happens now rather than on the next touch.
 *
 * An action with no duration still went through the same door as a six-second
 * dig: it was written down as what you are doing, given an end time of *now*,
 * and then sat there until something else came along and settled it. Renaming
 * a building and being told nothing until your next dig is not what instant
 * means, so the settle happens on the way out.
 */
create or replace function rpc_act(p_world uuid, p_action text, p_target jsonb, p_times int default 1)
  returns jsonb language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); d action_def; p player; why text; secs double precision;
        s double precision; tq double precision; cap int; room int;
begin
  if me is null then raise exception 'not signed in'; end if;
  perform settle(p_world, me);
  why := act_refusal(p_world, me, p_action, p_target);
  if why is not null then
    perform tell(p_world, me, why, 'error');
    return jsonb_build_object('started', false, 'why', why);
  end if;
  select * into d from action_def where id = p_action;
  select * into p from player where world_id = p_world and uid = me for update;

  -- Something already in hand: line this one up behind it rather than drop it.
  if p.act is not null then
    cap := queue_capacity(p_world, me);
    room := cap - 1 - jsonb_array_length(p.act_queue);
    if room <= 0 then
      why := 'You can only keep ' || cap || ' jobs in your head at once. Mind logic is what widens that.';
      perform tell(p_world, me, why, 'error');
      return jsonb_build_object('started', false, 'queued', false, 'why', why);
    end if;
    update player set act_queue = act_queue || jsonb_build_object(
        'action', p_action, 'target', p_target, 'goes', greatest(1, least(100, coalesce(p_times, 1))))
      where world_id = p_world and uid = me returning * into p;
    perform tell(p_world, me, d.label || ' is next, ' || jsonb_array_length(p.act_queue) + 1 || ' of ' || cap || ' in hand.', 'info');
    return jsonb_build_object('started', false, 'queued', true,
      'inHand', jsonb_array_length(p.act_queue) + 1, 'capacity', cap);
  end if;

  s := case when d.skill is null then 50 else skill_of(p_world, me, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, me, d.tool) end;
  -- Every other job has a floor of a second or so under it; an instant one has
  -- no duration to put a floor under, and act_duration would give it one.
  secs := case when d.instant then 0 else act_duration(d.base_time, s, tq, control_speed(p_world, me)) end;
  update player set
      act = p_action, act_target = p_target, act_started = now(),
      act_ends = now() + make_interval(secs => secs),
      act_left = greatest(1, least(100, coalesce(p_times, 1))), seen_at = now()
    where world_id = p_world and uid = me;
  if d.instant then
    perform settle(p_world, me);
    return jsonb_build_object('started', true, 'done', true, 'seconds', 0);
  end if;
  perform tell(p_world, me, 'You start ' || d.verb || '.', 'info');
  return jsonb_build_object('started', true, 'ends', now() + make_interval(secs => secs), 'seconds', secs);
end $$;

select private.lock_doors();

