-- ======================================================================
-- 20260914210400_fight.sql
-- ======================================================================

-- Swinging something, and what it leaves behind.
--
-- ## Wounds are the second thing that will not sit still
--
-- A creature moves, so it is stored as a walk. A wound *drains*, which is the
-- same problem wearing different clothes: health is not a number that sits
-- where you left it, it is a number that has been going down the whole time
-- nobody was looking. So wounds settle from a timestamp exactly as the legs
-- of a walk do — and the chance a wound goes bad, which the browser rolls
-- once a second, is rolled once over the whole elapsed stretch with the odds
-- compounded to match. One roll, the same expectation.

/* ------------------------------------------------------------------ *
 * What a thing is made of.
 * ------------------------------------------------------------------ */

/**
 * The material written on an item, as a row.
 *
 * `item.extra` holds the material the way a label does — `Oak`, `Steel` — and
 * `material_def.id` is the lower-cased form of the same word. Every lookup in
 * this database compared the two directly and so matched nothing at all: the
 * `coalesce(..., 1)` behind each one turned a miss into "made of nothing in
 * particular", which is a plausible number and therefore never noticed.
 */
create or replace function mat_of(p_extra text) returns material_def
  language sql stable as $$
  select * from material_def where id = lower(coalesce(p_extra, ''))
$$;

create or replace function mat_edge(p_extra text) returns double precision
  language sql stable as $$ select coalesce((mat_of(p_extra)).edge, 1) $$;
create or replace function mat_soak(p_extra text) returns double precision
  language sql stable as $$ select coalesce((mat_of(p_extra)).soak, 1) $$;
create or replace function mat_bane(p_extra text) returns boolean
  language sql stable as $$ select coalesce((mat_of(p_extra)).bane, false) $$;

-- The three lookups that have been quietly missing since the first migration.
create or replace function tool_worth(p_ql real, p_dmg real, p_extra text, p_rare text, p_bless real)
  returns double precision language sql stable as $$
  select least(100,
      least(100, p_ql * coalesce((mat_of(p_extra)).bite, 1))
      * rarity_boost(p_rare)
      * (1 + least(3, coalesce(p_bless, 0)) * 0.09))
    * greatest(0.3, 1 - p_dmg / 160)
$$;

/**
 * Put damage on a thing. Oak takes a third of what pine takes; seryll barely
 * marks at all — which is what the material lookup above was supposed to be
 * saying all along.
 */
create or replace function damage_item(p_item bigint, p_amount double precision) returns void
  language plpgsql as $$
declare it item;
begin
  if p_amount <= 0 then return; end if;
  select * into it from item where id = p_item;
  if not found then return; end if;
  update item set dmg = least(100, dmg + p_amount * coalesce((mat_of(it.extra)).wear, 1)
    * rarity_keep(it.rare)) where id = p_item;
  delete from item where id = p_item and dmg >= 100;
end $$;

create or replace function wear_tool(p_item bigint, p_multiplier double precision default 1)
  returns void language plpgsql as $$
declare it item;
begin
  select * into it from item where id = p_item;
  if not found then return; end if;
  perform damage_item(p_item, (0.06 + 3 / (10 + it.ql)) * p_multiplier);
end $$;

create or replace function mat_difficulty(p_extra text) returns double precision
  language sql stable as $$ select coalesce((mat_of(p_extra)).difficulty, 0) $$;

/* ------------------------------------------------------------------ *
 * What is on you and in your hands.
 * ------------------------------------------------------------------ */

create or replace function slot_of(p_def text) returns text language sql stable as $$
  select coalesce(
    (select slot from armour_def where id = p_def),
    (select 'weapon' from weapon_def where id = p_def),
    (select 'offhand' from shield_def where id = p_def),
    case when p_def = 'toolbelt' then 'belt' end)
$$;

/** What is worn or held in a slot, as an item. */
create or replace function worn(p_world uuid, p_uid uuid, p_slot text) returns item
  language sql stable as $$
  select i.* from player p
  join item i on i.id = (p.equipped->>p_slot)::bigint
    and i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
  where p.world_id = p_world and p.uid = p_uid
$$;

create or replace function two_handed_in_hand(p_world uuid, p_uid uuid) returns boolean
  language sql stable as $$
  select coalesce((select w.two_handed from weapon_def w
    where w.id = (worn(p_world, p_uid, 'weapon')).def), false)
$$;

/**
 * How much of a blow a piece of armour turns aside, given its state, what it
 * is made of and the wearer. A gold breastplate is a costly way to be killed;
 * the same plate in glimmersteel turns aside half again as much.
 */
create or replace function piece_soak(it item, p_skill double precision) returns double precision
  language sql stable as $$
  select least(0.92, c.soak * mat_soak(it.extra) * rarity_boost(it.rare)
    * (0.55 + it.ql / 220) * greatest(0.25, 1 - it.dmg / 130) * (1 + p_skill / 400))
  from armour_def a join armour_class_def c on c.id = a.cls where a.id = it.def
$$;

/**
 * Damage a weapon does in these hands, before the armour on the other side.
 * The metal of the head has as much say as the quality: a lead maul is a
 * heavy way of annoying something, and an adamantine one is not.
 */
create or replace function weapon_damage(p_world uuid, p_uid uuid, w weapon_def, it item)
  returns double precision language sql stable as $$
  select w.damage
    * case when it.id is null then 1 else mat_edge(it.extra) * rarity_boost(it.rare) end
    * (0.55 + coalesce(it.ql, 20) / 180)
    * case when it.id is null then 1 else greatest(0.4, 1 - it.dmg / 150) end
    * (0.7 + skill_of(p_world, p_uid, 'body_strength') / 90)
    * (1 + (skill_of(p_world, p_uid, w.kind) + skill_of(p_world, p_uid, 'fighting')) / 260)
$$;

/** Chance a swing lands at all: the weapon's own skill, then fighting behind it. */
create or replace function hit_chance(p_world uuid, p_uid uuid, p_kind text) returns double precision
  language sql stable as $$
  select least(0.96, 0.45 + skill_of(p_world, p_uid, p_kind) / 220
    + skill_of(p_world, p_uid, 'fighting') / 300
    + skill_of(p_world, p_uid, 'body_control') / 500)
$$;

/** Silver's old virtue: what carries its own light hates a silver edge. */
create or replace function bane_bonus() returns double precision language sql immutable as $$ select 1.5 $$;

/* ------------------------------------------------------------------ *
 * Wounds.
 * ------------------------------------------------------------------ */

create or replace function part_name(p_part text) returns text language sql immutable as $$
  select case p_part when 'arms' then 'arm' when 'legs' then 'leg' when 'feet' then 'foot'
                     when 'offhand' then 'hand' when 'weapon' then 'hand' else p_part end
$$;

/** "a deep cut to the arm, bleeding" */
create or replace function wound_text(w jsonb) returns text language sql stable as $$
  select 'a '
    || case when (w->>'severity')::double precision > 0.16 then 'deep '
            when (w->>'severity')::double precision > 0.07 then '' else 'light ' end
    || (select name from wound_kind_def where id = w->>'kind')
    || ' to the ' || part_name(w->>'part')
    || case when (w->>'infected')::boolean then ', gone bad'
            when (w->>'bleeding')::boolean then ', bleeding'
            when w->>'dressing' is not null then ', dressed' else '' end
$$;

/** What a wound is doing to you each second: blood out, or worse. */
create or replace function wound_drain(w jsonb) returns double precision language sql stable as $$
  select case when (w->>'bleeding')::boolean
           then k.bleed * (0.4 + (w->>'severity')::double precision * 3) else 0 end
       -- Something gone bad does not stop on its own, and dressing it will not do.
       + case when (w->>'infected')::boolean then k.bleed * 1.4 else 0 end
  from wound_kind_def k where k.id = w->>'kind'
$$;

/** How fast a wound closes, given what is on it. */
create or replace function wound_close(w jsonb, p_aid double precision) returns double precision
  language sql stable as $$
  select case when (w->>'infected')::boolean then 0 else
    (w->>'severity')::double precision
    * case when w->>'dressing' is null then 0.25 when w->>'dressing' = '' then 0.7
           when w->>'dressing' = k.herb then 1.6 else 0.9 end
    * (0.0006 + p_aid * 0.00002) end
  from wound_kind_def k where k.id = w->>'kind'
$$;

/**
 * The chance this wound goes bad, per second. An open wound left alone will
 * turn inside ten or twenty minutes; cloth over it is a holding measure that
 * usually holds; the wrong herb is better again; the right herb never turns.
 */
create or replace function fester_chance(w jsonb) returns double precision language sql stable as $$
  select case when (w->>'infected')::boolean or w->>'dressing' = k.herb then 0 else
    k.fester
    * case when w->>'dressing' is null then 1 when w->>'dressing' = '' then 0.12 else 0.05 end
    * (0.3 + (w->>'severity')::double precision * 2) / 60 end
  from wound_kind_def k where k.id = w->>'kind'
$$;

/** The worst wound on somebody, which is the one worth seeing to. */
create or replace function worst_wound(p_wounds jsonb) returns jsonb language sql stable as $$
  select w from jsonb_array_elements(coalesce(p_wounds, '[]'::jsonb)) w
  order by (w->>'severity')::double precision
    + case when (w->>'infected')::boolean then 1 else 0 end
    + case when (w->>'bleeding')::boolean then 0.5 else 0 end desc
  limit 1
$$;

/**
 * Everything open on somebody, brought up to the minute.
 *
 * Blood out of anything still bleeding, a little closing on anything dressed,
 * and the chance that something left alone has gone bad. The browser does
 * this every frame with a per-second chance; there is no frame here, so the
 * odds over the whole stretch are `1 - (1 - p)^seconds` and the roll happens
 * once. A wound left for ten minutes has had ten minutes to turn, whether or
 * not anybody was there to watch it.
 */
create or replace function wounds_settle(p_world uuid, p_uid uuid) returns boolean
  language plpgsql as $$
declare p player; elapsed double precision; aid double precision; w jsonb;
        out_w jsonb := '[]'::jsonb; health double precision; drained double precision := 0;
        sev double precision; turned boolean := false; kept int := 0;
begin
  select * into p from player where world_id = p_world and uid = p_uid for update;
  if not found or jsonb_array_length(coalesce(p.wounds, '[]'::jsonb)) = 0 then return false; end if;
  elapsed := extract(epoch from (now() - coalesce((p.stats->>'hurtSettled')::timestamptz, p.seen_at)));
  if elapsed <= 0 then return false; end if;
  aid := skill_of(p_world, p_uid, 'first_aid');
  health := coalesce((p.stats->>'health')::double precision, 1);

  for w in select * from jsonb_array_elements(p.wounds) loop
    drained := drained + wound_drain(w) * elapsed;
    if not (w->>'infected')::boolean
       and random() < 1 - power(1 - least(0.9, fester_chance(w)), elapsed) then
      w := jsonb_set(jsonb_set(w, '{infected}', 'true'), '{dressing}', 'null'::jsonb);
      turned := true;
    end if;
    sev := (w->>'severity')::double precision - wound_close(w, aid) * elapsed;
    if sev > 0.004 or (w->>'infected')::boolean then
      w := jsonb_set(w, '{severity}', to_jsonb(greatest(0.004, sev)));
      out_w := out_w || w;
      kept := kept + 1;
    end if;
  end loop;

  health := greatest(0, health - drained);
  update player set wounds = out_w,
      stats = jsonb_set(jsonb_set(p.stats, '{health}', to_jsonb(health)),
                        '{hurtSettled}', to_jsonb(now()))
    where world_id = p_world and uid = p_uid;
  if turned then
    perform tell(p_world, p_uid, 'Something you have been carrying has gone bad. Lye, and then a dressing.', 'error');
  end if;
  if kept = 0 and jsonb_array_length(p.wounds) > 0 then
    perform tell(p_world, p_uid, 'The last of what you were carrying has closed over.', 'event');
  end if;
  if health <= 0 then perform player_die(p_world, p_uid); end if;
  return true;
end $$;

/* ------------------------------------------------------------------ *
 * Taking a blow.
 * ------------------------------------------------------------------ */

create or replace function player_die(p_world uuid, p_uid uuid) returns void
  language plpgsql as $$
declare w world;
begin
  select * into w from world where id = p_world;
  -- Whatever killed you stays with the body. The wounds that did it would
  -- open you again in a minute, and nothing you could do would be quick
  -- enough; waking up is waking up whole.
  update player set
      stats = jsonb_build_object('health', 1, 'stamina', 0.5, 'hunger', 0.6, 'thirst', 0.6,
                                 'hurtSettled', to_jsonb(now())),
      wounds = '[]'::jsonb, x = w.spawn_x + 0.5, y = w.spawn_y + 0.5, level = 0,
      act = null, act_target = null, act_started = null, act_ends = null, act_left = null,
      act_queue = '[]'::jsonb, moved_at = now()
    where world_id = p_world and uid = p_uid;
  perform tell(p_world, p_uid, 'You have died. You wake up, shivering, where you first came ashore.', 'error');
end $$;

/**
 * Hurt somebody through their armour, and say what happened.
 *
 * The shield first, then wherever it lands, then whatever is on that place —
 * and what gets through is not only a number off the bar: it leaves a wound,
 * of a kind, in the place the blow landed, and that wound has its own life.
 */
create or replace function hurt_player(p_world uuid, p_uid uuid, p_raw double precision,
                                       p_what text, p_kind text default 'bite') returns void
  language plpgsql as $$
declare p player; shield item; sh shield_def; chance double precision; roll double precision;
        part text; piece item; cls armour_class_def; soak double precision; taken double precision;
        health double precision; ws jsonb; had jsonb; found_w boolean := false; out_w jsonb := '[]'::jsonb;
        w jsonb; k wound_kind_def; note text;
begin
  select * into p from player where world_id = p_world and uid = p_uid for update;
  if not found then return; end if;

  -- The shield, first of all.
  shield := worn(p_world, p_uid, 'offhand');
  if shield.id is not null then
    select * into sh from shield_def where id = shield.def;
    if found then
      chance := least(0.6, sh.block * (0.6 + shield.ql / 160) + skill_of(p_world, p_uid, 'shields') / 400);
      perform skill_raise(p_world, p_uid, 'shields', 0.12);
      if random() < chance then
        update item set dmg = least(100, dmg + p_raw * 3) where id = shield.id;
        perform skill_raise(p_world, p_uid, 'shields', 0.5);
        perform tell(p_world, p_uid, 'You take ' || p_what || ' on your '
          || lower((select name from item_def where id = shield.def)) || '.', 'error');
        return;
      end if;
    end if;
  end if;

  -- Then wherever it lands.
  roll := random();
  select h.slot into part from (
    select slot, sum(share) over (order by ord) as upto from hit_location) h
  where roll <= h.upto order by h.upto limit 1;
  part := coalesce(part, 'chest');

  taken := p_raw;
  note := '';
  piece := worn(p_world, p_uid, part);
  if piece.id is not null and exists (select 1 from armour_def where id = piece.def) then
    select c.* into cls from armour_def a join armour_class_def c on c.id = a.cls where a.id = piece.def;
    soak := piece_soak(piece, skill_of(p_world, p_uid, cls.skill));
    -- Armour is learned by being hit in it, and worn out the same way.
    perform skill_raise(p_world, p_uid, cls.skill, 0.4);
    update item set dmg = least(100, dmg + p_raw * 4) where id = piece.id;
    if piece.dmg + p_raw * 4 >= 100 then
      delete from item where id = piece.id;
      update player set equipped = equipped - part where world_id = p_world and uid = p_uid;
      perform tell(p_world, p_uid, 'Your ' || lower((select name from item_def where id = piece.def))
        || ' is beaten to pieces and falls away.', 'error');
    else
      note := ', though your ' || lower((select name from item_def where id = piece.def)) || ' takes the worst of it';
    end if;
    taken := p_raw * (1 - least(0.92, soak));
  end if;

  select * into k from wound_kind_def where id = p_kind;
  -- Open a wound, or deepen one of the same kind already in that place.
  for w in select * from jsonb_array_elements(coalesce(p.wounds, '[]'::jsonb)) loop
    if not found_w and w->>'kind' = p_kind and w->>'part' = part and not (w->>'infected')::boolean then
      w := jsonb_set(w, '{severity}', to_jsonb((w->>'severity')::double precision + taken));
      if k.bleed > 0.001 then w := jsonb_set(w, '{bleeding}', 'true'); end if;
      found_w := true;
    end if;
    out_w := out_w || w;
  end loop;
  if not found_w then
    -- A bruise does not bleed; everything else does until it is seen to.
    w := jsonb_build_object('kind', p_kind, 'part', part, 'severity', taken,
      'bleeding', p_kind <> 'crush', 'infected', false, 'dressing', null, 'at', now());
    out_w := out_w || w;
  end if;

  health := greatest(0, coalesce((p.stats->>'health')::double precision, 1) - taken);
  update player set wounds = out_w,
      stats = jsonb_set(jsonb_set(p.stats, '{health}', to_jsonb(health)),
                        '{hurtSettled}', to_jsonb(now()))
    where world_id = p_world and uid = p_uid;
  perform tell(p_world, p_uid, p_what || note || '. You have ' || wound_text(w) || '.', 'error');
  if health <= 0 then perform player_die(p_world, p_uid); end if;
end $$;

/* ------------------------------------------------------------------ *
 * Hurting something else.
 * ------------------------------------------------------------------ */

/** Put something down on the ground where it fell. */
create or replace function drop_on_ground(p_world uuid, p_x int, p_y int, p_def text,
    p_ql double precision, p_extra text default null, p_count int default 1) returns bigint
  language plpgsql as $$
declare new_id bigint;
begin
  values (p_world, 'ground', p_x, p_y, p_def, greatest(0, least(100, p_ql)), p_count, p_extra)
  returning id into new_id;
  return new_id;
end $$;

/**
 * Take a creature down, and leave the corpse where it fell.
 *
 * Nothing that has been hit takes food from the hand that hit it, and a timid
 * thing that survives the blow bolts: its next leg goes five tiles the other
 * way, at speed, which is what fleeing is once a walk is all a creature has.
 */
create or replace function hurt_creature(p_world uuid, p_id int, p_dmg double precision,
    p_by uuid default null) returns boolean
  language plpgsql as $$
declare c creature; d species_def; cx double precision; cy double precision;
        px double precision; py double precision; len double precision; size double precision;
begin
  perform creature_settle(p_world, p_id);
  select * into c from creature where world_id = p_world and id = p_id for update;
  if not found then return false; end if;
  select * into d from species_def where id = c.species;
  cx := creature_x(c); cy := creature_y(c);

  update creature set health = c.health - p_dmg, hurt_at = now(), coaxed = 0, coaxed_at = null,
      from_x = cx, from_y = cy, to_x = cx, to_y = cy, leg_at = now(), leg_ends = now(),
      settled_at = now()
    where world_id = p_world and id = p_id;

  if c.health - p_dmg > 0 then
    if c.mode = 'wild' and d.timid and p_by is not null then
      select p.x, p.y into px, py from player p where p.world_id = p_world and p.uid = p_by;
      len := greatest(0.001, sqrt((cx - px) ^ 2 + (cy - py) ^ 2));
      update creature set to_x = cx + ((cx - px) / len) * 5, to_y = cy + ((cy - py) / len) * 5,
          leg_ends = now() + interval '3 seconds', until = now() + interval '3 seconds'
        where world_id = p_world and id = p_id;
    end if;
    return false;
  end if;

  -- What the carcass is worth follows the size of the thing that left it.
  size := (age_row(c.born)).yield;
  delete from creature where world_id = p_world and id = p_id;
  perform drop_on_ground(p_world, floor(cx)::int, floor(cy)::int, 'corpse',
    (15 + random() * 35) * size, d.name);
  if p_by is not null then
    if d.monster then
      perform tell(p_world, p_by, 'The ' || lower(d.name)
        || ' goes down. Butcher it before it rots: there is a great deal on it.', 'system');
    else
      perform tell(p_world, p_by, 'You kill the wild ' || lower(d.name)
        || '. Its corpse lies where it fell.', 'event');
    end if;
  end if;
  return true;
end $$;

/**
 * Settling somebody now settles what is open on them too.
 *
 * Every way into this island already calls `settle`, so this is the one place
 * that has to know: touch a player and their wounds are as they would be.
 */
create or replace function settle(p_world uuid, p_uid uuid) returns int
  language plpgsql as $$
declare p player; d action_def; done int := 0; guard int := 0; nxt jsonb; ended timestamptz;
begin
  perform wounds_settle(p_world, p_uid);
  select * into p from player where world_id = p_world and uid = p_uid for update;
  if not found or p.act is null then return 0; end if;
  while p.act is not null and p.act_ends <= now() and guard < 200 loop
    guard := guard + 1;
    perform act_perform(p_world, p_uid, p.act, p.act_target);
    done := done + 1;
    select * into d from action_def where id = p.act;
    ended := p.act_ends;
    if p.act_left > 1 and act_refusal(p_world, p_uid, p.act, p.act_target) is null then
      update player set act_left = act_left - 1, act_started = ended,
             act_ends = ended + make_interval(secs => act_duration(
               d.base_time,
               case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end,
               case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end,
               control_speed(p_world, p_uid)))
        where world_id = p_world and uid = p_uid returning * into p;
    else
      if p.act_left > 1 then
        perform tell(p_world, p_uid, 'You stop ' || d.verb || '.', 'info');
      end if;
      nxt := p.act_queue -> 0;
      if nxt is null then
        update player set act = null, act_target = null, act_started = null, act_ends = null, act_left = null
          where world_id = p_world and uid = p_uid returning * into p;
      else
        select * into d from action_def where id = nxt->>'action';
        if d is null or act_refusal(p_world, p_uid, nxt->>'action', nxt->'target') is not null then
          perform tell(p_world, p_uid,
            coalesce(act_refusal(p_world, p_uid, nxt->>'action', nxt->'target'), 'That cannot be done now.'), 'error');
          update player set act = null, act_target = null, act_started = null, act_ends = null,
                 act_left = null, act_queue = act_queue - 0
            where world_id = p_world and uid = p_uid returning * into p;
        else
          update player set act = nxt->>'action', act_target = nxt->'target',
                 act_left = greatest(1, coalesce((nxt->>'goes')::int, 1)),
                 act_started = ended,
                 act_ends = ended + make_interval(secs => act_duration(
                   d.base_time,
                   case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end,
                   case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end,
                   control_speed(p_world, p_uid))),
                 act_queue = act_queue - 0
            where world_id = p_world and uid = p_uid returning * into p;
          perform tell(p_world, p_uid, 'You start ' || d.verb || '.', 'info');
        end if;
      end if;
    end if;
  end loop;
  return done;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914210500_fight_acts.sql
-- ======================================================================

-- Wearing it, swinging it, and what you do about the state it leaves you in.

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field',
      'fish', 'drag_net',
      'found_settlement',
      'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
      'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
      'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey',
      'examine_creature', 'tame', 'feed', 'groom', 'shear', 'milk_creature',
      'set_stance', 'rename_creature', 'take_creature', 'store_creature', 'release_creature',
      'equip', 'unequip', 'attack_creature', 'shoot_creature', 'butcher',
      'bind_wound', 'clean_wound', 'treat_creature',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

create or replace function fight_action(p_action text) returns boolean language sql immutable as $$
  select p_action in ('equip', 'unequip', 'attack_creature', 'shoot_creature', 'butcher',
                      'bind_wound', 'clean_wound', 'treat_creature')
$$;

/** How far you can reach with what is in your hand. */
create or replace function melee_reach(p_world uuid, p_uid uuid) returns double precision
  language sql stable as $$
  select coalesce((select greatest(2.2, coalesce(w.range, 1) + 1.2) from weapon_def w
    where w.id = (worn(p_world, p_uid, 'weapon')).def and w.ammo is null), 2.2)
$$;

/**
 * What is actually going to hit it. A bow is no use swung and bare hands are
 * the fallback either way, so this answers with the weapon row and, separately,
 * whether there is an item behind it.
 */
create or replace function swung_with(p_world uuid, p_uid uuid) returns weapon_def
  language sql stable as $$
  select coalesce(
    (select w from weapon_def w where w.id = (worn(p_world, p_uid, 'weapon')).def and w.ammo is null),
    -- Bare hands: what you fight with when there is nothing in them.
    row('fist', 'knives', 3, 1.8, null, null, false)::weapon_def)
$$;

create or replace function swung_item(p_world uuid, p_uid uuid) returns item
  language sql stable as $$
  select q.it from (select worn(p_world, p_uid, 'weapon') as it) q
  where exists (select 1 from weapon_def w where w.id = (q.it).def and w.ammo is null)
$$;

/** The corpse a target names, wherever it is lying. */
create or replace function target_corpse(p_world uuid, p_uid uuid, p_target jsonb) returns item
  language sql stable as $$
  select i.* from item i
  where i.world_id = p_world and i.def = 'corpse'
    and case p_target->>'kind'
      when 'ground' then i.holder = 'ground' and i.gx = (p_target->>'x')::int and i.gy = (p_target->>'y')::int
        and (p_target->>'uid' is null or i.id = (p_target->>'uid')::bigint)
      else i.holder = 'player' and i.holder_uid = p_uid and i.id = (p_target->>'uid')::bigint end
  order by i.id limit 1
$$;

/** The species a corpse came off, read from the name written on it. */
create or replace function corpse_species(p_extra text) returns species_def
  language sql stable as $$ select * from species_def where lower(name) = lower(coalesce(p_extra, '')) $$;

/**
 * How much of a carcass is worth keeping. Bare hands manage about a third; a
 * knife's quality and the butchering skill lift that towards the whole animal,
 * which the species' table caps.
 */
create or replace function butcher_yield(p_skill double precision, p_knife_ql double precision)
  returns double precision language sql immutable as $$
  select least(1, (case when p_knife_ql is null then 0.34 else 0.62 + (p_knife_ql / 100) * 0.3 end)
    + (p_skill / 100) * 0.28)
$$;

/** The soundest dressing carried: the right herb, any herb, or plain cloth. */
create or replace function dressing_for(p_world uuid, p_uid uuid, w jsonb) returns item
  language sql stable as $$
  select i.* from item i
  where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
    and i.def in ('cover', 'bandage')
  order by
    (i.def = 'cover' and lower(coalesce(i.extra, '')) =
      (select k.herb from wound_kind_def k where k.id = w->>'kind')) desc,
    (i.def = 'cover') desc, i.ql desc
  limit 1
$$;

create or replace function fight_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql as $$
declare it item; c creature; d species_def; w weapon_def; bow weapon_def; dist double precision;
        p player; slot text; corpse item; hurt jsonb; use item;
begin
  select * into p from player where world_id = p_world and uid = p_uid;

  if p_action in ('equip', 'unequip') then
    select * into it from item where id = (p_target->>'uid')::bigint
      and world_id = p_world and holder = 'player' and holder_uid = p_uid;
    if not found then return 'It is gone.'; end if;
    slot := slot_of(it.def);
    if slot is null then return 'That is not worn or wielded.'; end if;
    if p_action = 'unequip' then
      return case when (p.equipped->>slot)::bigint is distinct from it.id
                  then 'You are not wearing that.' end;
    end if;
    if (p.equipped->>slot)::bigint = it.id then return 'You already have it on.'; end if;
    if slot = 'offhand' and two_handed_in_hand(p_world, p_uid) then
      return 'Both your hands are on your weapon.';
    end if;
    return null;

  elsif p_action in ('attack_creature', 'shoot_creature', 'treat_creature') then
    perform creature_settle(p_world, (p_target->>'id')::int);
    c := target_creature(p_world, p_target);
    if c.world_id is null then return 'It is dead or gone.'; end if;
    select * into d from species_def where id = c.species;
    dist := (select sqrt((creature_x(c) - pl.x) ^ 2 + (creature_y(c) - pl.y) ^ 2)
             from player pl where pl.world_id = p_world and pl.uid = p_uid);
    if p_action = 'attack_creature' then
      if c.mode <> 'wild' then return 'That one is tame. Release it first if you mean it.'; end if;
      if dist > melee_reach(p_world, p_uid) then return 'It is out of reach.'; end if;
      return null;
    elsif p_action = 'shoot_creature' then
      if c.mode <> 'wild' then return 'That one is tame. Release it first if you mean it.'; end if;
      select bw.* into bow from weapon_def bw where bw.id = (worn(p_world, p_uid, 'weapon')).def and bw.ammo is not null;
      if not found then return 'You have no bow in your hands.'; end if;
      if pack_count(p_world, p_uid, bow.ammo) <= 0 then return 'You are out of arrows.'; end if;
      if dist > coalesce(bow.range, 6) then
        return 'Too far for a ' || lower((select name from item_def where id = bow.id)) || '.';
      end if;
      if dist < 1.2 then return 'It is too close to draw on.'; end if;
      return null;
    else
      if c.mode = 'wild' then return 'It will not stand still for you while it is wild.'; end if;
      if c.health >= max_health(c) then return c.name || ' is not hurt.'; end if;
      if pack_count(p_world, p_uid, 'bandage') <= 0 then return 'You have no bandages. Cut some from cloth.'; end if;
      if dist > 1.9 then return 'You need to be beside it.'; end if;
      return null;
    end if;

  elsif p_action = 'butcher' then
    corpse := target_corpse(p_world, p_uid, p_target);
    if corpse.id is null then return 'There is nothing to butcher.'; end if;
    if (corpse_species(corpse.extra)).id is null then return 'You cannot make sense of this carcass.'; end if;
    return null;

  elsif p_action = 'bind_wound' then
    perform wounds_settle(p_world, p_uid);
    select * into p from player where world_id = p_world and uid = p_uid;
    hurt := worst_wound(p.wounds);
    if hurt is null then
      return case when coalesce((p.stats->>'health')::double precision, 1) >= 0.999
        then 'There is nothing wrong with you.' else 'Nothing is open. You are only tired and thin.' end;
    end if;
    if (hurt->>'infected')::boolean then
      return 'The ' || (select name from wound_kind_def where id = hurt->>'kind')
        || ' on your ' || part_name(hurt->>'part')
        || ' has gone bad. Clean it out before anything will hold on it.';
    end if;
    use := dressing_for(p_world, p_uid, hurt);
    if use.id is null then return 'You have nothing to dress it with.'; end if;
    return null;

  elsif p_action = 'clean_wound' then
    perform wounds_settle(p_world, p_uid);
    select * into p from player where world_id = p_world and uid = p_uid;
    if not exists (select 1 from jsonb_array_elements(coalesce(p.wounds, '[]'::jsonb)) x
                   where (x->>'infected')::boolean) then
      return 'Nothing on you has gone bad.';
    end if;
    if pack_count(p_world, p_uid, 'lye_bucket') <= 0 then
      return 'You need a bucket of lye to clean it out with.';
    end if;
    return null;
  end if;
  return null;
end $$;

create or replace function perform_fight(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare it item; p player; slot text; shield item; c creature; d species_def; w weapon_def;
        bow weapon_def; arrow item; held item; dist double precision; dmg double precision;
        bane double precision; before double precision; died boolean; reach double precision;
        corpse item; sp species_def; knife_ql double precision; v_share double precision;
        made_ql double precision; taken text[] := '{}'; r record; v_n int; lumps text[] := '{}';
        hurt jsonb; use item; suits boolean; clean boolean; healed double precision;
        top double precision; out_w jsonb; one jsonb; lye item; got text;
begin
  select * into p from player where world_id = p_world and uid = p_uid;

  if p_action = 'equip' then
    select * into it from item where id = (p_target->>'uid')::bigint;
    slot := slot_of(it.def);
    update player set equipped = jsonb_set(equipped, array[slot], to_jsonb(it.id))
      where world_id = p_world and uid = p_uid returning * into p;
    -- Both hands on it means nothing else in them.
    if slot = 'weapon' and coalesce((select two_handed from weapon_def where id = it.def), false) then
      shield := worn(p_world, p_uid, 'offhand');
      if shield.id is not null then
        update player set equipped = equipped - 'offhand' where world_id = p_world and uid = p_uid;
        perform tell(p_world, p_uid, 'You need both hands for that, so the '
          || lower((select name from item_def where id = shield.def)) || ' goes on your back.', 'info');
      end if;
    end if;
    perform tell(p_world, p_uid, 'You '
      || case when slot in ('weapon', 'offhand') then 'take up' else 'put on' end
      || ' the ' || lower((select name from item_def where id = it.def)) || '.', 'info');

  elsif p_action = 'unequip' then
    select * into it from item where id = (p_target->>'uid')::bigint;
    slot := slot_of(it.def);
    update player set equipped = equipped - slot where world_id = p_world and uid = p_uid;
    perform tell(p_world, p_uid, 'You put the '
      || lower((select name from item_def where id = it.def)) || ' away.', 'info');

  elsif p_action = 'attack_creature' then
    c := target_creature(p_world, p_target);
    if c.world_id is null then return; end if;
    select * into d from species_def where id = c.species;
    w := swung_with(p_world, p_uid);
    held := swung_item(p_world, p_uid);
    before := c.health;
    perform skill_raise(p_world, p_uid, 'fighting', 0.3);
    perform skill_raise(p_world, p_uid, w.kind, 0.45);
    perform skill_raise(p_world, p_uid, 'body_strength', 0.05);
    if random() > hit_chance(p_world, p_uid, w.kind) then
      perform tell(p_world, p_uid, 'You swing at the ' || lower(d.name)
        || case when held.id is null then '' else ' with your '
             || lower((select name from item_def where id = held.def)) end || ' and miss.', 'event');
    else
      bane := case when held.id is not null and mat_bane(held.extra) and d.glow is not null
                   then bane_bonus() else 1 end;
      dmg := weapon_damage(p_world, p_uid, w, held) * bane * (0.75 + random() * 0.5);
      died := hurt_creature(p_world, c.id, dmg, p_uid);
      if held.id is not null then perform damage_item(held.id, 0.35); end if;
      if not died then
        perform tell(p_world, p_uid, 'You strike the ' || lower(d.name)
          || case when held.id is null then '' else ' with your '
               || lower((select name from item_def where id = held.def)) end
          || '. It is down to ' || greatest(0, ceil(c.health - dmg)) || ' of ' || max_health(c) || '.', 'event');
      end if;
    end if;
    -- A cornered animal gets a swipe in, and the defensive sorts never miss their chance.
    if not coalesce(died, false) and (d.defensive or random() < 0.35) then
      perform hurt_player(p_world, p_uid, attack_of(c) * 0.012,
        'The ' || lower(d.name) || case when d.defensive then ' comes straight back at you'
                                        else ' turns on you' end,
        coalesce(d.wound, 'bite'));
    end if;

  elsif p_action = 'shoot_creature' then
    c := target_creature(p_world, p_target);
    if c.world_id is null then return; end if;
    select * into d from species_def where id = c.species;
    held := worn(p_world, p_uid, 'weapon');
    select bw.* into bow from weapon_def bw where bw.id = held.def and bw.ammo is not null;
    if not found then return; end if;
    select i.* into arrow from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = bow.ammo
      order by i.ql desc limit 1;
    if arrow.id is null or not consume(p_world, p_uid, bow.ammo, 1, arrow.id) then return; end if;
    dist := (select sqrt((creature_x(c) - pl.x) ^ 2 + (creature_y(c) - pl.y) ^ 2)
             from player pl where pl.world_id = p_world and pl.uid = p_uid);
    perform skill_raise(p_world, p_uid, 'fighting', 0.2);
    perform skill_raise(p_world, p_uid, 'archery', 0.5);
    -- The far end of a bow's range is a far harder shot than the near end.
    if random() > hit_chance(p_world, p_uid, 'archery') * (1 - (dist / coalesce(bow.range, 6)) * 0.35) then
      perform tell(p_world, p_uid, 'Your arrow goes wide of the ' || lower(d.name) || '.', 'event');
    else
      -- The stave throws it; the head is what goes in. Both have a say.
      bane := case when mat_bane(arrow.extra) and d.glow is not null then bane_bonus() else 1 end;
      dmg := weapon_damage(p_world, p_uid, bow, held) * mat_edge(arrow.extra) * bane
             * (0.6 + arrow.ql / 140) * (0.8 + random() * 0.4);
      died := hurt_creature(p_world, c.id, dmg, p_uid);
      perform damage_item(held.id, 0.25);
      if not died then
        perform tell(p_world, p_uid, 'Your arrow goes home. The ' || lower(d.name)
          || ' is down to ' || greatest(0, ceil(c.health - dmg)) || ' of ' || max_health(c) || '.', 'event');
      end if;
    end if;

  elsif p_action = 'butcher' then
    corpse := target_corpse(p_world, p_uid, p_target);
    sp := corpse_species(corpse.extra);
    if corpse.id is null or sp.id is null then return; end if;
    knife_ql := nullif(tool_ql(p_world, p_uid, 'butchering_knife'), 0);
    v_share := butcher_yield(skill_of(p_world, p_uid, 'butchering'), knife_ql);
    made_ql := product_ql(skill_of(p_world, p_uid, 'butchering'), coalesce(knife_ql, 0))
               * (0.6 + corpse.ql / 250);
    -- What it was sleeping on, which is not a part of it at all.
    for r in select sb.n from species_butcher sb where sb.species = sp.id and sb.part = 'hoard' loop
      for v_n in 1..round(r.n * (4 + v_share * 6))::int loop
        select item into got from hoard_metal order by random() limit 1;
        perform give(p_world, p_uid, got, 1, greatest(20, least(100, 40 + random() * 55)));
        lumps := lumps || lower((select name from item_def where id = got));
      end loop;
    end loop;
    if array_length(lumps, 1) > 0 then
      perform tell(p_world, p_uid, 'Something rattles as the belly opens: ' || array_length(lumps, 1)
        || ' lumps of what it had been sleeping on. '
        || (select string_agg(distinct l, ', ') from unnest(lumps) l) || '.', 'event');
    end if;
    /* `n` was a plpgsql variable here and `species_butcher.n` a column, and
     * Postgres would not guess which was meant. That is the fourth time on
     * this island — `land_tile.y`, `crop.y`, `trait_def.tier` — so the locals
     * that could collide carry a prefix. */
    for r in select b.part, b.item, sb.n from butcher_part b
             join species_butcher sb on sb.part = b.part and sb.species = sp.id
             order by b.ord loop
      v_n := floor(r.n * v_share)::int;
      -- The remainder is a chance at one more, so a poor job still gives something.
      if random() < r.n * v_share - v_n then v_n := v_n + 1; end if;
      -- Glands are the rare part: only a steady hand finds them intact.
      if r.part = 'gland' and v_n > 0 and random() > 0.35 * (0.5 + v_share) then v_n := 0; end if;
      if v_n <= 0 then continue; end if;
      perform give(p_world, p_uid, r.item, v_n, greatest(1, least(100, made_ql)));
      taken := taken || (case when v_n > 1 then v_n || ' × ' else '' end
        || lower((select name from item_def where id = r.item)));
    end loop;
    delete from item where id = corpse.id;
    if array_length(taken, 1) is null then
      perform tell(p_world, p_uid, 'You make a mess of the ' || lower(sp.name)
        || ' carcass and salvage nothing.', 'event');
    else
      perform tell(p_world, p_uid, 'You butcher the ' || lower(sp.name) || ' and take '
        || array_to_string(taken, ', ') || '.'
        || case when knife_ql is null then ' Bare hands waste most of a carcass.' else '' end, 'event');
    end if;

  elsif p_action = 'bind_wound' then
    select * into p from player where world_id = p_world and uid = p_uid;
    hurt := worst_wound(p.wounds);
    if hurt is null or (hurt->>'infected')::boolean then return; end if;
    use := dressing_for(p_world, p_uid, hurt);
    if use.id is null or not consume(p_world, p_uid, use.def, 1, use.id) then return; end if;
    got := case when use.def = 'cover' then lower(coalesce(use.extra, '')) else '' end;
    suits := got = (select herb from wound_kind_def where id = hurt->>'kind');
    clean := skill_check(skill_of(p_world, p_uid, 'first_aid'), 10, use.ql);
    -- Cloth holds a dressing on. The right herb closes the wound.
    healed := (0.06 + (skill_of(p_world, p_uid, 'first_aid') / 100) * 0.24 + (use.ql / 100) * 0.1)
              * (case when clean then 1 else 0.35 end)
              * (case when suits then 1.5 when got <> '' then 1.1 else 1 end);
    out_w := '[]'::jsonb;
    for one in select * from jsonb_array_elements(p.wounds) loop
      if one = hurt then
        one := jsonb_set(one, '{severity}', to_jsonb(greatest(0, (one->>'severity')::double precision - healed)));
        if clean then one := jsonb_set(jsonb_set(one, '{dressing}', to_jsonb(got)), '{bleeding}', 'false'); end if;
      end if;
      if (one->>'severity')::double precision > 0.004 or (one->>'infected')::boolean then
        out_w := out_w || one;
      end if;
    end loop;
    update player set wounds = out_w,
        stats = jsonb_set(p.stats, '{health}',
          to_jsonb(least(1, coalesce((p.stats->>'health')::double precision, 1) + healed)))
      where world_id = p_world and uid = p_uid;
    perform skill_raise(p_world, p_uid, 'first_aid', 0.35);
    perform tell(p_world, p_uid, case
      when not clean then 'The dressing slips and you make a poor job of it. You still have '
        || wound_text(hurt) || '.'
      when suits then 'You lay the ' || got
        || ' cover on and bind it. The bleeding stops at once and it is already closing.'
      when got <> '' then 'You bind the ' || got || ' cover over it. It is the wrong herb for a '
        || (select name from wound_kind_def where id = hurt->>'kind')
        || ', but it holds and the bleeding stops.'
      else 'You clean it and bind it with cloth. The bleeding stops, though it will be slow to close.'
      end, 'event');

  elsif p_action = 'clean_wound' then
    select * into p from player where world_id = p_world and uid = p_uid;
    select i.* into lye from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = 'lye_bucket'
      order by i.ql desc limit 1;
    if lye.id is null or not consume(p_world, p_uid, 'lye_bucket', 1, lye.id) then return; end if;
    perform give(p_world, p_uid, 'bucket', 1, lye.ql);
    clean := skill_check(skill_of(p_world, p_uid, 'first_aid'), 26, lye.ql);
    perform skill_raise(p_world, p_uid, 'first_aid', 0.8);
    select x into hurt from jsonb_array_elements(p.wounds) x where (x->>'infected')::boolean limit 1;
    if not clean then
      perform tell(p_world, p_uid, 'You scour the '
        || (select name from wound_kind_def where id = hurt->>'kind')
        || ' out and it is no better for it. The lye is gone.', 'error');
      return;
    end if;
    out_w := '[]'::jsonb;
    for one in select * from jsonb_array_elements(p.wounds) loop
      if one = hurt then
        one := jsonb_set(jsonb_set(jsonb_set(one, '{infected}', 'false'),
          '{bleeding}', 'true'), '{dressing}', 'null'::jsonb);
      end if;
      out_w := out_w || one;
    end loop;
    update player set wounds = out_w where world_id = p_world and uid = p_uid;
    perform tell(p_world, p_uid, 'You scour the '
      || (select name from wound_kind_def where id = hurt->>'kind') || ' on your '
      || part_name(hurt->>'part') || ' out with lye. It is open and clean again, and bleeding. Dress it.', 'event');

  elsif p_action = 'treat_creature' then
    c := target_creature(p_world, p_target);
    if c.world_id is null then return; end if;
    select i.* into use from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = 'bandage'
      order by i.ql desc limit 1;
    if use.id is null or not consume(p_world, p_uid, 'bandage', 1, use.id) then return; end if;
    clean := skill_check(skill_of(p_world, p_uid, 'first_aid'), 14, use.ql);
    top := max_health(c);
    healed := top * (0.06 + (skill_of(p_world, p_uid, 'first_aid') / 100) * 0.24 + (use.ql / 100) * 0.1)
              * (case when clean then 1 else 0.35 end);
    update creature set health = least(top, health + healed)
      where world_id = p_world and id = c.id returning * into c;
    perform skill_raise(p_world, p_uid, 'first_aid', 0.35);
    perform tell(p_world, p_uid, case when clean
      then 'You dress ' || c.name || '''s wounds with the '
        || lower((select name from item_def where id = 'bandage')) || '. It is up to '
      else c.name || ' will not hold still and the dressing goes on badly. It is up to '
      end || ceil(c.health) || ' of ' || top || '.', 'event');
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914210600_dispatch9.sql
-- ======================================================================

-- The dispatcher, with a weapon in its hand.

/**
 * Which jobs belong to the building code.
 *
 * Written as a list rather than a prefix on purpose: `build_wall` and
 * `build_floor` share their first word with `build_campfire`, and the
 * dispatcher used to send anything beginning with `build_` to the fires. A
 * prefix that was unambiguous when it was written stopped being so the moment
 * a second family wanted the same verb, and nothing would have said so — the
 * wall would simply have been handed to the code that lights things.
 */
create or replace function build_action(p_action text) returns boolean language sql immutable as $$
  select p_action in (
    'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
    'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
    'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey')
$$;

create or replace function act_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql as $$
declare d action_def; p player; cx int; cy int; tx int; ty int; t tile_def; aimed text;
begin
  select * into d from action_def where id = p_action;
  if not found then return 'There is no such thing as ' || p_action || '.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  -- Deliberately not "are you busy": asked of queued jobs too. That is rpc_act's.
  if not act_ported(p_action) then
    return 'You cannot ' || lower(d.label) || ' on this island yet.';
  end if;

  aimed := p_target->>'kind';
  if aimed in ('campfire', 'smelter', 'kiln', 'furniture', 'anvil') or p_action like 'place\_%' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- The stake is in your hand and the ground is under your feet: nothing to reach for.
  if p_action = 'found_settlement' then
    return deed_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- A creature is not at a tile, it is wherever its last leg left it, so the
  -- reach check below cannot answer for it. Both of these do their own; the
  -- fighting ones reach as far as what is in your hand, which is further.
  if creature_action(p_action) then
    return creature_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if fight_action(p_action) then
    return fight_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
  if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
    return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
  end if;
  if p_action = 'build_campfire' then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if build_action(p_action) then
    return build_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    return terrain_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    return gather_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    return farm_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('fish', 'drag_net') then
    return fish_refusal(p_world, p_uid, p_action, p_target);
  end if;

  if exists (select 1 from recipe where id = p_action) then
    return craft_refusal(p_world, p_uid, p_action, nullif(p_target->>'uid', '')::bigint);
  end if;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    if t.dig_yield is null then return 'You cannot dig that.'; end if;
    if land_height(p_world, cx, cy) <= 0 then return 'You cannot dig below the water level.'; end if;
    if land_dirt(p_world, cx, cy) <= 0 then
      return 'That corner is bare rock. Only a pickaxe will take it lower.';
    end if;
  end if;
  return null;
end $$;

create or replace function act_perform(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tq double precision; s double precision; cx int; cy int; tx int; ty int;
        t tile_def; left_dirt int; made_ql double precision; yield text; gained double precision; tool_id bigint;
begin
  -- Before the `build_%` prefix below, which would otherwise take the walls.
  if build_action(p_action) then
    perform perform_building(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action = 'found_settlement' then
    perform perform_deed(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if creature_action(p_action) then
    perform perform_creature(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if fight_action(p_action) then
    perform perform_fight(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action like 'build\_%' or p_action like 'place\_%' or p_action like 'pick\_up\_%'
     or p_action like 'light\_%' or p_action like 'fuel\_%' or p_action like 'put\_out\_%'
     or p_action like 'damp\_%' or p_action like 'take\_ashes\_%' or p_action like 'take\_apart\_%' then
    perform perform_fire(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    perform perform_terrain(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    perform perform_gather(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    perform perform_farm(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('fish', 'drag_net') then
    perform perform_fish(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if exists (select 1 from recipe where id = p_action) then
    perform perform_craft(p_world, p_uid, p_action, p_target);
    return;
  end if;

  select * into d from action_def where id = p_action;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    select i.id into tool_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = d.tool
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'You fail to dig anything useful.', 'event');
      return;
    end if;
    perform land_set_height(p_world, cx, cy, land_height(p_world, cx, cy) - 1);
    left_dirt := land_dirt(p_world, cx, cy) - 1;
    perform land_set_dirt(p_world, cx, cy, left_dirt);
    if t.turns_to_dirt then perform land_set_tile(p_world, tx, ty, 1); end if;
    -- Dug to the rock, the tile becomes rock and shows the seam under it.
    perform reconcile_around(p_world, cx, cy);
    perform land_announce(p_world, tx, ty);
    if left_dirt <= 0 then
      perform tell(p_world, p_uid, 'Your shovel grates on bare rock.', 'event');
    end if;
    yield := coalesce(t.dig_yield, 'dirt');
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yield, 1, made_ql);
    gained := skill_raise(p_world, p_uid, d.skill, 1);
    perform tell(p_world, p_uid,
      'You dig up some ' || lower((select name from item_def where id = yield)) ||
      '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    if gained > 0 then
      perform tell(p_world, p_uid, 'Digging increased by ' || to_char(gained, 'FM0.0000') ||
        ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
    end if;
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914212000_worker.sql
-- ======================================================================

-- Wildermon set to work on the deed.
--
-- ## A worker is a round trip
--
-- A wild creature wanders: legs with no purpose, and the last one is as good
-- an answer as any to where it is. A worker is doing something, and a round
-- trip has parts — out to a tile, work it, back to the crate, put the load
-- down — each of which begins and ends at a moment. So a worker is stored as
-- which part of the trip it is in and when that part is over, and settling it
-- walks it through as many whole trips as have come due.
--
-- Which means the result of an hour of a worker's labour is a loop over the
-- clock rather than an hour of simulation: the logs are in the crate because
-- the arithmetic says they would be, and nothing had to be running to put
-- them there.

/* ------------------------------------------------------------------ *
 * Somewhere to put a load down.
 * ------------------------------------------------------------------ */

/**
 * The settlement's own crate.
 *
 * Only this one, for now: crates you make, place and stuff by hand are their
 * own family. This is the one the token comes with, and it is here because a
 * worker that has nowhere to put a log is a worker doing nothing.
 */
create table if not exists crate (
  world_id uuid not null references world on delete cascade,
  id int not null,
  kind text not null default 'plank' check (kind in ('log', 'plank')),
  x int not null,
  y int not null,
  sx int not null default 1,
  sy int not null default 1,
  material text,
  name text,
  /** The settlement's own, which is where a worker takes things by default. */
  deed boolean not null default false,
  primary key (world_id, id)
);
alter table crate enable row level security;
drop policy if exists crate_read on crate;
create policy crate_read on crate for select to authenticated using (true);
grant select on crate to authenticated;
revoke insert, update, delete on crate from anon, authenticated;

-- What is in one. `holder = 'crate'` and the crate's own number, which is not
-- an item number, so it wants a column of its own rather than `inside`.
alter table item add column if not exists crate int;
create index if not exists item_in_crate on item (world_id, crate) where holder = 'crate';

create or replace function crate_capacity(c crate) returns int language sql stable as $$
  select round(case c.kind when 'log' then 30 else 60 end
    * coalesce((mat_of(c.material)).hold, 1))::int
$$;

create or replace function crate_units(p_world uuid, p_id int) returns int language sql stable as $$
  select coalesce(sum(count), 0)::int from item
  where world_id = p_world and holder = 'crate' and crate = p_id
$$;

create or replace function crate_centre_x(c crate) returns double precision
  language sql immutable as $$ select c.x + (c.sx + 0.5) / 4.0 $$;
create or replace function crate_centre_y(c crate) returns double precision
  language sql immutable as $$ select c.y + (c.sy + 0.5) / 4.0 $$;

create or replace function deed_crate(p_world uuid) returns crate language sql stable as $$
  select * from crate where world_id = p_world and deed order by id limit 1
$$;

/** Put something in a crate, or say it would not go. */
create or replace function crate_add(p_world uuid, p_id int, p_def text, p_count int,
    p_ql double precision, p_extra text default null) returns boolean
  language plpgsql as $$
declare c crate; stacks boolean; into_id bigint;
begin
  select * into c from crate where world_id = p_world and id = p_id;
  if not found then return false; end if;
  if crate_units(p_world, p_id) + p_count > crate_capacity(c) then return false; end if;
  select coalesce(d.stackable, false) into stacks from item_def d where d.id = p_def;
  if stacks then
    select i.id into into_id from item i
    where i.world_id = p_world and i.holder = 'crate' and i.crate = p_id and i.def = p_def
      and i.extra is not distinct from p_extra
    limit 1;
    if into_id is not null then
      update item set ql = (ql * count + p_ql * p_count) / (count + p_count), count = count + p_count
        where id = into_id;
      return true;
    end if;
  end if;
  values (p_world, 'crate', p_id, c.x, c.y, p_def, greatest(0, least(100, p_ql)), p_count, p_extra);
  return true;
end $$;

/** Stand the settlement's crate beside the token, on the first tile that will have it. */
create or replace function place_deed_crate(p_world uuid) returns int
  language plpgsql as $$
declare d deed; spot record; new_id int;
begin
  select * into d from deed where world_id = p_world;
  if not found or (deed_crate(p_world)).id is not null then return null; end if;
  select gx, gy into spot from (values (1, 0), (0, 1), (-1, 0), (0, -1), (1, 1)) as v(dx, dy),
    lateral (select d.x + v.dx as gx, d.y + v.dy as gy) q
  where in_bounds(p_world, q.gx, q.gy) and passable(p_world, q.gx, q.gy)
    and not has_water(p_world, q.gx, q.gy)
    and building_at(p_world, q.gx, q.gy) is null
    and not exists (select 1 from crate cr where cr.world_id = p_world and cr.x = q.gx and cr.y = q.gy)
  limit 1;
  if not found then return null; end if;
  select coalesce(max(id), 0) + 1 into new_id from crate where world_id = p_world;
  return new_id;
end $$;

/* ------------------------------------------------------------------ *
 * The worker itself.
 * ------------------------------------------------------------------ */

alter table creature add column if not exists job text;
alter table creature add column if not exists phase text not null default 'idle';
alter table creature add column if not exists work_x int;
alter table creature add column if not exists work_y int;
alter table creature add column if not exists carrying jsonb;

/** How long a worker takes over a task: twice what a player of the same skill would. */
create or replace function work_duration(p_skill double precision) returns double precision
  language sql immutable as $$ select 2 * greatest(1.2, 5 * (1 - p_skill / 140)) $$;

/** A worker's task skill, or 1 for a species with no trade. */
create or replace function task_skill(c creature) returns double precision
  language sql stable as $$
  select coalesce((c.skills->>(select skill from gather_def where id =
    (select gathers from species_def where id = c.species)))::double precision, 1)
$$;

/** Every ten levels of its trade let a worker range ten tiles further from the token. */
create or replace function work_range(c creature) returns int language sql stable as $$
  select round((d.work_range + floor(task_skill(c) / 10) * 10) * trait_mul(c.traits, 'range'))::int
  from species_def d where d.id = c.species
$$;

create or replace function workers_on_deed(p_world uuid) returns int language sql stable as $$
  select count(*)::int from creature where world_id = p_world and mode = 'deed'
$$;

/** How many wildermon may work the deed at this level. */
create or replace function worker_cap(p_world uuid) returns int language sql stable as $$
  select coalesce((select level from deed where world_id = p_world), 0)
$$;

/** One tile to one worker: nobody else's seam, tree or field. */
create or replace function claimed(p_world uuid, p_x int, p_y int, p_id int) returns boolean
  language sql stable as $$
  select exists (select 1 from creature c where c.world_id = p_world and c.mode = 'deed'
    and c.id <> p_id and c.work_x = p_x and c.work_y = p_y and c.phase in ('out', 'work'))
$$;

/** A tile beside one that cannot be stood on: a tree, or open water. */
create or replace function beside_tile(p_world uuid, p_x int, p_y int)
  returns table (x int, y int) language sql stable as $$
  select p_x + dx, p_y + dy from (values (1,0), (-1,0), (0,1), (0,-1)) as v(dx, dy)
  where creature_tile_ok(p_world, p_x + dx, p_y + dy)
  limit 1
$$;

/**
 * Whether a tile is worth a worker walking to, for its trade.
 *
 * Every one of these rules is already in this database somewhere — a forage
 * bed's cooldown, a seam's metal and its level, a field that has come ripe.
 * A worker is not a second set of rules, it is the same ones with nobody
 * watching.
 */
create or replace function worker_gatherable(p_world uuid, p_x int, p_y int, p_kind text, c creature)
  returns boolean language plpgsql stable as $$
declare here int; t tile_def; rock rock_def;
begin
  if not in_bounds(p_world, p_x, p_y) or claimed(p_world, p_x, p_y, c.id) then return false; end if;
  here := land_tile(p_world, p_x, p_y);
  select * into t from tile_def where id = here;

  if p_kind = 'woodcut' then
    -- Any tree with somewhere to stand beside it. An old one is worth a log
    -- more, which is the felling's business rather than the choosing's.
    return here = tile_id('Tree') and exists (select 1 from beside_tile(p_world, p_x, p_y));
  elsif p_kind = 'mine' then
    rock := bedrock_at(p_world, p_x, p_y);
    return here = tile_id('Rock') and rock.ore and rock.level <= task_skill(c)
       and rock_height(p_world, p_x, p_y) > 1;
  elsif p_kind = 'quarry' then
    rock := bedrock_at(p_world, p_x, p_y);
    return here = tile_id('Rock') and not rock.ore and rock_height(p_world, p_x, p_y) > 1;
  elsif p_kind in ('sand', 'clay') then
    return here = tile_id(case p_kind when 'sand' then 'Sand' else 'Clay' end)
       and land_dirt(p_world, p_x, p_y) > 0 and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'peat' then
    return here in (tile_id('Peat'), tile_id('Tar')) and not is_foraged(p_world, p_x, p_y, 'dig')
       and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'reed' then
    return here = tile_id('Reed') and not is_foraged(p_world, p_x, p_y, 'reed');
  elsif p_kind = 'fish' then
    return fishable(p_world, p_x, p_y);
  elsif p_kind = 'farm' then
    -- Only ground that has been tilled and sown; a worker never rakes a field
    -- of its own, and it does not sow one either — that wants seeds in its
    -- cheeks, which is a piece still to come.
    perform crop_settle(p_world, p_x, p_y);
    return exists (select 1 from crop cr where cr.world_id = p_world and cr.x = p_x and cr.y = p_y
      and (cr.stage >= crop_ripe() or not cr.tended_now));
  elsif p_kind = 'forage' then
    return coalesce(t.forage, false) and not is_foraged(p_world, p_x, p_y, 'forage')
       and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'botanize' then
    return coalesce(t.botanize, false) and not is_foraged(p_world, p_x, p_y, 'botanize')
       and creature_tile_ok(p_world, p_x, p_y);
  end if;
  return false;
end $$;

/**
 * The nearest tile to the token worth working, searched ring by ring outwards.
 *
 * Written as a scan of the whole square first, which is correct and costs the
 * same whether the answer is under the worker's nose or nowhere: two workers
 * half an hour behind took four seconds to catch up, nearly all of it looking
 * at ground they had no need to look at. Outwards from the token, stopping at
 * the first ring with anything in it, is both what the browser does and what
 * the cost wants — and the ring is shuffled so two workers do not queue up on
 * the same tile.
 */
create or replace function find_work_tile(p_world uuid, p_cx int, p_cy int, p_range int,
    p_kind text, c creature)
  returns table (x int, y int) language plpgsql stable as $$
declare ring int; spot record;
begin
  for ring in 0..p_range loop
    for spot in
      select p_cx + dx as gx, p_cy + dy as gy
      from generate_series(-ring, ring) dx, generate_series(-ring, ring) dy
      where greatest(abs(dx), abs(dy)) = ring
      order by random()
    loop
      if worker_gatherable(p_world, spot.gx, spot.gy, p_kind, c) then
        x := spot.gx; y := spot.gy;
        return next;
        return;
      end if;
    end loop;
  end loop;
  return;
end $$;

select private.lock_doors();

/* ------------------------------------------------------------------ *
 * What a worker learns, and what it brings back.
 * ------------------------------------------------------------------ */

/** A beast learns on the same curve a player does, at half the pace. */
create or replace function worker_learn(p_world uuid, p_id int, p_skill text, p_base double precision)
  returns double precision language plpgsql as $$
declare was double precision; now_v double precision;
begin
  was := coalesce((select (skills->>p_skill)::double precision from creature
                   where world_id = p_world and id = p_id), 1);
  now_v := least(100, was + skill_gain_of(was, p_base, 0.6 + 0.8 * random()));
  update creature set skills = jsonb_set(skills, array[p_skill], to_jsonb(now_v)), xp = xp + (now_v - was)
    where world_id = p_world and id = p_id;
  return now_v - was;
end $$;

/**
 * Do the job, once, and hand back what it is carrying home — or null, because
 * a trip out is not always a trip back with something.
 *
 * Every rule underneath this is the one a player gets. A worker rolls like a
 * player of its own skill, wears the same forage cooldown into the ground,
 * fells the same tree and leaves the rest of it at the stump.
 */
create or replace function worker_do(p_world uuid, p_id int) returns jsonb
  language plpgsql as $$
declare c creature; d species_def; kind text; skill_id text; skill double precision;
        wx int; wy int; here int; data int; tree tree_def; rock rock_def; logs int;
        made_ql double precision; got text; careful double precision; chance double precision;
        cr crop; yld int[]; depth double precision;
begin
  select * into c from creature where world_id = p_world and id = p_id;
  if not found or c.work_x is null then return null; end if;
  select * into d from species_def where id = c.species;
  kind := d.gathers;
  select g.skill into skill_id from gather_def g where g.id = kind;
  skill := task_skill(c);
  wx := c.work_x; wy := c.work_y;
  here := land_tile(p_world, wx, wy);
  careful := trait_mul(c.traits, 'yield');
  perform worker_learn(p_world, p_id, skill_id, 0.225);
  made_ql := least(100, greatest(1, skill * (0.6 + random() * 0.8) + 1) * careful);

  if kind = 'woodcut' then
    if here <> tile_id('Tree') then return null; end if;
    data := land_data(p_world, wx, wy);
    select * into tree from tree_def where id = tree_species(data);
    logs := tree.logs + case when tree_age(data) = 2 then 1 else 0 end;
    perform land_set_tile(p_world, wx, wy, tile_id('Grass'));
    perform land_set_data(p_world, wx, wy, 0);
    perform land_announce(p_world, wx, wy);
    -- It can only carry one at a time; the rest of the tree waits at the stump.
    if logs > 1 then
      perform drop_on_ground(p_world, wx, wy, 'log', made_ql, tree.name, logs - 1);
    end if;
    return jsonb_build_object('def', 'log', 'count', 1, 'ql', made_ql, 'extra', tree.name);

  elsif kind in ('mine', 'quarry') then
    rock := bedrock_at(p_world, wx, wy);
    got := case when kind = 'mine' and rock.ore then rock.yields else 'rock_shards' end;
    made_ql := least(ore_max_ql((select seed from world where id = p_world), wx, wy), made_ql);
    return jsonb_build_object('def', got, 'count', 1, 'ql', made_ql);

  elsif kind in ('sand', 'clay') then
    if land_dirt(p_world, wx, wy) <= 0 then return null; end if;
    perform land_set_dirt(p_world, wx, wy, land_dirt(p_world, wx, wy) - 1);
    return jsonb_build_object('def', kind, 'count', 1, 'ql', made_ql);

  elsif kind = 'peat' then
    perform mark_foraged(p_world, wx, wy, 'dig');
    return jsonb_build_object('def', case when here = tile_id('Tar') then 'tar' else 'peat' end,
      'count', 1, 'ql', made_ql);

  elsif kind = 'reed' then
    perform mark_foraged(p_world, wx, wy, 'reed');
    return jsonb_build_object('def', 'reed', 'count', 1, 'ql', made_ql);

  elsif kind = 'fish' then
    depth := water_depth(p_world, wx, wy);
    got := catch_fish(depth, skill, 0, null);
    if got is null then return null; end if;
    return jsonb_build_object('def', got, 'count', 1, 'ql', made_ql);

  elsif kind = 'farm' then
    perform crop_settle(p_world, wx, wy);
    select * into cr from crop where world_id = p_world and x = wx and y = wy;
    if not found then return null; end if;
    if cr.stage < crop_ripe() then
      -- Not ripe: weed and water it, which is what makes the harvest worth having.
      if cr.tended_now then return null; end if;
      update crop set tended = tended + 1, tended_now = true,
          ql = least(100, ql + greatest(1, skill * 0.2))
        where world_id = p_world and x = wx and y = wy;
      return null;
    end if;
    yld := crop_yield(cr.tended);
    select produce into got from crop_def where id = cr.id;
    delete from crop where world_id = p_world and x = wx and y = wy;
    perform land_set_tile(p_world, wx, wy, tile_id('Field'));
    perform land_announce(p_world, wx, wy);
    -- The seed goes back in the ground's place; the produce goes home.
    perform drop_on_ground(p_world, wx, wy, (select seed from crop_def where id = cr.id),
      cr.ql, null, yld[2]);
    return jsonb_build_object('def', got, 'count', yld[1], 'ql', cr.ql);

  else
    -- Foraging and botanizing: the same table a player rolls on, and the same
    -- bed left picked clean behind it.
    perform mark_foraged(p_world, wx, wy, kind);
    chance := least(0.98, greatest(0.3, 0.6 + (skill / 100) * 0.38 - 5 / 150.0) * careful);
    if random() < 0.2 or random() >= chance then return null; end if;
    got := roll_table(kind, random());
    if got is null then return null; end if;
    return jsonb_build_object('def', got, 'count', 1, 'ql', made_ql);
  end if;
end $$;

/**
 * Walk a worker through as many whole round trips as have come due.
 *
 * Four parts, each of which begins and ends at a moment: out to the tile,
 * work it, home to the crate, put the load down. Thirty round trips — a
 * hundred and twenty of those parts — is as far back as anybody walks; past
 * that the clock catches up, exactly as it does for a wild one's legs, because
 * an island left alone for a week should not cost a week of arithmetic the
 * first time somebody looks at it.
 */
create or replace function worker_settle(p_world uuid, p_id int) returns int
  language plpgsql as $$
declare c creature; d species_def; dd deed; cr crate; kind text; guard int := 0; done int := 0;
        spot record; stand record; pace double precision; dist double precision; secs double precision;
        load jsonb; cx double precision; cy double precision; ax double precision; ay double precision;
begin
  select * into c from creature where world_id = p_world and id = p_id for update;
  if not found or c.mode <> 'deed' then return 0; end if;
  select * into dd from deed where world_id = p_world;
  if not found then
    -- No settlement to work for any more.
    update creature set mode = 'wild', phase = 'idle', job = null where world_id = p_world and id = p_id;
    return 0;
  end if;
  select * into d from species_def where id = c.species;
  kind := d.gathers;
  cr := deed_crate(p_world);
  pace := d.speed * (age_row(c.born)).speed * trait_mul(c.traits, 'speed')
          * (1 + greatest(1, task_skill(c)) / 500);

  while c.until <= now() and guard < 120 loop
    guard := guard + 1;
    cx := c.to_x; cy := c.to_y;

    if c.phase = 'out' then
      -- Arrived at the tile. Now the work, which takes as long as it takes.
      c.phase := 'work';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + make_interval(secs => work_duration(task_skill(c)) / trait_mul(c.traits, 'work'));

    elsif c.phase = 'work' then
      -- Write back where it stands before the job reads the row.
      update creature set from_x = cx, from_y = cy, to_x = cx, to_y = cy,
          leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
          work_x = c.work_x, work_y = c.work_y, settled_at = now()
        where world_id = p_world and id = p_id;
      load := worker_do(p_world, p_id);
      select * into c from creature where world_id = p_world and id = p_id;
      done := done + 1;
      c.carrying := load;
      c.work_x := null; c.work_y := null;
      if load is null or cr.id is null then
        -- Nothing to carry, or nowhere to carry it: back to pottering.
        c.phase := 'idle';
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + interval '1 second';
      else
        ax := crate_centre_x(cr); ay := crate_centre_y(cr);
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        secs := greatest(0.2, dist / greatest(0.1, pace));
        c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
        c.leg_at := c.until; c.leg_ends := c.leg_at + make_interval(secs => secs);
        c.until := c.leg_ends;
        c.phase := 'home';
      end if;

    elsif c.phase = 'home' then
      -- At the crate. In it goes, if it will go in.
      if c.carrying is not null and crate_add(p_world, cr.id, c.carrying->>'def',
          (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision, c.carrying->>'extra') then
        c.carrying := null;
      end if;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + interval '1 second';

    else
      -- Idle: look for something to do, and potter if there is nothing.
      select * into spot from find_work_tile(p_world, dd.x, dd.y, work_range(c), kind, c);
      if spot.x is null then
        /*
         * Nothing to do. Replaying half an hour of finding nothing costs a
         * search every four seconds and produces exactly nothing, so the
         * catch-up stops here: it has been pottering, and it is pottering now.
         */
        c.from_x := cx; c.from_y := cy;
        c.to_x := dd.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
        c.to_y := dd.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
        if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
          c.to_x := cx; c.to_y := cy;
        end if;
        dist := sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2);
        c.leg_at := now();
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends + interval '4 seconds';
        exit;
      else
        -- A tree cannot be stood on and neither can the water: both are
        -- worked from beside.
        if kind in ('woodcut', 'fish') then
          select * into stand from beside_tile(p_world, spot.x, spot.y);
          if stand.x is null then
            c.until := c.until + interval '4 seconds';
            continue;
          end if;
          ax := stand.x + 0.5; ay := stand.y + 0.5;
        else
          ax := spot.x + 0.5; ay := spot.y + 0.5;
        end if;
        c.work_x := spot.x; c.work_y := spot.y;
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
        c.leg_at := c.until;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends;
        c.phase := 'out';
      end if;
    end if;
  end loop;

  -- Thirty round trips is as far back as anybody walks.
  if c.until <= now() then
    c.from_x := c.to_x; c.from_y := c.to_y;
    c.leg_at := now(); c.leg_ends := now(); c.until := now() + interval '1 second';
  end if;

  update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
      leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
      work_x = c.work_x, work_y = c.work_y, carrying = c.carrying, settled_at = now()
    where world_id = p_world and id = p_id;
  return done;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914212100_worker_acts.sql
-- ======================================================================

-- Setting one to work, and the settle that does the work.

/** The trades this island knows how to have done for it. */
create or replace function worker_job_ported(p_kind text) returns boolean
  language sql immutable as $$
  select p_kind in ('forage', 'botanize', 'woodcut', 'mine', 'quarry',
                    'sand', 'clay', 'peat', 'reed', 'fish', 'farm')
$$;

create or replace function creature_action(p_action text) returns boolean language sql immutable as $$
  select p_action in ('examine_creature', 'tame', 'feed', 'groom', 'shear', 'milk_creature',
                      'set_stance', 'rename_creature', 'take_creature', 'store_creature',
                      'release_creature', 'assign_deed')
$$;

/**
 * Settling a creature now settles a worker's day as well.
 *
 * The body first — hunger, wounds closing, fleece — and written down, because
 * the work reads the row back. Then the trips, for whichever of them is on the
 * deed rather than out in the country.
 */
create or replace function creature_settle(p_world uuid, p_id int) returns boolean
  language plpgsql as $$
declare c creature; d species_def; a age_def; elapsed double precision; top double precision;
        guard int := 0; n int; i int; nx double precision; ny double precision;
        dist double precision; secs double precision; pace double precision; ok boolean;
        home record;
begin
  select * into c from creature where world_id = p_world and id = p_id for update;
  if not found then return false; end if;
  select * into d from species_def where id = c.species;
  a := age_row(c.born);
  elapsed := extract(epoch from (now() - c.settled_at));
  if elapsed <= 0 then
    if c.mode = 'deed' then perform worker_settle(p_world, p_id); end if;
    return false;
  end if;

  top := max_health(c);
  c.hunger := greatest(0, c.hunger - elapsed * hunger_rate(c.mode) * trait_mul(c.traits, 'appetite'));
  if c.health > top then
    c.health := top;
  elsif c.health < top and (c.hurt_at is null or now() - c.hurt_at > interval '6 seconds') then
    c.health := least(top, c.health + elapsed * case when c.mode = 'wild' then 0.25 else 0.6 end);
  end if;
  if d.fleece is not null and a.growth > 0 and c.fleece < 1 then
    c.fleece := least(1, c.fleece + elapsed * d.fleece * a.growth * trait_mul(c.traits, 'grow'));
  end if;
  c.care := greatest(0, c.care - elapsed / (3 * 3600));

  if c.mode = 'wild' then
    pace := d.speed * a.speed * trait_mul(c.traits, 'speed') * 0.7;
    while c.until <= now() and guard < 40 loop
      guard := guard + 1;
      n := c.leg + 1;
      ok := false;
      for i in 0..7 loop
        nx := c.to_x + (hash_tile(p_id, n, 7001 + i) * 2 - 1) * 4;
        ny := c.to_y + (hash_tile(p_id, n, 9001 + i) * 2 - 1) * 4;
        if creature_tile_ok(p_world, floor(nx)::int, floor(ny)::int)
           and line_clear(p_world, c.to_x, c.to_y, nx, ny) then ok := true; exit; end if;
      end loop;
      c.leg := n;
      if not ok then
        c.from_x := c.to_x; c.from_y := c.to_y;
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + interval '2 seconds';
        continue;
      end if;
      if c.hunger < 0.5 and coalesce((select forage from tile_def
            where id = land_tile(p_world, floor(nx)::int, floor(ny)::int)), false) then
        c.hunger := least(1, c.hunger + 0.5);
      end if;
      dist := sqrt((nx - c.to_x) ^ 2 + (ny - c.to_y) ^ 2);
      secs := greatest(0.2, dist / greatest(0.1, pace));
      c.from_x := c.to_x; c.from_y := c.to_y;
      c.to_x := nx; c.to_y := ny;
      c.leg_at := c.until;
      c.leg_ends := c.leg_at + make_interval(secs => secs);
      c.until := c.leg_ends + make_interval(secs => 1 + hash_tile(p_id, n, 11001) * 5);
    end loop;
    if c.until <= now() then
      c.from_x := c.to_x; c.from_y := c.to_y;
      c.leg_at := now(); c.leg_ends := now();
      c.until := now() + make_interval(secs => 1 + hash_tile(p_id, c.leg, 11001) * 5);
    end if;
  elsif c.mode = 'active' and c.keeper is not null then
    select p.x, p.y into home from player p where p.world_id = p_world and p.uid = c.keeper;
    if found then
      c.from_x := home.x; c.from_y := home.y; c.to_x := home.x; c.to_y := home.y;
      c.leg_at := now(); c.leg_ends := now(); c.until := now();
    end if;
  elsif c.mode = 'stored' then
    select dd.x + 0.5 as x, dd.y + 1.5 as y into home from deed dd where dd.world_id = p_world;
    if found then
      c.from_x := home.x; c.from_y := home.y; c.to_x := home.x; c.to_y := home.y;
      c.leg_at := now(); c.leg_ends := now(); c.until := now();
    end if;
  end if;

  update creature set
      from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
      leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, leg = c.leg,
      health = c.health, hunger = c.hunger, fleece = c.fleece, care = c.care,
      settled_at = now()
    where world_id = p_world and id = p_id;
  if c.mode = 'deed' then perform worker_settle(p_world, p_id); end if;
  return true;
end $$;

/**
 * Founding a settlement stands its crate up again.
 *
 * It was left out when the deed was first ported because nothing needed it.
 * A worker needs it: a beast that has walked out for a log and has nowhere to
 * put it is a beast doing nothing at all.
 */
create or replace function perform_deed(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare p player; tx int; ty int; nm text; made int;
begin
  select * into p from player where world_id = p_world and uid = p_uid;
  tx := floor(p.x)::int; ty := floor(p.y)::int;
  nm := nullif(btrim(coalesce(p_target->>'name', '')), '');
  if nm is null then nm := 'Homestead'; end if;
  if not consume(p_world, p_uid, 'deed_stake', 1) then return; end if;
  values (p_world, left(nm, 32), tx, ty, deed_radius(1), 1, p_uid)
  on conflict do nothing;
  made := place_deed_crate(p_world);
  perform tell(p_world, p_uid, 'You found the settlement of ' || left(nm, 32)
    || '. The land ' || (deed_radius(1) * 2 + 1) || ' tiles across around the token is yours to build on.'
    || case when made is null then '' else ' A deed crate stands beside the token.' end, 'system');
end $$;

/**
 * A settlement's crate is the settlement's to read.
 *
 * The item policy let you see what you were carrying and what lay on the
 * ground, which was every place an item could be until today. A crate nobody
 * can read is a crate nobody can use, so anybody standing on the island can
 * see what is in its stores — and still not touch them except through a rule.
 */
drop policy if exists item_read on item;
create policy item_read on item for select to authenticated using (
  (holder = 'player' and holder_uid = (select auth.uid()))
  or holder = 'ground'
  or (holder = 'crate' and private.on_island(world_id))
);

select private.lock_doors();

-- ======================================================================
-- 20260914212200_assign.sql
-- ======================================================================

-- Assigning one to the deed.

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field',
      'fish', 'drag_net',
      'found_settlement',
      'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
      'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
      'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey',
      'examine_creature', 'tame', 'feed', 'groom', 'shear', 'milk_creature',
      'set_stance', 'rename_creature', 'take_creature', 'store_creature', 'release_creature',
      'assign_deed',
      'equip', 'unequip', 'attack_creature', 'shoot_creature', 'butcher',
      'bind_wound', 'clean_wound', 'treat_creature',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_furniture', 'pick_up_furniture')
      or exists (select 1 from recipe where id = p_action)
$$;

create or replace function creature_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql as $$
declare c creature; d species_def; food text; held int; working int; cap int;
begin
  -- Walked forward before it is looked at: where it was is not where it is.
  perform creature_settle(p_world, (p_target->>'id')::int);
  c := target_creature(p_world, p_target);
  if c.world_id is null then return 'It is gone.'; end if;
  select * into d from species_def where id = c.species;

  if p_action not in ('examine_creature', 'assign_deed')
     and not creature_in_reach(p_world, p_uid, c) then
    return case when c.mode = 'wild' then 'The ' || lower(d.name) || ' is not close enough.'
                else 'Stand next to ' || c.name || '.' end;
  end if;

  if p_action = 'tame' then
    if d.monster then
      return 'A ' || lower(d.name) || ' is not a wildermon. There is nothing to be done with it but kill it.';
    end if;
    if c.mode <> 'wild' then return c.name || ' is already yours.'; end if;
    if skill_of(p_world, p_uid, 'taming') < d.tame_level then
      return 'You need taming ' || to_char(d.tame_level, 'FM990.#') || ' to try.';
    end if;
    if bait_in_pack(p_world, p_uid, c.species) is null then
      return d.name || 's take ' || diet_text(c.species) || '. Bring some.';
    end if;
    if companion_of(p_world, p_uid) is not null and not exists (select 1 from deed where world_id = p_world) then
      return 'You already have a companion and no settlement to keep another.';
    end if;
    return null;

  elsif p_action = 'assign_deed' then
    if c.mode = 'wild' then return 'It is not yours to set to work.'; end if;
    if not exists (select 1 from deed where world_id = p_world) then
      return 'You have no settlement to assign it to.';
    end if;
    if d.gathers is null then return 'A ' || lower(d.name) || ' has no trade to be set to.'; end if;
    if not worker_job_ported(d.gathers) then
      return 'Nobody has taught this island what ' || (select plain from gather_def where id = d.gathers)
        || ' looks like yet.';
    end if;
    if c.mode <> 'deed' then
      working := workers_on_deed(p_world);
      cap := worker_cap(p_world);
      if working >= cap then
        return (select name from deed where world_id = p_world) || ' has work for ' || cap
          || ' wildermon at level ' || cap || '. Upgrade the settlement to take on more.';
      end if;
    end if;
    return null;

  elsif p_action = 'feed' then
    if c.mode not in ('active', 'deed') then return 'It is not yours to feed.'; end if;
    if bait_in_pack(p_world, p_uid, c.species) is null then
      return 'It eats ' || diet_text(c.species) || '.';
    end if;
    return null;

  elsif p_action = 'groom' then
    if d.monster then return 'Not that. Not ever.'; end if;
    if c.mode = 'wild' then return 'It is not yours to brush.'; end if;
    if pack_count(p_world, p_uid, 'brush') <= 0 then return 'You need a brush.'; end if;
    if c.care >= 0.995 then return c.name || ' has been brushed to a shine already.'; end if;
    return null;

  elsif p_action = 'shear' then
    if d.fleece is null then return 'There is nothing on it worth shearing.'; end if;
    if c.mode = 'wild' then return 'Tame it first; it will not stand still for you otherwise.'; end if;
    if pack_count(p_world, p_uid, 'carving_knife') <= 0 then return 'You need a knife to shear with.'; end if;
    if c.fleece < 0.35 then
      return c.name || ' has hardly any '
        || case when d.shear_yield = 'feather' then 'feathers' else 'fleece' end || ' back yet.';
    end if;
    return null;

  elsif p_action = 'milk_creature' then
    if not d.milk then return 'That is not something you milk.'; end if;
    if c.mode in ('wild', 'stored') then return 'It is not yours to milk.'; end if;
    if pack_count(p_world, p_uid, 'bucket') <= 0 then return 'You need an empty bucket.'; end if;
    if c.sex <> 'female' then return c.name || ' is male. Nothing is coming out of him.'; end if;
    if c.fleece < 0.4 then return c.name || ' has nothing to give yet.'; end if;
    return null;

  elsif p_action = 'set_stance' then
    if c.mode <> 'active' then return 'Only a companion takes orders like that.'; end if;
    if coalesce(p_target->>'stance', '') not in ('passive', 'defensive', 'aggressive') then
      return 'Passive, defensive or aggressive.';
    end if;
    return null;

  elsif p_action = 'rename_creature' then
    if c.mode = 'wild' then return 'It is not yours to name.'; end if;
    if nullif(btrim(coalesce(p_target->>'name', '')), '') is null then return 'Choose a name.'; end if;
    return null;

  elsif p_action = 'take_creature' then
    if c.mode not in ('deed', 'stored') then return 'It is already with you.'; end if;
    held := companion_of(p_world, p_uid);
    if held is not null and not exists (select 1 from deed where world_id = p_world) then
      return 'Nowhere to keep your current companion.';
    end if;
    return null;

  elsif p_action = 'store_creature' then
    if c.mode not in ('active', 'deed') then return 'It is already at the token.'; end if;
    if not exists (select 1 from deed where world_id = p_world) then
      return 'You have no settlement token to keep it at.';
    end if;
    return null;

  elsif p_action = 'release_creature' then
    if c.mode = 'wild' then return 'It is already wild.'; end if;
    return null;
  end if;
  return null;
end $$;

/**
 * The doing of the creature actions, with one more on the end: a beast set to
 * work walks out on its own from the moment it is told to.
 */
create or replace function perform_creature(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare c creature; d species_def; a age_def; food text; n int; made_ql double precision;
        gained double precision; chance double precision; warm double precision; nm text;
        held int; brush_id bigint; top double precision; before double precision; skill double precision;
        dd deed;
begin
  c := target_creature(p_world, p_target);
  if c.world_id is null then return; end if;
  select * into d from species_def where id = c.species;
  a := age_row(c.born);

  if p_action = 'examine_creature' then
    if c.mode = 'wild' and d.monster then
      perform tell(p_world, p_uid, 'A ' || lower(d.name) || ': ' || d.description
        || ' It has ' || ceil(c.health) || ' of ' || max_health(c) || ' in it and hits for '
        || to_char(attack_of(c), 'FM990') || '. It cannot be tamed. Kill it and butcher it, or keep well clear.', 'error');
    elsif c.mode = 'wild' then
      warm := coax_bonus(c);
      perform tell(p_world, p_uid, 'A wild ' || lower(d.name) || ': ' || d.description
        || ' It eats ' || diet_text(c.species) || '.'
        || case when warm > 0 then ' It has taken ' ||
             case when c.coaxed = 1 then 'an offering' else c.coaxed || ' offerings' end
             || ' from your hand and is ' || to_char(warm * 100, 'FM990') || '% readier for the next.'
           else '' end
        || ' You would have to tame it to learn more.', 'event');
    else
      perform tell(p_world, p_uid, c.name || ' (' || c.sex || ' ' || lower(d.name) || ', ' || a.name
        || '): ' || d.description || ' Level ' || creature_level(c.skills)
        || '. Health ' || ceil(c.health) || '/' || max_health(c) || '. It is ' || care_word(c.care)
        || ' and carries ' || trait_names(c.traits) || '. '
        || case when c.hunger < 0.3 then 'It looks hungry.' when c.hunger < 0.6 then 'It could eat.'
                else 'It looks well fed.' end
        || ' It eats ' || diet_text(c.species) || '.', 'event');
    end if;

  elsif p_action = 'tame' then
    food := bait_in_pack(p_world, p_uid, c.species);
    if food is null or not consume(p_world, p_uid, food, 1) then return; end if;
    chance := tame_chance(p_world, p_uid, c);
    update creature set hunger = least(1, hunger + 0.25) where world_id = p_world and id = c.id;
    if random() < chance then
      held := companion_of(p_world, p_uid);
      update creature set
          mode = case when held is null then 'active' else 'stored' end,
          stance = 'defensive', keeper = p_uid, coaxed = 0, coaxed_at = null
        where world_id = p_world and id = c.id;
      perform tell(p_world, p_uid, 'The ' || lower(d.name) || ' takes the '
        || material_name(food, 1) || ' from your hand and trusts you. '
        || case when held is null then c.name || ' now follows you.'
             else 'As you already travel with a companion, it is kept at the token of '
                  || coalesce((select name from deed where world_id = p_world), 'your settlement') || '.' end, 'system');
      perform skill_raise(p_world, p_uid, 'taming', 0.7);
      perform skill_raise(p_world, p_uid, 'soul_strength', 0.4);
    else
      -- It refused, but it stayed for the offering, and that is worth
      -- something to the next one.
      update creature set coaxed = coaxed + 1, coaxed_at = now()
        where world_id = p_world and id = c.id returning * into c;
      warm := coax_bonus(c);
      perform tell(p_world, p_uid, 'The ' || lower(d.name) || ' '
        || replace(d.tame_fail, '{food}', material_name(food, 1)) || '.'
        || case when warm > 0 then ' It is ' ||
             case when warm >= 0.12 then 'as used to you as it will get' else 'growing used to you' end
             || ': ' || to_char(warm * 100, 'FM990') || '% readier than the first time.'
           else '' end, 'event');
      perform skill_raise(p_world, p_uid, 'taming', 0.35);
      perform skill_raise(p_world, p_uid, 'soul_strength', 0.2);
    end if;

  elsif p_action = 'feed' then
    food := bait_in_pack(p_world, p_uid, c.species);
    if food is null or not consume(p_world, p_uid, food, 1) then return; end if;
    update creature set hunger = least(1, hunger + 0.5) where world_id = p_world and id = c.id;
    perform tell(p_world, p_uid, c.name || ' gobbles up the ' || material_name(food, 1) || '.', 'event');

  elsif p_action = 'groom' then
    select i.id into brush_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = 'brush'
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    skill := skill_of(p_world, p_uid, 'animal_husbandry');
    before := c.care;
    top := max_health(c);
    update creature set
        care = least(1, care + 0.18 + (skill / 100) * 0.34
                          + (least(100, tool_ql(p_world, p_uid, 'brush')) / 100) * 0.22),
        -- A brushing is also a looking-over: it finds the small hurts.
        health = least(top, health + top * 0.06)
      where world_id = p_world and id = c.id returning * into c;
    if brush_id is not null then perform wear_tool(brush_id, 3); end if;
    gained := skill_raise(p_world, p_uid, 'animal_husbandry', 0.4);
    perform tell(p_world, p_uid, case when before < 0.12 and c.care >= 0.12
        then 'You work the dust out of ' || c.name || '''s coat. It leans into the brush. ('
        else 'You brush ' || c.name || ' down. (' end || care_word(c.care) || ')', 'event');

  elsif p_action = 'shear' then
    -- A full fleece is three, a half-grown one is one, and quality follows the fleece.
    n := greatest(1, round(c.fleece * case when coalesce(d.shear_yield, 'wool') = 'wool' then 3 else 6 end)::int);
    made_ql := greatest(1, least(100, 15 + c.fleece * 45 + skill_of(p_world, p_uid, 'tailoring') * 0.4));
    perform give(p_world, p_uid, coalesce(d.shear_yield, 'wool'), n, made_ql);
    update creature set fleece = 0 where world_id = p_world and id = c.id;
    perform skill_raise(p_world, p_uid, 'tailoring', 0.4);
    perform skill_raise(p_world, p_uid, 'taming', 0.1);
    perform tell(p_world, p_uid, 'You '
      || case when coalesce(d.shear_yield, 'wool') = 'wool' then 'shear' else 'pluck' end
      || ' ' || c.name || ' and come away with ' || n || ' '
      || lower((select coalesce(name, 'wool') from item_def where id = coalesce(d.shear_yield, 'wool')))
      || '. (QL ' || to_char(made_ql, 'FM990.0') || ') It will grow back.', 'event');

  elsif p_action = 'milk_creature' then
    if not consume(p_world, p_uid, 'bucket', 1) then return; end if;
    -- What it has been fed on is what comes out of it.
    made_ql := greatest(1, least(100, 20 + c.fleece * 40 + c.hunger * 30));
    perform give(p_world, p_uid, 'milk_bucket', 1, made_ql);
    update creature set fleece = 0 where world_id = p_world and id = c.id;
    perform skill_raise(p_world, p_uid, 'farming', 0.3);
    perform tell(p_world, p_uid, 'You milk ' || c.name || ' into the bucket. (QL '
      || to_char(made_ql, 'FM990.0') || ')', 'event');

  elsif p_action = 'set_stance' then
    update creature set stance = p_target->>'stance' where world_id = p_world and id = c.id;
    perform tell(p_world, p_uid, c.name || ' will be ' || (p_target->>'stance') || '.', 'info');

  elsif p_action = 'rename_creature' then
    nm := left(btrim(p_target->>'name'), 24);
    update creature set name = nm where world_id = p_world and id = c.id;
    perform tell(p_world, p_uid, 'It answers to ' || nm || ' now.', 'info');

  elsif p_action = 'take_creature' then
    held := companion_of(p_world, p_uid);
    if held is not null then
      update creature set mode = 'stored' where world_id = p_world and id = held;
      perform tell(p_world, p_uid,
        (select name from creature where world_id = p_world and id = held)
        || ' stays at the token for now.', 'info');
    end if;
    update creature set mode = 'active', keeper = p_uid, settled_at = now()
      where world_id = p_world and id = c.id;
    perform creature_settle(p_world, c.id);
    perform tell(p_world, p_uid, c.name || ' now follows you.', 'system');

  elsif p_action = 'store_creature' then
    update creature set mode = 'stored', settled_at = now() where world_id = p_world and id = c.id;
    perform creature_settle(p_world, c.id);
    perform tell(p_world, p_uid, c.name || ' is kept at the token of '
      || (select name from deed where world_id = p_world) || '.', 'system');

  elsif p_action = 'assign_deed' then
    select * into dd from deed where world_id = p_world;
    update creature set mode = 'deed', keeper = p_uid, phase = 'idle', job = d.gathers,
        work_x = null, work_y = null, carrying = null,
        from_x = case when c.mode = 'stored' then dd.x + 0.5 else creature_x(c) end,
        from_y = case when c.mode = 'stored' then dd.y + 1.5 else creature_y(c) end,
        to_x = case when c.mode = 'stored' then dd.x + 0.5 else creature_x(c) end,
        to_y = case when c.mode = 'stored' then dd.y + 1.5 else creature_y(c) end,
        leg_at = now(), leg_ends = now(), until = now(), settled_at = now()
      where world_id = p_world and id = c.id;
    perform tell(p_world, p_uid, c.name || ' will '
      || coalesce((select plain from gather_def where id = d.gathers), 'stay around the settlement')
      || ' within ' || work_range(c) || ' tiles of the token and bring what it finds to the crate.', 'system');

  elsif p_action = 'release_creature' then
    -- Blood takes generations to build and a moment to walk away.
    update creature set mode = 'wild', stance = 'passive', keeper = null,
        name = d.name, coaxed = 0, coaxed_at = null, until = now()
      where world_id = p_world and id = c.id;
    perform tell(p_world, p_uid, 'The ' || lower(d.name) || ' ' || d.leaves || '.', 'system');
  end if;
end $$;

