-- ======================================================================
-- 20260914232400_liquids.sql
-- ======================================================================

-- Barrels, buckets, and a well that fills itself.
--
-- ## A well is the fifth thing that will not sit still
--
-- A fire burns down, a crop comes on, a forage bed recovers, a creature walks.
-- A well draws its own water, and it draws it whether or not anybody is
-- standing over it — so it settles like all the others: how much is in it is
-- what was in it when somebody last touched it, plus the seconds since,
-- stopped at the depth it was sunk to. Nothing has to tick.
--
-- A barrel is the other half and the easy half. It holds what is poured into
-- it and loses nothing, so its litres are simply a number on the row.
--
-- ## Two litres tables, because a barrel and a well mean different things by
-- "how much it holds"
--
-- A coopered thing varies with the wood it was built out of: a large oak
-- barrel takes more than a large pine one. A well is a lined shaft in the
-- ground, and the ground does not care what the kerb is made of.

alter table placed add column if not exists litres real not null default 0;
alter table placed add column if not exists liquid text;

create or replace function liquid_action(p_action text) returns boolean language sql immutable as $$
  select p_action in ('fill_bucket', 'fill_skin', 'empty_bucket',
                      'empty_vessel', 'drink_from_vessel', 'pour_into_barrel')
$$;

/** A bucket holds five litres, whichever way it is going. */
create or replace function bucket_litres() returns double precision
  language sql immutable as $$ select 5 $$;

/** What a thing standing about is called, once somebody has called it anything. */
create or replace function placed_name(p placed) returns text language sql stable as $$
  select coalesce(p.name, (select f.name from furniture_def f where f.id = p.sub), p.kind)
$$;

/**
 * Litres a vessel holds: a barrel by its build, a well by how deep it was sunk.
 *
 * The browser scales a coopered thing by the wood it was built out of — a
 * large oak barrel takes more than a large pine one. Nothing standing on this
 * island records what it was built of yet, so there is nothing for that
 * multiplier to read, and a barrel holds what its build says. When a placed
 * thing remembers its material this is the one line that changes.
 */
create or replace function liquid_capacity(p placed) returns double precision
  language sql stable as $$
  select case when d.liquid is not null then d.liquid else coalesce(d.well, 0) end
  from furniture_def d where d.id = p.sub
$$;

create or replace function holds_liquid(p placed) returns boolean
  language sql stable as $$ select liquid_capacity(p) > 0 $$;

/** A well draws its own water; a barrel only holds what is poured into it. */
create or replace function is_well(p placed) returns boolean language sql stable as $$
  select coalesce((select well from furniture_def where id = p.sub), 0) > 0
$$;

/**
 * What is in it.
 *
 * A barrel says so on its row, because somebody poured it in. A well never
 * needed telling: it is water, it was always going to be water, and the column
 * only catches up the next time anybody draws from it. Asking through here
 * rather than reading the column is the difference between a bucket that fills
 * and a bucket that comes up holding null.
 */
create or replace function placed_liquid(p placed) returns text language sql stable as $$
  select case when is_well(p) then 'water' else p.liquid end
$$;

/** What a well finds in a second: a better-sunk shaft finds it faster. */
create or replace function well_rate(p_ql double precision) returns double precision
  language sql immutable as $$ select 0.012 + (p_ql / 100) * 0.055 $$;

/**
 * How much is in it now.
 *
 * A barrel: whatever was poured in. A well: that, plus what it has found since
 * somebody last looked, up to the depth it was sunk to.
 */
create or replace function placed_litres(p placed) returns double precision
  language sql stable as $$
  select case when not is_well(p) then p.litres
              else least(liquid_capacity(p),
                         p.litres + well_rate(p.ql) * extract(epoch from (now() - p.since))) end
$$;

/** Write down what a well has found, so that what happens next starts from now. */
create or replace function well_settle(p_id bigint) returns void language plpgsql as $$
declare p placed;
begin
  select * into p from placed where id = p_id for update;
  if not found or not is_well(p) then return; end if;
  update placed set litres = placed_litres(p), liquid = 'water', since = now() where id = p_id;
end $$;

/* ------------------------------------------------------------------ *
 * What is within reach of a pair of hands.
 * ------------------------------------------------------------------ */

/** Open water on the tile you stand on or any of its neighbours. */
create or replace function near_water(p_world uuid, p_uid uuid) returns boolean
  language sql stable as $$
  select exists (
    select 1 from player pl,
      lateral generate_series(floor(pl.x)::int - 1, floor(pl.x)::int + 1) as g(wx),
      lateral generate_series(floor(pl.y)::int - 1, floor(pl.y)::int + 1) as h(wy)
    where pl.world_id = p_world and pl.uid = p_uid
      and in_bounds(p_world, g.wx, h.wy) and has_water(p_world, g.wx, h.wy))
$$;

/** Whether a piece of furniture is close enough to dip into or pour from. */
create or replace function near_piece(p_world uuid, p_uid uuid, p placed,
                                      p_range double precision default 2.4)
  returns boolean language sql stable as $$
  select exists (select 1 from player pl where pl.world_id = p_world and pl.uid = p_uid
    and sqrt((p.cx - pl.x) ^ 2 + (p.cy - pl.y) ^ 2) <= p_range)
$$;

/**
 * Something beside you with a liquid in it, fullest first.
 *
 * A barrel still working is not drawn off — whatever is in it is not ready —
 * but nothing on this island ferments yet, so that question has only one
 * answer here and is left out until brewing arrives.
 */
create or replace function vessels_near(p_world uuid, p_uid uuid, p_kind text default null)
  returns setof placed language sql stable as $$
  select p.* from placed p
  where p.world_id = p_world and p.kind = 'furniture' and holds_liquid(p)
    and placed_litres(p) >= 1
    and (p_kind is null or placed_liquid(p) = p_kind)
    and near_piece(p_world, p_uid, p, 2.6)
  order by placed_litres(p) desc, p.id
$$;

/** Whether there is water at hand at all: a shore, a well, or a barrel of it. */
create or replace function water_near(p_world uuid, p_uid uuid) returns boolean
  language sql stable as $$
  select near_water(p_world, p_uid)
      or exists (select 1 from vessels_near(p_world, p_uid, 'water'))
$$;

/** The emptiest barrel beside you that would take this liquid. */
create or replace function barrel_for(p_world uuid, p_uid uuid, p_kind text) returns placed
  language sql stable as $$
  select p.* from placed p
  where p.world_id = p_world and p.kind = 'furniture'
    and holds_liquid(p) and not is_well(p)
    and (placed_litres(p) <= 0 or placed_liquid(p) = p_kind)
    and placed_litres(p) < liquid_capacity(p)
    and near_piece(p_world, p_uid, p, 2.6)
  order by placed_litres(p), p.id
  limit 1
$$;

/** Take a measure out of something, and leave it empty of anything if it runs dry. */
create or replace function draw_from(p_id bigint, p_litres double precision) returns boolean
  language plpgsql as $$
declare p placed; v_left double precision;
begin
  perform well_settle(p_id);
  select * into p from placed where id = p_id for update;
  if not found or placed_litres(p) < p_litres then return false; end if;
  v_left := placed_litres(p) - p_litres;
  update placed set litres = v_left, since = now(),
      liquid = case when v_left <= 0 and not is_well(p) then null else p.liquid end
    where id = p_id;
  return true;
end $$;

/* ------------------------------------------------------------------ *
 * The doors.
 * ------------------------------------------------------------------ */

create or replace function liquid_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare it item; p placed; v_kind text;
begin
  if p_action in ('fill_bucket', 'fill_skin', 'empty_bucket', 'pour_into_barrel') then
    select * into it from item where world_id = p_world and id = (p_target->>'uid')::bigint
      and holder = 'player' and holder_uid = p_uid;
    if not found then return 'It is gone.'; end if;
  else
    select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint
      and kind = 'furniture';
    if not found then return 'It is gone.'; end if;
    if not near_piece(p_world, p_uid, p) then return 'Stand next to it.'; end if;
  end if;

  if p_action = 'fill_bucket' then
    if it.def <> 'bucket' then return 'That is not an empty bucket.'; end if;
    if not exists (select 1 from vessels_near(p_world, p_uid) v where placed_litres(v) >= bucket_litres())
       and not near_water(p_world, p_uid) then
      return 'You need water: a shore, a well, or a barrel with something in it.';
    end if;

  elsif p_action = 'fill_skin' then
    if (select charges from item_def where id = it.def) is null then
      return 'That does not hold water.';
    end if;
    if coalesce(it.charges, 0) >= (select charges from item_def where id = it.def) then
      return 'It is already full.';
    end if;
    if not water_near(p_world, p_uid) then
      return 'You need water: a shore, a well, or a barrel of it.';
    end if;

  elsif p_action = 'empty_bucket' then
    if not exists (select 1 from vessel_def where item = it.def) then
      return 'That is not a bucket of anything.';
    end if;

  elsif p_action = 'pour_into_barrel' then
    select liquid into v_kind from vessel_def where item = it.def;
    if v_kind is null then return 'That is not a bucket of anything.'; end if;
    if (barrel_for(p_world, p_uid, v_kind)).id is null then
      return 'There is no barrel beside you with room for '
        || (select name from liquid_def where id = v_kind) || '.';
    end if;

  elsif p_action = 'empty_vessel' then
    if not holds_liquid(p) or is_well(p) then return 'That is not something you tip out.'; end if;
    if placed_litres(p) <= 0 then return 'It is already empty.'; end if;

  elsif p_action = 'drink_from_vessel' then
    if not holds_liquid(p) then return 'There is nothing in that to drink.'; end if;
    if not coalesce((select drinkable from liquid_def where id = placed_liquid(p)), false) then
      return 'You would not want to drink that.';
    end if;
    if placed_litres(p) < 1 then return 'It is dry.'; end if;
    if coalesce((select (stats->>'thirst')::double precision from player
                 where world_id = p_world and uid = p_uid), 1) >= 0.999
       and not coalesce((select brew from liquid_def where id = placed_liquid(p)), false) then
      return 'You are not thirsty.';
    end if;
  end if;
  return null;
end $$;

create or replace function perform_liquid(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare it item; p placed; v_kind text; v_from placed; v_full text; v_room double precision;
        v_poured double precision; v_favour text; v_full_msg text; v_thirst double precision;
begin
  if p_action in ('fill_bucket', 'fill_skin', 'empty_bucket', 'pour_into_barrel') then
    select * into it from item where world_id = p_world and id = (p_target->>'uid')::bigint
      and holder = 'player' and holder_uid = p_uid;
    if not found then return; end if;
  else
    select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint;
    if not found then return; end if;
  end if;

  if p_action = 'fill_bucket' then
    -- A barrel beside you first, and the shore only if there is none.
    select * into v_from from vessels_near(p_world, p_uid) v
      where placed_litres(v) >= bucket_litres() limit 1;
    if found then
      v_kind := placed_liquid(v_from);
      if not draw_from(v_from.id, bucket_litres()) then return; end if;
    elsif near_water(p_world, p_uid) then
      v_kind := 'water';
    else
      return;
    end if;
    select item into v_full from vessel_def where liquid = v_kind limit 1;
    if not consume(p_world, p_uid, 'bucket', 1, it.id) then return; end if;
    perform give(p_world, p_uid, v_full, 1, it.ql);
    perform tell(p_world, p_uid, case when v_from.id is not null
      then 'You draw a bucket of ' || (select name from liquid_def where id = v_kind)
           || ' out of the ' || lower(placed_name(v_from)) || '.'
      else 'You dip the bucket full of water.' end, 'event');

  elsif p_action = 'fill_skin' then
    update item set charges = (select charges from item_def where id = it.def) where id = it.id;
    perform tell(p_world, p_uid, 'You fill the '
      || lower((select name from item_def where id = it.def)) || ' with water.', 'event');

  elsif p_action = 'empty_bucket' then
    select empty into v_full from vessel_def where item = it.def;
    if v_full is null then return; end if;
    if not consume(p_world, p_uid, it.def, 1, it.id) then return; end if;
    perform give(p_world, p_uid, v_full, 1, it.ql);
    perform tell(p_world, p_uid, 'You tip the '
      || lower((select name from item_def where id = it.def)) || ' out.', 'event');

  elsif p_action = 'pour_into_barrel' then
    select liquid into v_kind from vessel_def where item = it.def;
    v_from := barrel_for(p_world, p_uid, v_kind);
    if v_from.id is null then return; end if;
    v_room := liquid_capacity(v_from) - placed_litres(v_from);
    v_poured := least(bucket_litres(), v_room);
    if v_poured <= 0 then return; end if;
    if not consume(p_world, p_uid, it.def, 1, it.id) then return; end if;
    update placed set litres = placed_litres(v_from) + v_poured, liquid = v_kind, since = now()
      where id = v_from.id;
    perform give(p_world, p_uid, (select empty from vessel_def where item = it.def), 1, it.ql);
    perform tell(p_world, p_uid, 'You pour ' || to_char(v_poured, 'FM990') || ' litres of '
      || (select name from liquid_def where id = v_kind) || ' into the '
      || lower(placed_name(v_from)) || '. '
      || to_char(placed_litres(v_from) + v_poured, 'FM990') || ' of '
      || to_char(liquid_capacity(v_from), 'FM990') || '.', 'event');

  elsif p_action = 'empty_vessel' then
    v_kind := coalesce((select name from liquid_def where id = placed_liquid(p)), 'it');
    update placed set litres = 0, liquid = null, since = now() where id = p.id;
    perform tell(p_world, p_uid, 'You tip the ' || v_kind || ' out of the '
      || lower(placed_name(p)) || '.', 'event');

  elsif p_action = 'drink_from_vessel' then
    if not draw_from(p.id, 1) then return; end if;
    v_thirst := coalesce((select (stats->>'thirst')::double precision from player
                          where world_id = p_world and uid = p_uid), 1);
    update player set stats = jsonb_set(stats, '{thirst}', to_jsonb(least(1, v_thirst + 0.5)))
      where world_id = p_world and uid = p_uid;
    -- A brew straight out of the barrel favours a trade like any other.
    if coalesce((select brew from liquid_def where id = placed_liquid(p)), false) then
      select item into v_full from vessel_def where liquid = placed_liquid(p) limit 1;
      v_favour := grant_boon(p_world, p_uid, v_full, p.ql);
      v_full_msg := nourish(p_world, p_uid, v_full, p.ql);
    end if;
    perform tell(p_world, p_uid, 'You drink your fill from the ' || lower(placed_name(p)) || '.'
      || coalesce(' ' || v_favour, '') || coalesce(' ' || v_full_msg, ''), 'event');
  end if;
end $$;

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
      'pave_gravel', 'pave_cobble', 'drop_dirt_here',
      'cut_down', 'forage', 'botanize', 'collect',
      'till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field',
      'fish', 'drag_net',
      'found_settlement',
      'plan_building', 'add_to_building', 'remove_from_plan', 'rename_building',
      'plan_wall', 'plan_fence', 'build_wall', 'remove_wall',
      'add_floor', 'plan_floor', 'build_floor', 'remove_floor', 'remove_storey',
      'examine_creature', 'tame', 'feed', 'groom', 'shear', 'milk_creature',
      'set_stance', 'rename_creature', 'take_creature', 'store_creature', 'release_creature',
      'assign_deed',
      'place_crate', 'pick_up_crate', 'crate_take_all', 'store_in_crate',
      'equip', 'unequip', 'attack_creature', 'shoot_creature', 'butcher',
      'bind_wound', 'clean_wound', 'treat_creature',
      'smelt_ore', 'cast_anvil', 'smelter_take_all', 'load_kiln', 'kiln_take_all',
      'improve_item', 'repair_item', 'eat', 'drink', 'drink_skin',
      'build_campfire', 'light_campfire', 'put_out_campfire', 'fuel_campfire',
      'take_ashes_fire', 'take_apart_campfire',
      'place_smelter', 'pick_up_smelter', 'light_smelter', 'fuel_smelter',
      'damp_smelter', 'take_ashes_smelter',
      'place_kiln', 'pick_up_kiln', 'light_kiln', 'fuel_kiln',
      'damp_kiln', 'take_ashes_kiln',
      'place_furniture', 'pick_up_furniture',
      'pick_up', 'pick_up_all', 'drop', 'examine', 'examine_item',
      'lock_item', 'unlock_item', 'name_thing',
      'flatten', 'drop_dirt', 'pave_slabs', 'remove_paving',
      'cut_grass', 'cut_reeds', 'pick_fruit', 'pick_sprout',
      'plant', 'dig_worms', 'prospect',
      'fill_bucket', 'fill_skin', 'empty_bucket',
      'empty_vessel', 'drink_from_vessel', 'pour_into_barrel')
      or exists (select 1 from recipe where id = p_action)
$$;


select private.lock_doors();

-- ======================================================================
-- 20260914232500_water_work.sql
-- ======================================================================

-- Carrying water, which is the twenty-first trade.
--
-- ## An errand that carries nothing out of the stores
--
-- Every other fetching errand takes a piece out of a crate. A water carrier
-- takes its load out of the island itself — a well on the deed, or the shore —
-- and the only thing it puts down is five litres in a barrel. So it is the
-- round trip with the crate swapped for the water, which the phase machine
-- runs without knowing the difference.

create or replace function worker_errand(p_kind text) returns boolean language sql immutable as $$
  select p_kind in ('hod', 'mend', 'stoke', 'plant', 'prospect', 'water')
$$;

/** Twenty-one of twenty-two. Only `seek` is left, and it wants archaeology. */
create or replace function worker_job_ported(p_kind text) returns boolean
  language sql immutable as $$
  select p_kind in ('forage', 'botanize', 'woodcut', 'mine', 'quarry',
                    'sand', 'clay', 'peat', 'reed', 'fish', 'farm', 'fetch',
                    'hod', 'mend', 'stoke', 'plant', 'compost', 'guard', 'hunt',
                    'prospect', 'water')
$$;

/** A barrel on the deed with room in it for more water. */
create or replace function thirsty_vessel(p_world uuid) returns placed
  language sql stable as $$
  select p.* from placed p, deed dd
  where p.world_id = p_world and dd.world_id = p_world and p.kind = 'furniture'
    and holds_liquid(p) and not is_well(p)
    and placed_litres(p) < liquid_capacity(p)
    and (p.liquid is null or p.liquid = 'water')
    and on_deed(p_world, p.x, p.y)
  order by placed_litres(p), p.id
  limit 1
$$;

/**
 * Somewhere worth dipping into: a well on the deed first, and the nearest
 * open water within range if there is no well.
 */
create or replace function water_source(p_world uuid, p_cx int, p_cy int, p_range int, c creature)
  returns table (x int, y int, gx double precision, gy double precision)
  language plpgsql stable as $$
declare v_well placed; v_size int;
begin
  select p.* into v_well from placed p
    where p.world_id = p_world and p.kind = 'furniture' and is_well(p)
      and placed_litres(p) >= 1 and on_deed(p_world, p.x, p.y)
    order by p.id limit 1;
  if found then
    x := v_well.x; y := v_well.y; gx := v_well.cx; gy := v_well.cy;
    return next;
    return;
  end if;
  v_size := (select size from world where id = p_world);
  select q.wx, q.wy, q.wx + 0.5, q.wy + 0.5 into x, y, gx, gy
  from generate_series(greatest(0, p_cx - p_range), least(v_size - 1, p_cx + p_range)) as a(wx)
  cross join generate_series(greatest(0, p_cy - p_range), least(v_size - 1, p_cy + p_range)) as b(wy)
  cross join lateral (select a.wx as wx, b.wy as wy) q
  where has_water(p_world, q.wx, q.wy)
  order by (q.wx + 0.5 - creature_x(c)) ^ 2 + (q.wy + 0.5 - creature_y(c)) ^ 2, q.wx, q.wy
  limit 1;
  if x is null then return; end if;
  return next;
end $$;

create or replace function errand_step(p_world uuid, p_id int)
  returns table (gx double precision, gy double precision, want text, wx int, wy int)
  language plpgsql stable as $$
declare c creature; d species_def; dd deed; kind text; rng int;
        v_job record; v_store item; v_crate crate; v_hearth placed; v_spot record;
        v_vessel placed; v_wet record;
begin
  select * into c from creature where world_id = p_world and id = p_id;
  select * into d from species_def where id = c.species;
  select * into dd from deed where world_id = p_world;
  if not found then return; end if;
  kind := d.gathers;
  rng := work_range(c);

  if kind = 'mend' then
    -- Nothing is carried: it works at whichever crate holds the worst of it.
    v_store := damaged_in_stores(p_world);
    if v_store.id is null then return; end if;
    select * into v_crate from crate where world_id = p_world and id = v_store.crate;
    gx := crate_centre_x(v_crate); gy := crate_centre_y(v_crate);
    want := null; wx := v_crate.x; wy := v_crate.y;
    return next;
    return;

  elsif kind = 'hod' then
    select * into v_job from wall_needing(p_world, dd.x, dd.y, rng, c.carrying->>'def');
    if v_job.item is null then return; end if;
    if c.carrying->>'def' is distinct from v_job.item then
      v_store := stocked(p_world, v_job.item);
      if v_store.id is null then return; end if;
      select * into v_crate from crate where world_id = p_world and id = v_store.crate;
      gx := crate_centre_x(v_crate); gy := crate_centre_y(v_crate);
      want := v_job.item; wx := v_crate.x; wy := v_crate.y;
    else
      gx := v_job.x + 0.5; gy := v_job.y + 0.5;
      want := null; wx := v_job.x; wy := v_job.y;
    end if;
    return next;
    return;

  elsif kind = 'stoke' then
    v_hearth := cold_hearth(p_world, dd.x, dd.y, rng);
    if v_hearth.id is null then return; end if;
    if c.carrying is null then
      v_store := fuel_in_stores(p_world);
      if v_store.id is null then return; end if;
      select * into v_crate from crate where world_id = p_world and id = v_store.crate;
      gx := crate_centre_x(v_crate); gy := crate_centre_y(v_crate);
      want := v_store.def; wx := v_crate.x; wy := v_crate.y;
    else
      gx := v_hearth.cx; gy := v_hearth.cy;
      want := null; wx := v_hearth.x; wy := v_hearth.y;
    end if;
    return next;
    return;

  elsif kind = 'water' then
    -- Full: to whichever barrel on the deed has room. Empty: to the water.
    if c.carrying->>'def' = 'water_bucket' then
      v_vessel := thirsty_vessel(p_world);
      if v_vessel.id is null then return; end if;
      gx := v_vessel.cx; gy := v_vessel.cy;
      want := null; wx := v_vessel.x; wy := v_vessel.y;
    else
      select * into v_wet from water_source(p_world, dd.x, dd.y, rng, c);
      if v_wet.x is null then return; end if;
      gx := v_wet.gx; gy := v_wet.gy;
      want := null; wx := v_wet.x; wy := v_wet.y;
    end if;
    return next;
    return;

  elsif kind = 'prospect' then
    -- Nothing is carried and nothing is fetched: the work *is* the walk.
    select * into v_spot from unread_ground(p_world, dd.x, dd.y, rng, p_id, c);
    if v_spot.x is null then return; end if;
    gx := v_spot.x + 0.5; gy := v_spot.y + 0.5;
    want := null; wx := v_spot.x; wy := v_spot.y;
    return next;
    return;

  elsif kind = 'plant' then
    if c.carrying->>'def' is distinct from 'sprout' then
      v_store := stocked(p_world, 'sprout');
      if v_store.id is null then return; end if;
      select * into v_crate from crate where world_id = p_world and id = v_store.crate;
      gx := crate_centre_x(v_crate); gy := crate_centre_y(v_crate);
      want := 'sprout'; wx := v_crate.x; wy := v_crate.y;
    else
      select * into v_spot from planting_spot(p_world, dd.x, dd.y, rng);
      if v_spot.x is null then return; end if;
      gx := v_spot.x + 0.5; gy := v_spot.y + 0.5;
      want := null; wx := v_spot.x; wy := v_spot.y;
    end if;
    return next;
    return;
  end if;
  return;
end $$;

create or replace function errand_do(p_world uuid, p_id int) returns boolean
  language plpgsql as $$
declare c creature; d species_def; kind text; skill_id text; skill double precision;
        v_job record; v_it item; v_hearth placed; v_per double precision; v_tree int;
        v_vessel placed;
begin
  select * into c from creature where world_id = p_world and id = p_id;
  select * into d from species_def where id = c.species;
  kind := d.gathers;
  select g.skill into skill_id from gather_def g where g.id = kind;
  skill := task_skill(c);

  if kind = 'mend' then
    v_it := damaged_in_stores(p_world);
    if v_it.id is null then return false; end if;
    perform worker_learn(p_world, p_id, skill_id, 0.2);
    -- The same bargain the player's own repair makes: damage out, a little
    -- quality with it, and a better hand loses less of it.
    update item set dmg = greatest(0, dmg - (2 + skill / 12)),
        ql = greatest(1, ql - greatest(0.05, 0.6 - skill / 220))
      where id = v_it.id;
    return true;

  elsif kind = 'hod' then
    if c.carrying is null then return false; end if;
    select * into v_job from wall_needing(p_world, c.work_x, c.work_y, 0, c.carrying->>'def');
    if v_job.item is null or v_job.item is distinct from c.carrying->>'def' then return false; end if;
    update wall set needed = jsonb_set(needed, array[v_job.item],
        to_jsonb((needed->>v_job.item)::int - 1))
      where world_id = p_world and level = 0 and dir = v_job.dir and x = v_job.x and y = v_job.y;
    update creature set carrying = null where world_id = p_world and id = p_id;
    perform worker_learn(p_world, p_id, skill_id, 0.25);
    return true;

  elsif kind = 'stoke' then
    if c.carrying is null then return false; end if;
    v_hearth := cold_hearth(p_world, c.work_x, c.work_y, 0);
    if v_hearth.id is null then return false; end if;
    perform placed_settle(v_hearth.id);
    v_per := fuel_value(c.carrying->>'def');
    if v_per is null then
      update creature set carrying = null where world_id = p_world and id = p_id;
      return false;
    end if;
    -- Fed, and lit if it had gone out: a stoker's whole job is that nothing
    -- on the deed is ever cold when somebody comes back to it.
    update placed set fuel = least(fire_capacity(), placed_fuel(placed) + v_per),
        ash = placed_ash(placed), lit = true, since = now()
      where id = v_hearth.id;
    update creature set carrying = null where world_id = p_world and id = p_id;
    perform worker_learn(p_world, p_id, skill_id, 0.2);
    return true;

  elsif kind = 'water' then
    if c.carrying->>'def' = 'water_bucket' then
      -- Pouring it in. Whichever barrel it walked to, if it still has room.
      -- Aliased, and not for tidiness: `kind` is a local in this function and
      -- a column of `placed`, and an unaliased table makes it ambiguous. That
      -- is the sixth time this class has bitten, and the first caught by
      -- running rather than by reading.
      select p2.* into v_vessel from placed p2 where p2.world_id = p_world and p2.kind = 'furniture'
        and p2.x = c.work_x and p2.y = c.work_y and holds_liquid(p2) and not is_well(p2)
        limit 1;
      if v_vessel.id is null then return false; end if;
      update placed set litres = least(liquid_capacity(v_vessel),
                                       placed_litres(v_vessel) + bucket_litres()),
          liquid = 'water', since = now()
        where id = v_vessel.id;
      update creature set carrying = null where world_id = p_world and id = p_id;
      perform worker_learn(p_world, p_id, skill_id, 0.2);
      return true;
    end if;
    -- Filling it. A well is drawn down by what is taken; a shore is not.
    select p2.* into v_vessel from placed p2 where p2.world_id = p_world and p2.kind = 'furniture'
      and p2.x = c.work_x and p2.y = c.work_y and is_well(p2) limit 1;
    if v_vessel.id is not null and not draw_from(v_vessel.id, bucket_litres()) then return false; end if;
    if v_vessel.id is null and not has_water(p_world, c.work_x, c.work_y) then return false; end if;
    update creature set carrying = jsonb_build_object('def', 'water_bucket', 'count', 1, 'ql', 40)
      where world_id = p_world and id = p_id;
    return true;

  elsif kind = 'prospect' then
    perform worker_learn(p_world, p_id, skill_id, 0.22);
    -- The radius grows with what it knows, the same way a player's does, and
    -- what it finds is lit for its keeper: the beast cannot read a map.
    perform read_ground(p_world, p_id, c.work_x, c.work_y, 2 + floor(skill / 20)::int);
    /*
     * And it moves on.
     *
     * `unread_ground` hashes its sixty guesses off the creature and its leg
     * number, which is how everything out here stays the same when it is
     * replayed. A deed worker never touches its leg, though — nothing in the
     * round trip needs one — so the hash was constant and the prospector
     * walked to the same square forty times, learning a great deal about one
     * patch of grass. A reading is a leg, so it counts as one.
     */
    update creature set leg = leg + 1 where world_id = p_world and id = p_id;
    return true;

  elsif kind = 'plant' then
    if c.carrying->>'def' is distinct from 'sprout' then return false; end if;
    if not plantable_tile(p_world, c.work_x, c.work_y) then
      update creature set carrying = null where world_id = p_world and id = p_id;
      return false;
    end if;
    v_tree := coalesce((select id from tree_def where name = c.carrying->>'extra'), 0);
    perform land_set_tile(p_world, c.work_x, c.work_y, tile_id('Tree'));
    perform land_set_data(p_world, c.work_x, c.work_y, v_tree);
    perform land_announce(p_world, c.work_x, c.work_y);
    update creature set carrying = null where world_id = p_world and id = p_id;
    perform worker_learn(p_world, p_id, skill_id, 0.25);
    return true;
  end if;
  return false;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914232600_dispatch15.sql
-- ======================================================================

-- The dispatcher, with barrels, buckets and a well in it.
--
-- Only the two functions, as ever.

create or replace function act_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql as $$
declare d action_def; p player; cx int; cy int; tx int; ty int; t tile_def; aimed text;
begin
  select * into d from action_def where id = p_action;
  if not found then return 'There is no such thing as ' || p_action || '.'; end if;
  select * into p from player where world_id = p_world and uid = p_uid;
  if not found then return 'You are not on this island.'; end if;
  -- Deliberately not "are you busy": asked of queued jobs too. That is rpc_act's.
  if not act_ported(p_action) then
    return 'You cannot ' || lower(d.label) || ' on this island yet.';
  end if;

  aimed := p_target->>'kind';
  if hands_action(p_action) then
    return hands_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- Before the one that lights fires, which is what pointing at furniture has
  -- meant up to now: a barrel is furniture too, and tipping it out is not a fire.
  if liquid_action(p_action) then
    return liquid_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- Working the ground answers for its own reach for the same reason: a
  -- corner is a place rather than a thing, and `drop_dirt` names one.
  if ground_action(p_action) then
    if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
    if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
      return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
    end if;
    return ground_refusal(p_world, p_uid, p_action, p_target);
  end if;
  /*
   * A furnace is brought up to date before anything asks it a question: its
   * fire and its queue together, so that "is anything finished" is answered
   * about now rather than about whenever somebody last stood here.
   */
  if aimed in ('smelter', 'kiln') then
    perform furnace_settle(p_world, nullif(p_target->>'id', '')::bigint);
  end if;
  if item_action(p_action) then
    return item_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if firing_action(p_action) then
    return firing_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if aimed in ('campfire', 'smelter', 'kiln', 'furniture', 'anvil') or fire_action(p_action) then
    return fire_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- A crate is reached for rather than stood in front of, so it answers for
  -- its own reach the way the creatures do.
  if crate_action(p_action) then
    return crate_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- The stake is in your hand and the ground is under your feet: nothing to reach for.
  if p_action = 'found_settlement' then
    return deed_refusal(p_world, p_uid, p_action, p_target);
  end if;
  -- A creature is not at a tile, it is wherever its last leg left it, so the
  -- reach check below cannot answer for it. Both of these do their own; the
  -- fighting ones reach as far as what is in your hand, which is further.
  if creature_action(p_action) then
    return creature_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if fight_action(p_action) then
    return fight_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if not in_reach(p.x, p.y, p_target, d.corner, d.range) then return 'You are too far away from that.'; end if;
  if d.tool is not null and tool_ql(p_world, p_uid, d.tool) <= 0 then
    return 'You need a ' || lower((select coalesce(name, d.tool) from item_def where id = d.tool)) || ' to ' || lower(d.label) || '.';
  end if;
  if build_action(p_action) then
    return build_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    return terrain_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    return gather_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    return farm_refusal(p_world, p_uid, p_action, p_target);
  end if;
  if p_action in ('fish', 'drag_net') then
    return fish_refusal(p_world, p_uid, p_action, p_target);
  end if;

  if exists (select 1 from recipe where id = p_action) then
    return craft_refusal(p_world, p_uid, p_action, nullif(p_target->>'uid', '')::bigint);
  end if;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    if t.dig_yield is null then return 'You cannot dig that.'; end if;
    if land_height(p_world, cx, cy) <= 0 then return 'You cannot dig below the water level.'; end if;
    if land_dirt(p_world, cx, cy) <= 0 then
      return 'That corner is bare rock. Only a pickaxe will take it lower.';
    end if;
  end if;
  return null;
end $$;

create or replace function act_perform(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare d action_def; tq double precision; s double precision; cx int; cy int; tx int; ty int;
        t tile_def; left_dirt int; made_ql double precision; yield text; gained double precision; tool_id bigint;
begin
  if hands_action(p_action) then
    perform perform_hands(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if liquid_action(p_action) then
    perform perform_liquid(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if ground_action(p_action) then
    perform perform_ground(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if build_action(p_action) then
    perform perform_building(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action = 'found_settlement' then
    perform perform_deed(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if creature_action(p_action) then
    perform perform_creature(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if fight_action(p_action) then
    perform perform_fight(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if crate_action(p_action) then
    perform perform_crate(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if item_action(p_action) then
    perform perform_item(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if firing_action(p_action) then
    perform perform_firing(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if fire_action(p_action) then
    perform perform_fire(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('mine', 'chip_corner', 'pack', 'cultivate', 'pave_gravel', 'pave_cobble', 'drop_dirt_here') then
    perform perform_terrain(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('cut_down', 'forage', 'botanize', 'collect') then
    perform perform_gather(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('till', 'plant_seed', 'tend_crop', 'harvest_crop', 'clear_field') then
    perform perform_farm(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if p_action in ('fish', 'drag_net') then
    perform perform_fish(p_world, p_uid, p_action, p_target);
    return;
  end if;
  if exists (select 1 from recipe where id = p_action) then
    perform perform_craft(p_world, p_uid, p_action, p_target);
    return;
  end if;

  select * into d from action_def where id = p_action;
  s := case when d.skill is null then 50 else skill_of(p_world, p_uid, d.skill) end;
  tq := case when d.tool is null then 0 else tool_ql(p_world, p_uid, d.tool) end;

  if p_action = 'dig' then
    cx := (p_target->>'cx')::int; cy := (p_target->>'cy')::int;
    tx := (p_target->>'x')::int;  ty := (p_target->>'y')::int;
    select * into t from tile_def where id = land_tile(p_world, tx, ty);
    select i.id into tool_id from item i
      where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = d.tool
      order by tool_worth(i.ql, i.dmg, i.extra, i.rare, i.bless) desc limit 1;
    if tool_id is not null then perform wear_tool(tool_id); end if;
    if not skill_check(s, d.difficulty, tq) then
      perform tell(p_world, p_uid, 'You fail to dig anything useful.', 'event');
      return;
    end if;
    perform land_set_height(p_world, cx, cy, land_height(p_world, cx, cy) - 1);
    left_dirt := land_dirt(p_world, cx, cy) - 1;
    perform land_set_dirt(p_world, cx, cy, left_dirt);
    if t.turns_to_dirt then perform land_set_tile(p_world, tx, ty, 1); end if;
    -- Dug to the rock, the tile becomes rock and shows the seam under it.
    perform reconcile_around(p_world, cx, cy);
    perform land_announce(p_world, tx, ty);
    if left_dirt <= 0 then
      perform tell(p_world, p_uid, 'Your shovel grates on bare rock.', 'event');
    end if;
    yield := coalesce(t.dig_yield, 'dirt');
    made_ql := product_ql(s, tq);
    perform give(p_world, p_uid, yield, 1, made_ql);
    gained := skill_raise(p_world, p_uid, d.skill, 1);
    perform tell(p_world, p_uid,
      'You dig up some ' || lower((select name from item_def where id = yield)) ||
      '. (QL ' || to_char(made_ql, 'FM990.0') || ')', 'event');
    if gained > 0 then
      perform tell(p_world, p_uid, 'Digging increased by ' || to_char(gained, 'FM0.0000') ||
        ' to ' || to_char(skill_of(p_world, p_uid, d.skill), 'FM990.0000') || '.', 'skill');
    end if;
  end if;
end $$;

select private.lock_doors();

-- ======================================================================
-- 20260914234000_forge.sql
-- ======================================================================

-- The oven, the lantern, and the anvil.
--
-- ## A candle is the sixth thing that will not sit still, and the fussiest
--
-- A fire burns whether anybody is there or not. A crop grows, a well fills, a
-- creature walks. A candle is the first of them that burns *conditionally* —
-- only while the lantern is lit, and a dark lantern in your pack costs you
-- nothing but the weight of it. So it cannot settle from one timestamp: it
-- needs two, `lit` and `lit_at`, and the arithmetic is "what was left, less
-- the seconds since it was struck, but only if it is still burning".
--
-- ## An oven is a fire with a roof on it
--
-- Which is why it needed almost nothing: `placed` already carries fuel, ash,
-- lit and a clock, and the settling is the same settling. What an oven has
-- that a campfire has not is a firebox that takes two hours rather than ten
-- minutes, and a `hearth` flag on its definition that was generated months
-- ago and has never been read by anything down here until now.

/** Whether a lantern is burning, and when it was struck. */
alter table item add column if not exists lit boolean not null default false;
alter table item add column if not exists lit_at timestamptz;

create or replace function forge_action(p_action text) returns boolean language sql immutable as $$
  select p_action in ('fuel_oven', 'light_oven', 'put_out_oven', 'take_ashes_oven',
                      'candle_lantern', 'light_lantern', 'douse_lantern',
                      'place_anvil', 'pick_up_anvil', 'smith')
$$;

/* ------------------------------------------------------------------ *
 * The oven.
 * ------------------------------------------------------------------ */

/** Two hours of firebox, against a campfire's ten minutes. */
create or replace function oven_capacity() returns double precision
  language sql immutable as $$ select 7200 $$;

create or replace function is_oven(p placed) returns boolean language sql stable as $$
  select p.kind = 'furniture'
     and coalesce((select hearth from furniture_def where id = p.sub), false)
$$;

/** How long it will burn, in whichever unit reads best. */
create or replace function oven_burns_for(p_fuel double precision) returns text
  language sql immutable as $$
  select case when round(p_fuel / 60) >= 60 then to_char(p_fuel / 3600, 'FM990.0') || ' hours'
              when round(p_fuel / 60) >= 1 then to_char(round(p_fuel / 60), 'FM990') || ' minutes'
              else to_char(round(p_fuel), 'FM990') || ' seconds' end
$$;

/* ------------------------------------------------------------------ *
 * The lantern.
 * ------------------------------------------------------------------ */

/** Twenty-two minutes of candle, a little more in a well-made lantern. */
create or replace function candle_burn(p_ql double precision) returns double precision
  language sql immutable as $$ select 22 * 60 * (0.7 + least(100, greatest(1, p_ql)) / 160) $$;

/** How far it throws, in tiles: five at the roughest, nine at the best. */
create or replace function lantern_reach(p_ql double precision) returns int
  language sql immutable as $$ select 5 + round(least(100, greatest(1, p_ql)) / 25)::int $$;

/**
 * Seconds of candle left.
 *
 * The charges on the row are what was left when it was last struck or pinched
 * out. A lit lantern has been burning since `lit_at` and the answer is that
 * much less; a dark one is exactly what it says.
 */
create or replace function candle_left(it item) returns double precision
  language sql stable as $$
  select greatest(0, case when it.lit and it.lit_at is not null
                          then coalesce(it.charges, 0) - extract(epoch from (now() - it.lit_at))
                          else coalesce(it.charges, 0) end)
$$;

/** Write down what has burnt, so that whatever happens next starts from now. */
create or replace function lantern_settle(p_item bigint) returns void language plpgsql as $$
declare it item; v_left double precision;
begin
  select * into it from item where id = p_item for update;
  if not found or it.def <> 'lantern' then return; end if;
  v_left := candle_left(it);
  update item set charges = round(v_left)::int,
      lit = (it.lit and v_left > 0),
      lit_at = case when it.lit and v_left > 0 then now() end
    where id = p_item;
end $$;

/** How it reads: dark, lit with so long left, or empty. */
create or replace function lantern_state(it item) returns text language sql stable as $$
  select case when candle_left(it) <= 0 then 'no candle in it'
              when it.lit then 'lit, ' || ceil(candle_left(it) / 60) || 'm of candle left'
              else ceil(candle_left(it) / 60) || 'm of candle in it, unlit' end
$$;

/* ------------------------------------------------------------------ *
 * The anvil, and what is beaten out on it.
 * ------------------------------------------------------------------ */

/** An anvil covers two subtiles each way: four in all. */
create or replace function anvil_subtiles() returns int language sql immutable as $$ select 2 $$;

create or replace function anvil_name(p placed) returns text language sql stable as $$
  select coalesce((select name from metal_def where id = p.sub), 'Iron') || ' anvil'
$$;

/** What a thing is worth to work with: its quality, and how hard its stuff is. */
create or replace function working_ql(p_ql double precision, p_extra text) returns double precision
  language sql stable as $$ select least(100, p_ql * (mat_of(p_extra)).bite) $$;

/** What the anvil is worth to beat on. */
create or replace function anvil_ql(p placed) returns double precision language sql stable as $$
  select working_ql(p.ql, (select name from metal_def where id = p.sub))
$$;

/** Every filling wears the mould, and no mould can be mended. */
create or replace function mould_wear(p_ql double precision) returns double precision
  language sql immutable as $$ select greatest(3, 26 - p_ql * 0.22) $$;

create or replace function mould_uses_left(p_ql double precision, p_dmg double precision) returns int
  language sql immutable as $$ select greatest(0, ceil((100 - p_dmg) / mould_wear(p_ql))::int) $$;

/** What mind logic lends to a hard piece of work. */
create or replace function mind_ease(p_world uuid, p_uid uuid) returns double precision
  language sql stable as $$
  select greatest(0, (skill_of(p_world, p_uid, 'mind_logic') - 20) * 0.2)
$$;

/** How good a piece comes out: the smith, the mould, the metal and the anvil all have a say. */
create or replace function smith_ql(p_world uuid, p_uid uuid, p_skill text,
    p_mould_ql double precision, p_lump_ql double precision, p_anvil_ql double precision)
  returns double precision language sql stable as $$
  select greatest(1, least(100,
    (product_ql(skill_of(p_world, p_uid, p_skill)) + p_mould_ql + p_lump_ql + p_anvil_ql) / 4
    + skill_of(p_world, p_uid, p_skill) / 25))
$$;

/** The lump the smith means to pour: the one they chose, or the first that will do. */
create or replace function smith_lump(p_world uuid, p_uid uuid, p_uid_item bigint) returns item
  language sql stable as $$
  select i.* from item i
  where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
    and not i.locked and exists (select 1 from metal_def m where m.lump = i.def)
  order by (i.id = p_uid_item) desc, i.id
  limit 1
$$;

/** Whether an anvil's four subtiles are free of everything else standing about. */
create or replace function anvil_place_reason(p_world uuid, p_x int, p_y int, p_sx int, p_sy int)
  returns text language plpgsql stable as $$
begin
  if not in_bounds(p_world, p_x, p_y) then return 'That is off the edge of the world.'; end if;
  if has_water(p_world, p_x, p_y) then return 'Not in the water.'; end if;
  if exists (select 1 from placed pl where pl.world_id = p_world and pl.x = p_x and pl.y = p_y
               and pl.sx < p_sx + anvil_subtiles() and pl.sx + (placed_size(pl.kind, pl.sub))[1] > p_sx
               and pl.sy < p_sy + anvil_subtiles() and pl.sy + (placed_size(pl.kind, pl.sub))[2] > p_sy) then
    return 'Something is already standing there.';
  end if;
  return null;
end $$;

/* ------------------------------------------------------------------ *
 * The doors.
 * ------------------------------------------------------------------ */

create or replace function forge_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns text language plpgsql stable as $$
declare p placed; it item; v_mould item; d mould_def; v_lump item;
begin
  if p_action in ('fuel_oven', 'light_oven', 'put_out_oven', 'take_ashes_oven') then
    select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint;
    if not found or not is_oven(p) then return 'That is not an oven.'; end if;
    if not near_piece(p_world, p_uid, p) then return 'Stand next to the oven.'; end if;
    if p_action = 'fuel_oven' then
      select * into it from item where world_id = p_world and holder = 'player' and holder_uid = p_uid
        and not locked and fuel_value(def) is not null
        and (nullif(p_target->>'uid', '') is null or id = (p_target->>'uid')::bigint)
        order by id limit 1;
      if not found then return 'Ovens take the same wood and coal a fire does.'; end if;
      if placed_fuel(p) >= oven_capacity() then return 'The firebox is packed as full as it will take.'; end if;
    elsif p_action = 'light_oven' then
      if placed_lit(p) then return 'It is already burning.'; end if;
      if placed_fuel(p) <= 0 then return 'There is nothing in the firebox. Feed it some wood.'; end if;
    elsif p_action = 'put_out_oven' then
      if not placed_lit(p) then return 'It is not burning.'; end if;
    elsif p_action = 'take_ashes_oven' then
      if floor(placed_ash(p)) < 1 then return 'There are no ashes worth taking yet.'; end if;
    end if;
    return null;
  end if;

  if p_action in ('candle_lantern', 'light_lantern', 'douse_lantern') then
    select * into it from item where world_id = p_world and id = (p_target->>'uid')::bigint
      and holder = 'player' and holder_uid = p_uid;
    if not found or it.def <> 'lantern' then return 'It is gone.'; end if;
    if p_action = 'candle_lantern' then
      if candle_left(it) > 0 then return 'There is still a candle in it.'; end if;
      if pack_count(p_world, p_uid, 'candle') < 1 then
        return 'You have no candles. Two are drawn from two beeswax and a yarn.';
      end if;
    elsif p_action = 'light_lantern' then
      if candle_left(it) <= 0 then return 'There is no candle in it.'; end if;
      /*
       * The browser asks for a tinderbox, and there is no tinderbox in the
       * game — not in `ITEM_DEFS`, not in any recipe, nowhere but this check
       * and the help text that promises it. So a lantern cannot be struck
       * there either, and it cannot be struck here. Ported as written and
       * named out loud rather than quietly fixed: a port that improves on the
       * thing it is porting is a port nobody can check against it.
       */
      if pack_count(p_world, p_uid, 'tinderbox') < 1 then
        return 'You need a tinderbox to strike a light.';
      end if;
      if it.lit then return 'It is already lit.'; end if;
    elsif p_action = 'douse_lantern' then
      if not it.lit then return 'It is not lit.'; end if;
    end if;
    return null;
  end if;

  if p_action = 'place_anvil' then
    select * into it from item where world_id = p_world and holder = 'player' and holder_uid = p_uid
      and def = 'anvil' and not locked
      and (nullif(p_target->>'uid', '') is null or id = (p_target->>'uid')::bigint)
      order by id limit 1;
    if not found then return 'You have no anvil to set down.'; end if;
    return anvil_place_reason(p_world, (p_target->>'x')::int, (p_target->>'y')::int,
      coalesce((p_target->>'sx')::int, 0), coalesce((p_target->>'sy')::int, 0));
  end if;

  select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint
    and kind = 'anvil';
  if not found then return 'It is gone.'; end if;
  if p_action = 'pick_up_anvil' then return null; end if;

  -- Smithing.
  if not near_piece(p_world, p_uid, p) then return 'Stand at the anvil.'; end if;
  select * into v_mould from item where world_id = p_world
    and id = nullif(p_target->>'mould', '')::bigint
    and holder = 'player' and holder_uid = p_uid;
  if not found then return 'Choose a mould.'; end if;
  select * into d from mould_def where id = v_mould.def;
  if not found then return 'Choose a mould.'; end if;
  if d.makes = 'anvil' then return 'An anvil is cast in a smelter, not beaten out here.'; end if;
  v_lump := smith_lump(p_world, p_uid, nullif(p_target->>'uid', '')::bigint);
  if v_lump.id is null then return 'You have no metal to pour.'; end if;
  if v_lump.count < d.lumps then return 'That takes ' || d.lumps || ' lumps.'; end if;
  return null;
end $$;

create or replace function perform_forge(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
  returns void language plpgsql as $$
declare p placed; it item; v_mould item; d mould_def; v_lump item; m metal_def;
        v_per double precision; v_room double precision; v_fits int; v_whole int;
        v_ql double precision; v_mould_ql double precision; v_hard double precision;
        v_rare text; v_made bigint; v_broke boolean; v_sz int[]; v_sx int; v_sy int;
        v_gained double precision; v_left double precision;
begin
  if p_action in ('fuel_oven', 'light_oven', 'put_out_oven', 'take_ashes_oven') then
    perform placed_settle((p_target->>'id')::bigint);
    select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint;
    if not found then return; end if;

    if p_action = 'fuel_oven' then
      select * into it from item where world_id = p_world and holder = 'player' and holder_uid = p_uid
        and not locked and fuel_value(def) is not null
        and (nullif(p_target->>'uid', '') is null or id = (p_target->>'uid')::bigint)
        order by id limit 1;
      if not found then return; end if;
      v_per := fuel_value(it.def);
      v_room := greatest(0, oven_capacity() - p.fuel);
      v_fits := greatest(1, least(least(coalesce((p_target->>'count')::int, 1), it.count),
                                  ceil(v_room / v_per)::int));
      if not consume(p_world, p_uid, it.def, v_fits, it.id) then return; end if;
      update placed set fuel = least(oven_capacity(), p.fuel + v_per * v_fits), since = now()
        where id = p.id;
      perform tell(p_world, p_uid, 'You feed '
        || case when v_fits > 1 then v_fits || ' × ' else 'a ' end
        || lower((select name from item_def where id = it.def)) || ' into the oven. '
        || oven_burns_for(least(oven_capacity(), p.fuel + v_per * v_fits)) || ' of fuel.', 'event');

    elsif p_action = 'light_oven' then
      update placed set lit = true, since = now() where id = p.id;
      perform tell(p_world, p_uid, 'The oven draws and the fire takes hold. '
        || oven_burns_for(p.fuel) || ' of fuel.', 'event');

    elsif p_action = 'put_out_oven' then
      update placed set lit = false, since = now() where id = p.id;
      perform tell(p_world, p_uid,
        'You rake the fire out of the oven. It will keep its heat for nobody.', 'event');

    elsif p_action = 'take_ashes_oven' then
      v_whole := floor(p.ash)::int;
      update placed set ash = p.ash - v_whole, since = now() where id = p.id;
      perform give(p_world, p_uid, 'ash', v_whole, 20);
      perform tell(p_world, p_uid, 'You rake ' || v_whole
        || case when v_whole = 1 then ' lot' else ' lots' end
        || ' of ashes out of the oven. (QL 20)', 'event');
    end if;
    return;
  end if;

  if p_action in ('candle_lantern', 'light_lantern', 'douse_lantern') then
    perform lantern_settle((p_target->>'uid')::bigint);
    select * into it from item where world_id = p_world and id = (p_target->>'uid')::bigint;
    if not found then return; end if;
    if p_action = 'candle_lantern' then
      if not consume(p_world, p_uid, 'candle', 1) then return; end if;
      update item set charges = round(candle_burn(it.ql))::int, lit = false, lit_at = null
        where id = it.id;
      perform tell(p_world, p_uid, 'You set a candle in the lantern. '
        || ceil(candle_burn(it.ql) / 60) || ' minutes of it, at a guess.', 'event');
    elsif p_action = 'light_lantern' then
      update item set lit = true, lit_at = now() where id = it.id;
      perform tell(p_world, p_uid, 'The wick catches and the lantern throws its light '
        || lantern_reach(it.ql) || ' tiles.', 'event');
    else
      v_left := candle_left(it);
      update item set lit = false, lit_at = null, charges = round(v_left)::int where id = it.id;
      perform tell(p_world, p_uid, 'You pinch the wick out. '
        || ceil(v_left / 60) || ' minutes of candle saved.', 'event');
    end if;
    return;
  end if;

  if p_action = 'place_anvil' then
    select * into it from item where world_id = p_world and holder = 'player' and holder_uid = p_uid
      and def = 'anvil' and not locked
      and (nullif(p_target->>'uid', '') is null or id = (p_target->>'uid')::bigint)
      order by id limit 1;
    if not found then return; end if;
    v_sx := least(subtiles() - anvil_subtiles(), greatest(0, coalesce((p_target->>'sx')::int, 0)));
    v_sy := least(subtiles() - anvil_subtiles(), greatest(0, coalesce((p_target->>'sy')::int, 0)));
    values (p_world, 'anvil', coalesce(it.extra, 'copper'),
            (p_target->>'x')::int, (p_target->>'y')::int, v_sx, v_sy,
            (p_target->>'x')::int + (v_sx + 1.0) / subtiles(),
            (p_target->>'y')::int + (v_sy + 1.0) / subtiles(), it.ql, p_uid)
    returning * into p;
    delete from item where id = it.id;
    perform tell(p_world, p_uid, 'You set the ' || lower(anvil_name(p))
      || ' down. Bring a filled mould to it.', 'event');
    perform land_announce(p_world, p.x, p.y);
    return;
  end if;

  select * into p from placed where world_id = p_world and id = (p_target->>'id')::bigint;
  if not found then return; end if;

  if p_action = 'pick_up_anvil' then
    perform give(p_world, p_uid, 'anvil', 1, p.ql, p.sub);
    perform tell(p_world, p_uid, 'You heave the ' || lower(anvil_name(p))
      || ' up onto your shoulder.', 'event');
    delete from placed where id = p.id;
    perform land_announce(p_world, p.x, p.y);
    return;
  end if;

  -- Smithing: the mould, the metal, the anvil and the hands, in that order.
  select * into v_mould from item where world_id = p_world
    and id = nullif(p_target->>'mould', '')::bigint;
  select * into d from mould_def where id = v_mould.def;
  v_lump := smith_lump(p_world, p_uid, nullif(p_target->>'uid', '')::bigint);
  select * into m from metal_def where lump = v_lump.def;
  if v_mould.id is null or d.id is null or v_lump.id is null or m.id is null
     or v_lump.count < d.lumps then return; end if;
  if not consume(p_world, p_uid, v_lump.def, d.lumps, v_lump.id) then return; end if;

  v_mould_ql := greatest(1, v_mould.ql - v_mould.dmg / 2);
  -- Every filling wears the mould, and a hard metal takes more out of it.
  v_broke := v_mould.dmg + mould_wear(v_mould.ql) * (1 + (mat_of(m.name)).difficulty / 30) >= 100;
  if v_broke then
    delete from item where id = v_mould.id;
  else
    update item set dmg = least(100, v_mould.dmg
        + mould_wear(v_mould.ql) * (1 + (mat_of(m.name)).difficulty / 30))
      where id = v_mould.id;
  end if;

  -- The deeper the seam it came out of, the harder it is to beat into shape.
  v_hard := d.difficulty + (mat_of(v_lump.extra)).difficulty;
  if not skill_check(skill_of(p_world, p_uid, d.skill), v_hard, anvil_ql(p),
                     mind_ease(p_world, p_uid)) then
    v_gained := skill_raise(p_world, p_uid, d.skill, 0.25);
    perform tell(p_world, p_uid, 'The '
      || lower((select name from item_def where id = d.makes))
      || ' comes out misshapen and you throw the metal back.'
      || case when v_broke then ' The ' || lower((select name from item_def where id = v_mould.def))
                                || ' cracks through.' else '' end, 'event');
    return;
  end if;

  v_ql := smith_ql(p_world, p_uid, d.skill, v_mould_ql, v_lump.ql, anvil_ql(p));
  v_gained := skill_raise(p_world, p_uid, d.skill, 0.5);
  v_rare := rarity_roll();
  v_made := give(p_world, p_uid, d.makes, d.per, v_ql, m.name, v_rare);
  if v_rare is not null then perform tell(p_world, p_uid, rarity_word(v_rare), 'skill'); end if;
  perform tell(p_world, p_uid, 'You beat out '
    || case when d.per > 1 then d.per || ' ' else 'a ' end
    || lower(m.name) || ' '
    || case when d.per > 1 and right(lower((select name from item_def where id = d.makes)), 1) <> 's'
            then lower((select name from item_def where id = d.makes)) || 's'
            else lower((select name from item_def where id = d.makes)) end
    || ' on the ' || lower(anvil_name(p)) || '. (QL ' || to_char(v_ql, 'FM990.0') || ')'
    || case when v_broke then ' The ' || lower((select name from item_def where id = v_mould.def))
                              || ' cracks through and is done.'
            else ' The mould has ' || mould_uses_left(v_mould.ql, v_mould.dmg
                   + mould_wear(v_mould.ql) * (1 + (mat_of(m.name)).difficulty / 30))
                 || ' fillings left.' end, 'event');
end $$;

create or replace function act_ported(p_action text) returns boolean language sql stable as $$
  select p_action in (
      'dig', 'mine', 'chip_corner', 'pack', 'cultivate',
